INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099092737', 'Mochila Carrinho 2 Compartimentos Paul Frank T03 - Dark Pink', 'Transforme sua rotina com a Mochila Carrinho 2 Compartimentos Paul Frank Classics - Dark Rosa - Pink, uma opção inovadora e estilosa que combina praticidade e conforto ideal para o dia a dia. Fabricada em nailon, este produto garante resistência e durabilidade para acompanhar todas as aventuras. 2 Compartimentos: Organização eficiente para seus itens. Mochila e carrinho 2 em 1: Versatilidade para diferentes situações. Carrinho embutido em alumínio: Estrutura leve e resistente. Alças de costas espumadas e reguláveis: Conforto ideal durante o transporte. Cantoneira de proteção: Segurança para seus pertences. Bolsos laterais em tela com elástico: Acesso rápido a itens pequenos. puxador personalizado: Estilo único e diferenciado. Alça de mão espumada: Conforto ao carregar. Bolso para guardar as alças: Praticidade na arrumação. 2 rodas sem sistema de giro: Estabilidade ao mover.', 699.9, 699.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mlwjctzqeo756a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867958784%2F21099092737', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
