INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45107384999', 'Breve manual de adoração, culto e reforma | Douglas Wilson', 'Recupere a essência transformadora do culto bíblico e fortaleça sua igreja para impactar a cultura! Em Breve Manual de Adoração, Culto e Reforma, Douglas Wilson oferece um diagnóstico preciso e um chamado urgente para a igreja contemporânea abandonar o superficialismo e resgatar a adoração robusta, alegre e pactual que marcou os reformadores. Este manual combina análise teológica profunda com aplicação prática, mostrando como a recuperação da pregação fiel, dos sacramentos significativos e do uso integral dos Salmos pode revitalizar não apenas o culto dominical, mas toda a vida da igreja e sua influência cultural. Mais que um guia litúrgico, é um manifesto estratégico para cristãos que desejam substituir o entretenimento religioso por uma adoração que edifica, transforma e glorifica a Cristo. Principais Benefícios e Destaques: Diagnóstico Preciso: Análise das fraquezas do evangelicalismo moderno no culto Fundamento Reformado: Resgate da teologia de adoração dos reformadores Aplicação Prática: Como implementar culto centrado na Palavra e nos sacramentos Visão Cultural: O culto como motor para transformação societal Chamado à Ação: Convite para abandonar superficialidades e abraçar reverência bíblica Ideal para pastores, líderes de adoração e todos que buscam aprofundar a vida litúrgica da igreja. Adquira já este manual transformador e junte-se à batalha por um culto que honra a Deus e edifica seu povo! Titulo: Breve manual de adoração, culto e reforma Autor: Douglas Wilson Número de Páginas: 104 Acabamento: Capa Brochura Editora: Trinitas', 26.9, 26.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8262s-mlz2zlh2i0aq78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F45107384999', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
