INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52454873257', 'Jogo de Jantar Aura Porcelana Decorada 40 Peças Tramontina', 'Jogo de Jantar Aura Porcelana Decorada 40 Peças Tramontina Os produtos Tramontina Porcelana completam as suas refeições e agregam muito mais beleza a sua mesa. De porcelana Tradicional e exclusiva Tramontina, que é translúcida, tem excelente brancura e brilho, alta resistência mecânica e porosidade próxima de zero, são a escolha ideal para compor uma decoração diferenciada e cheia de estilo! Descrição do produto Marca: Tramontina Coleção: Aura Material: Porcelana Quantidade de peças: 40 Serviço: 8 pessoas Conteúdo: 8x Prato Raso 25 cm 8x Prato Sobremesa 19 cm 8x Prato Fundo 21 cm 8x Conjunto Xícara e Pires 200 ml Uso: Resistente a micro-ondas e lava-louças. Porosidade próxima de zero, evitando a proliferação de fungos e bactérias. Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 1427.57, 644.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-8260o-mjn4n1w5dg5h53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F52454873257', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19498528106', 'Kit 2 Varal de Chão com Abas Retrátil Slim Mor', 'Kit 2 Varal de Chão com Abas Retrátil Slim Mor Para quem vive uma vida agitada e não pode deixar as roupas secando a céu aberto, ou para quem precisa de uma opção por conta da quantidade de roupas o Varal de Chão com Abas Slim ocupa pouco espaço, é prático para montar, desmontar e guardar. Com estrutura em tubo de aço e acabamento em pintura epóxi de alta qualidade o Varal de Chão com Abas oferece resistência e durabilidade e suas exclusivas peças plásticas coloridas são um diferencial que além de trazer maior charme, ajudam a proteger contra corrosão. Ideal para quem busca praticidade e qualidade em um mesmo produto, o Varal de Chão com Abas Slim otimiza seu espaço distribuindo seis varetas resistentes no centro e duas abas com quatro varetas cada com capacidade para até 11 metros de roupas ou 19 Kg distribuídos. Assim que recolher suas roupas você guarda o seu varal dobrado em qualquer lugar. Perfeito para manter a organização da sua casa! Descrição do produto Composição: 02 un Varal Mor 6105 Marca: Mor Material: Polipropileno Material da estrutura: Aço Altura: 89 cm Largura: 49 cm Comprimento: 1,44 m Peso: 2,82 kg Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 333.34, 208.43, NULL, 'Home & Living > Home Care Supplies > Clotheslines & Drying Racks', 'https://cf.shopee.com.br/file/sg-11134201-7qve2-lgzgstryzukg25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F19498528106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398724603', 'Conjunto 6 Cadeiras Isabelle em Polipropileno e Fibra de Vidro Preto Tramontina', 'Conjunto 6 Cadeiras Isabelle em Polipropileno e Fibra de Vidro Preto Tramontina Deixe sua casa mais bonita, confortável e cheia de estilo, com a cadeira Tramontina Isabelle em polipropileno e fibra de vidro preto. Seu design é diferenciado, moderno e versátil e sua fabricação é em polipropileno e fibra de vidro. Uma cadeira que suporta peso até 182 quilos, que garante durabilidade e resistência para seus espaços! Descrição do produto Marca: Tramontina Linha comercial: Isabelle Conteúdo: 6 Peso Máximo Recomendável: 182 kg Material: Polipropileno e Fibra de Vidro Injetado Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 2972.12, 2451.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvm-mc5i7u8vrr4e69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F22398724603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251984519', 'Biscoito de Leite Passatempo', 'O Biscoito Passatempo Leite é um clássico que marcou gerações! Com sabor suave e levemente adocicado, é perfeito para acompanhar o café, o lanche da tarde ou para matar a vontade de um docinho. Com seus desenhos divertidos, estimula a imaginação das crianças e torna os momentos em família ainda mais gostosos.', 4.99, 4.99, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-825ab-mqneldrp5jpn08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554761%2F58251984519', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492824489', 'Garrafa Térmica Lumina Bomba de Pressão Gold 1 Litro TERMOLAR', 'Garrafa Térmica Inox Lúmina 1 Litro TERMOLAR. A garrafa térmica Lúmina é a escolha ideal para quem busca praticidade e elegância no dia a dia. Com 1 litro de capacidade, essa garrafa térmica grande combina um design sofisticado com alta eficiência térmica, perfeita para manter suas bebidas quentes ou frias por longos períodos. Feita com exterior em inox cor Gold (Dourada), a Lúmina não apenas confere resistência, mas também um toque moderno e elegante. A camada protetora de verniz adiciona uma proteção extra, evitando marcas indesejadas e garantindo que sua garrafa esteja sempre impecável. O interior com ampola de vidro proporciona uma conservação térmica diferenciada, mantendo a temperatura das bebidas por mais tempo com a qualidade que só a Termolar oferece. Com a garrafa térmica Lúmina, você terá em mãos um produto que une o melhor da tecnologia térmica com o requinte do inox. Seja para começar o dia com um café quente ou para refrescar-se com uma bebida gelada, essa garrafa térmica inox é a parceira perfeita para todas as ocasiões. A garrafa térmica Lúmina também é uma excelente escolha que pode contar com sua leveza e fácil manuseio. A Rolha Clean torna o processo de servir mais simples e seguro, enquanto o design compacto e a capacidade de 1 litro são ideais para porções em grupo, evitando o desperdício e facilitando o transporte. Características Técnicas: Capacidade: 1 Litro Exterior em Inox Cor: Dourada Bomba de pressão Interior com Ampola de Vidro Não deixa marcas de dedo Dicas de Uso: Para aumentar o desempenho do seu Garrafa Térmica Inox Termolar, siga estas dicas simples: Para líquidos quentes: Escalde a garrafa previamente por 2 minutos antes de adicionar o líquido. Para bebidas geladas: Resfrie o interior da garrafa com água fria antes de utilizá-la. Com essas práticas, você garante a máxima eficiência térmica do seu Garrafa Térmica Termolar, mantendo suas bebidas na temperatura ideal por mais tempo. Lembre-se de EVITAR: Evite choque térmico: Não coloque bebida gelada e em seguida a bebida quente, e vice-versa. Não beba diretamente e nem use aquecedor elétrico. Evite abrir a tampa em excesso para não ocorrer perdas na conservação. Não coloque sua garrafa no micro-ondas, nem na máquina de lavar louças. Não coloque cubos de gelo nas garrafas com ampolas de vidro e inox nem bebidas gaseificadas. Confira todas as orientações de uso e cuidados com a sua garrafa no manual de instruções que acompanha o produto. Dicas de Limpeza: Limpeza Interna Ingredientes: Adicione duas colheres de bicarbonato de sódio e água quente dentro da garrafa. Ação: Deixe agir por 12 horas. Enxágue: Retire o conteúdo e enxágue bem a garrafa. Frequência: Repita a lavagem completa uma vez por semana ou após o uso de café e leite. Armazenamento: Guarde a garrafa aberta para evitar odores e proliferação de mofo. Limpeza Externa: Material: Utilize um pano úmido e sabão neutro. Instruções Adicionais: Para uma limpeza mais eficaz, siga as orientações da bula que acompanha o produto. Importante! Posição de Uso: Garrafas com bomba devem ser usadas na vertical. Não incline ou deite a garrafa. Produtos Proibidos: Não utilize produtos abrasivos ou de limpeza que contenham cloro, ácidos ou soda cáustica. Especificações do produto: Acabamento: Lisa Capacidade: 1L Conservação Térmica: 12h Quente / 24h Frio Dimensões de Produto: (A x L x C) cm: 31,5 x 11,3 x 14,5 Isolamento Térmico: Ampola de Vidro Livre de BPA: Sim Material Atóxico: Sim Material Externo: Inox Sistema de Servir: Bomba de pressão. ATENÇÃO: Garantia de 90 dias diretamente com fabricante TERMOLAR.', 120.0, 112.39, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-820l8-mneg56zgqk1ueb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719930213%2F23492824489', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48706559904', 'Conjunto Cabide Conthey N253037931 Veludo Slim 50 Unidades', 'DESCRIÇÃO RESUMIDA Este conjunto contém 50 unidades de cabides de alta qualidade, projetados para organizar o guarda-roupa com sofisticação e eficiência. Revestidos com veludo de primeira qualidade, os cabides evitam que as roupas escorreguem. Possuem estrutura interna resistente em ABS e contam com um gancho giratório que recebe tratamento antiferrugem, garantindo durabilidade e praticidade no manuseio diário. Características: Marca: Conthey Modelo: N253037931 Especificações: Cor: Preto Material Interno: Estrutura em ABS. Material Externo: Veludo de primeira qualidade. Diferenciais: Gancho giratório com tratamento antiferrugem. Grupo de Estoque: Cadeiras e Móveis. Quantidade: Conjunto com 50 unidades. Unidade de Venda: JG (Jogo). Dimensões: 33 x 14 x 43 cm (AxLxC) Conteúdo da embalagem: 1 x Conjunto com 50 cabides de veludo. Garantia 6 meses Peso 3,3Kg', 167.99, 49.99, NULL, 'Home & Living > Home Organizers > Hangers & Pegs', 'https://cf.shopee.com.br/file/br-11134207-820ld-ml88n9ke8jrac5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F359168917%2F48706559904', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44561008080', 'Mindset | A Nova Psicologia do Sucesso | Carol S. Dweck', 'SOBRE O LIVRO Clássico da psicologia em versão revista e atualizada. Carol S. Dweck, ph.D., professora de psicologia na Universidade Stanford e especialista internacional em sucesso e motivação, desenvolveu, ao longo de décadas de pesquisa, um conceito fundamental: a atitude mental com que encaramos a vida, que ela chama de "mindset", é crucial para o sucesso. Dweck revela de forma brilhante como o sucesso pode ser alcançado pela maneira como lidamos com nossos objetivos. O mindset não é um mero traço de personalidade, é a explicação de por que somos otimistas ou pessimistas, bem-sucedidos ou não. Ele define nossa relação com o trabalho e com as pessoas e a maneira como educamos nossos filhos. É um fator decisivo para que todo o nosso potencial seja explorado. Ficha Técnica Páginas: 312Formato: 16.00 X 23.00 cmPeso: 0.481 kgAcabamento: Livro brochuraLançamento: 18/01/2017ISBN: 978-85-470-0024-0Selo: ObjetivaTradução: S. Duarte', 57.9, 55.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-823px-mokbg1mpv47g3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F44561008080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18836879873', 'Bases da Fé Cristã | Wayne Grudem', 'Para permanecer firme na fé e desenvolver uma base sólida para a vida com Deus, é preciso conhecer os princípios que regem a vida cristã e entender porque eles se mostram tão essenciais. É com esse propósito que Wayne A. Grudem nos convida a refletir sobre os principais fundamentos da fé cristã, afim de trazer auxílio e respostas tanto para novos convertidos como para os mais maduros na caminhada.Com vigoroso foco na Bíblia e questões para serem respondidas individualmente ou em grupo, o autor alia rigor teológico e aplicação prática em uma análise primorosa de vinte conceitos complexos, tais como trindade, pecado, eleição, justificação, expiação, santificação e juízo final. Neste livro, uma versão condensada do best-seller Teologia Sistemática de Grudem, você aprenderá mais sobre a Bíblia, as características de Deus e o que significa ser criado à sua imagem e semelhança, o propósito da Igreja e muito mais, adquirindo, assim, as bases necessárias para fortalecer seu relacionamento com Deus. 208 Páginas 14x21cm', 34.9, 33.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/55e781b7b9df151718598de15b754477', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F18836879873', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55500934618', 'Deus Escolhe os Improváveis | Por que o que Deus Procura é um Coração Disponível', 'Histórias bíblicas e atuais de pessoas improváveis que impactaram gerações. A desconstrução de um pensamento religioso baseado em mérito humano. Encorajamento para confiar na suficiência da graça de Deus. Um convite a se disponibilizar, não a se justificar. 14x21cm 128 páginas', 50.9, 24.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821gf-mgraegvrneh96f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F55500934618', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
