INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259672054', 'Pão de forma sabor chia e macadâmia Wickbold', 'O pão de forma Wickbold sabor chia e macadâmia é uma opção nutritiva e saborosa para o seu dia a dia. Elaborado com ingredientes selecionados, este pão integral combina os benefícios dos grãos com o sabor refinado da chia e da macadâmia, proporcionando uma experiência única a cada mordida. Ideal para o café da manhã, lanches ou para acompanhar suas refeições, o pão Wickbold é uma escolha saudável e deliciosa para toda a família. Além disso, é Vegano e possui o selo de certificação SVB.', 17.49, 14.86, NULL, 'Food & Beverages > Bakery > Breads', 'https://cf.shopee.com.br/file/sg-11134201-825b8-mqnem5kz1wxse3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555006%2F58259672054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
