INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23399124166', 'Prancha Inflável Frutinhas Sortidas - amarelo', 'A Prancha Inflável Frutinhas garante a diversão para os pequenos na piscina. Em formato de prancha, ela conta com alças em suas laterais para os pequenos se segurarem. Produzida em vinil resistente, ela possui duas câmaras de ar independente, duas válvulas de segurança e adesivo para reparo. Pode ser levada desinflada para qualquer lugar, ocupando pouco espaço e garantindo a alegria da garotada. Recomendada para crianças acima de 3 anos e com peso máximo recomendado de 45 Kg, é perfeita para os pequenos curtirem os melhores momentos do verão! Atenção! Este não é um equipamento salva-vidas. Nunca deixe crianças sozinhas perto da água sem supervisão de um adulto.', 35.0, 35.0, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-82580-mgb5xhy41ybw3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23399124166', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23999369327', 'Kit Gotíssima Chuva de Balsamo Gota Dourada Shampoo + Condicionador 300ml', 'O Kit Gotissima Chuva de Balsamo Gota Dourada Shampoo 300ml + Condicionador 300ml foi desenvolvido especialmente para cabelos loiros e com mechas. Com uma fórmula rica em Pantenol, Mel, Quinoa e Bálsamo, ele proporciona hidratação profunda, reconstrução dos fios e um brilho intenso. Se você busca cabelos mais saudáveis, revitalizados e cheios de vida, este kit é a escolha ideal. Benefícios do Kit Gotissima Chuva de Balsamo Reconstrução intensa dos fios danificados. Hidratação profunda para cabelos loiros e com mechas. Redução do ressecamento e melhora da elasticidade capilar. Brilho intenso e aparência saudável. Fórmula com ingredientes naturais e poderosos.', 35.9, 16.0, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-820lt-mlnu59c5acqv84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1382606196%2F23999369327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
