INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17487296005', '4x Luminária Emergência Bivolt Recarregável Lampada 30 Leds', 'Chega de escuridão quando falta energia, com as Lâmpadas de Led toda vez que acabar a força ele acende automaticamente.INFORMAÇÕES TÉCNICAS:Luminária de Emergência 30 LEDS BivoltTempo de Recarga: De 48h em 127V e 24h em 220VPotência: 2WTensão: BivoltTensão (V): 100-240VTemperatura de Cor: 6500K Branca FriaVida útil: 3 horas na potência máxima e 6 horas na potência mínima. 300 recargasFrequência: 50/60HzFluxo Luminoso (lm): 100lm máximo e 55lm mínimoIluminação LedCONTEÚDO DA EMBALAGEM:4 Unidades do Lâmpada de Emergencia 30 leds4NTV771', 83.91, 83.91, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-22100-5jku4wan6giv0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278256920%2F17487296005', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298284733', 'CÂMBIO TRASEIRO SHIMANO DEORE M6100-SGS 12V', 'CÂMBIO TRASEIRO SHIMANO DEORE M6100-SGS 12V SHIMANO DEORE - Câmbio traseiro - SHIMANO SHADOW RD+ - 1x12 velocidades O Câmbio Traseiro Shimano Deore M6100, oferece desempenho avançado nas trocas de marchas com menor tensão nas posições das marchas baixas. Polias maiores de 13D aumentam a eficiência e o gerenciamento da corrente, enquanto a compatibilidade com os cassetes de 12 velocidades da SHIMANO aumentam a faixa. CARACTERÍSTICAS: Câmbio traseiro SHIMANO SHADOW RD+ 1x12 velocidades Trocas de marcha rápidas e precisas para o mountain biking moderno Transmissão silenciosa em todas as posições de marchas >> Tensão menor no câmbio traseiro e na corrente em marchas baixas >> Polia 13D maior >> Transmissão estável em terrenos acidentados >> Design de perfil baixo, que evita danos por pedras >> Estabilizador de corrente, que reduz quedas, batidas e o barulho da corrente ESPECIFICAÇÕES DO PRODUTO - MODELO Nº RD-M6100-SGS - SÉRIE DEORE M6100 - Part Number:IRDM6100SGS *Observações: com pára-choque na cage da polia - Velocidades traseiras 12 - Corrente compatível: HG de 12 velocidades - Tipo de mola topo-normal | SHIMANO SHADOW RD+ - Montagem | Fixação direta (Convencional) - Capacidade total 41D - Pinhão inferior | Máx. 51D - Pinhão inferior | Mín. 51D - Pinhão superior | Máx. 10D - Pinhão superior | Mín. 10D - Buchas dos elos com revestimento fluórico 7 - Roldana | Dentes 13D - Roldana | Parafuso de roldana tipo afundado - Eixo B | Eixo oco', 381.21, 381.21, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdwv-mdovv08qxgis80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1271146358%2F21298284733', NULL, NULL, '2026-