INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299297988', 'Defletor Calha de Chuva Renault Sandero 2008 a 2014 4 Portas Ecoflex', 'Defletor Calha de Chuva Renault Sandero 2008 a 2014 4 Portas Ecoflex A Ecoflex possui uma vasta linha de calhas defletores automotivas para os mais diversos modelos. Utiliza matéria-prima de primeira, 100% acrílico, com tecnologia 3M e instalação simples. Os produtos comercializados pela Ecoflex têm como objetivo trazer conforto e segurança em seu automóvel nos dias de chuva. Com a calha de chuva a água da chuva não entrará no interior do veículo e evita que os vidros embacem. Compatibilidade: • Sandero 2008 a 2014 4 Portas Especificações: • 100% Acrílica; • Proteção e Design; • Contra chuva e sol; • Fixada por Fita Dupla Face 3M; • Não deixa os vidros embaçarem. Conteúdo da Embalagem: • 4 Calhas Defletores de Chuva • 1 Primer (anti-aderente) Garantia: • 5 Anos (defeito de fabricação) Se tiver alguma dúvida a equipe Triangulo Auto Parts estará pronta para lhe atender.', 133.9, 109.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd5b-lwgbkf33d0hp1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1276072791%2F19299297988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493498747', 'Envasadora de Líquidos 100-1000ml com 2 Bicos', 'Apresentamos as Envasadoras NAGANO, a solução ideal para a produção de envase em diversas indústrias, incluindo alimentos, sucos, cervejarias, produtos farmacêuticos, químicos, limpeza doméstica, óleo e pesticidas. Com uma estrutura simples, nossas máquinas oferecem uma precisão excepcional no envase em mililitros, garantindo maior controle e exatidão nos volumes. A facilidade de limpeza e manutenção é uma das principais características das Envasadoras NAGANO. As peças de contato com os materiais são cuidadosamente fabricadas com aço inoxidável, atendendo aos mais rigorosos requisitos de saúde e higiene. Além disso, os componentes de vedação utilizados são de alta qualidade, resistentes às altas temperaturas e proporcionam uma excelente vedação dos produtos. Nossa máquina opera de forma pneumática, o que significa que o cilindro não entra em contato com os produtos a serem envasados. Esse design inteligente facilita ainda mais a limpeza, manutenção e garante a segurança durante todo o processo de produção. As Envasadoras NAGANO são projetadas especificamente para líquidos aquosos, portanto, é importante observar que o uso de líquidos pastosos e outras viscosidades é estritamente proibido para garantir o desempenho e a durabilidade da máquina. Voltar Características Técnicas Nome Produto: Envasadora de Líquidos 100-1000ml com 2 Bicos Fabricante:Nagano EAN:7899646137002 Garantia:03 meses contra defeito de fábrica. Fabricante: Nagano Modelo: NEL10002B Voltagem: 220V Capacidade de envase: 10-1000ML Pressão de ar nominal: 0.4-0.6mpa Velocidade de envase com 2 bicos: 20-60 garrafas/min Precisão de enchimento: 0.5% - 1% Voltar Pesos e Dimensões Dimensões Total do Produto Largura: 43,00 cm Altura: 40,00 cm Comprimento: 105,00 cm Dimensões da Embalagem Largura: 46,00 cm Altura: 34,00 cm Comprimento: 102,00 cm Peso do Produto 55,00 kg', 8032.8, 8032.8, NULL, 'Home & Living > Kitchenware > Sealers', 'https://cf.shopee.com.br/file/sg-11134201-7reqo-m1wt5w0dhoc652', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F23493498747', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
