INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193395112', 'Cropped Feminino Planet Girls Azul Médio', 'O cropped feminino Planet Girls é a peça-chave para um look moderno e cheio de atitude. Confeccionado em tecido leve e macio, ele proporciona conforto e liberdade de movimento. Seja ousada, seja autêntica, seja Planet Girls! O Cropped Feminino Planet Girls é a peça chave para quem adora estar sempre na moda, sem abrir mão do conforto. Com um design moderno e super versátil, ele combina perfeitamente com jeans, saias ou shorts, criando looks incríveis para qualquer ocasião DETALHES QUE VOCÊ VAI AMAR SABER: Ideal para combinar com jeans, saias ou shorts, o cropped Planet Girls é perfeito para diversas ocasiões. Seja para um passeio casual ou uma noite especial, você estará sempre estilosa. Descubra nossa coleção completa e encontre o modelo ideal para você!', 39.99, 39.99, NULL, 'Women Clothes > Traditional Wear > Tops', 'https://cf.shopee.com.br/file/sg-11134201-8259e-mqrycho5btohb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F675392510%2F23193395112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259718270', 'Brilhante Limpeza Total Lava Roupas Pó', 'Brilhante Limpeza Total em pó cuida das suas roupas brancas e coloridas, removendo as sujeiras mais difíceis e protegendo as cores. Sua fórmula com tecnologia Brilho Ativo evita o amarelamento dos tecidos brancos e mantém as cores vibrantes por mais tempo. Rende 12 lavagens e 800g rende igual 1kg. Modo de uso: * Utilize menos de meia xícara (66g) para roupas com sujidade moderada. * Utilize meia xícara (80g) para roupas com manchas ou sujeira extrema. * Tempo de molho ideal: até 2 horas.', 14.49, 14.49, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-8259u-mqnekx4v9pfma7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554900%2F58259718270', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493702903', 'Pneu Aro 18 225/60r18 Pirelli Scorpion HT 104h Xl', 'Você Busca por Um Pneu Eficiente Tanto na Terra Quanto no Asfalto? Então o Pirelli Scorpion Ht é a Resposta para a Sua Dúvida. Desenvolvido para Rodar a Maior Parte do Tempo no Asfalto (70%), o Modelo Vai Bem Em Trilhas Leves (30%), Sendo Perfeito para Você Que Usa Picapes e Ama Versatilidade. Com Desenho Moderno e Otimizado da Banda de Rodagem, o Pirelli Scorpion Ht Conta Com Novos Compostos para Diminuir a Resistência Ao Rolamento. Essa Composição Ajuda na Economia de Combustível. Conteúdo da Embalagem: • - 01 - Pneu 225/60r18 104h Xl S-ht - Pirelli Aplicações de Veículos: • - Charger • - 300c • - Actyon Sport, Actyon Sport Ii • - X-trail, X-trail Ii • - Tiggo 7 • - Bronco • - Koleos • - Toro, Toro Ii • - Outback • - Rav4 v • - Grand Vitara • - Equinox, Equinox Ii • - Cr-v • - Tiggo 7, Tiggo 7 Pro Especifiações Técnicas: • - Marca: Pirelli • - Modelo: Scorpion • - Medida: 225/60r18 • - Largura: 225mm • - Perfil: 60% • - Aro: 18 • - Diâmetro Total Em Mm: 727.0 • - Índice de Peso: 104 - 900 Kg , 104 • - Índice de Velocidade: h - 210 Km/h , v • - Runflat: Nao • - Tipo de Construção: Radial • - Peso: 12.50 • - Extra Load: Sim • - Protetor de Bordas: Sim • - Sidewall: Bsw Letras Pretas • - Tipo de Terreno: Ht • - Desenho: Assimétrico • - Registro Inmetro: 001424/2012 • - Garantia: 5 Anos Contra Defeito de Fabricação • - Observações: Produto Novo. Imagem Meramente Ilustrativa - Vianx - • Este Produto Possui 60 Meses de Garantia. • Imagens Meramente Ilustrativas. • a Garantia é Responsabilidade do Fabricante e Esta Limita Se Apenas á Troca de Qualquer Produto Encontrado Com Defeitos de Fabricação Desde Que Tenha Sido Utilizado Corretamente ou Devidamente Instalado por Um Profissional Qualificado.', 1689.9, 1689.9,