INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294388417', 'DIVIDIR NEM SEMPRE É FÁCIL...', 'DIVIDIR NEM SEMPRE É FÁCIL... Quando o primo da coelhinha vai visitá la, ele faz uma bagunça sem igual puxando e empurrando, saltando e pulando, bufando e gritando até que eles descobrem a importância de dividir.. Informações Adicionais Autor: ANNE, GARLAND Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: DIVIDIR NEM SEMPRE É FÁCIL... Idioma: PORTUGUES Páginas: 32 Edição: 1 ISBN-13: 9788538053125 ISBN-10: 8538053124', 31.92, 28.41, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd3m-lvivf5a65asyd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23294388417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097342780', 'Forno Elétrico Britânia 43L Preto Dupla Resistência BFE43', 'O Forno Elétrico Britânia 43L BFE43 oferece praticidade e eficiência para o dia a dia, com design moderno em preto e detalhes em inox que combinam com qualquer cozinha. Compacto e versátil, é ideal para quem busca desempenho sem ocupar muito espaço. Com dupla resistência e seletor individual, permite escolher entre resistência superior, inferior ou ambas, além da função dourar, garantindo preparos uniformes e evitando que os alimentos fiquem crus ou queimem. O controle de temperatura do Forno Elétrico Britânia varia entre 100 graus e 250 graus, perfeito para diferentes tipos de receitas. A potência de 1500W (127V) ou 2000W (220V) do Forno Elétrico proporciona rápido aquecimento e melhor distribuição de calor. A luz interna e o indicador de funcionamento facilitam acompanhar o preparo sem abrir a porta de vidro temperado, que oferece mais segurança. Para completar, o Forno Elétrico BFE43 acompanha grelha em inox com 3 níveis de altura e bandeja coletora, além de um timer de 60 minutos com desligamento automático, trazendo praticidade e precisão para o preparo de bolos, carnes, pães e muito mais. Acabamento preto com detalhes em inox Capacidade de 43L Potência: 1500W (127V) / 2000W (220V) Dupla resistência com seletor (superior, inferior ou ambas) Controle de temperatura de 100 graus a 250 graus Função dourar Luz interna e luz indicadora de funcionamento Timer de 60 minutos com desligamento automático Grelha em inox com 3 níveis de altura Bandeja coletora incluída Porta em vidro temperado.', 399.9, 369.9, NULL, 'Home Appliances > Kitchen Appliances > Ovens', 'https://cf.shopee.com.br/file/sg-11134201-8258w-mqz9ao3tkw04d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811879342%2F23097342780', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
