INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298499482', 'Sombra Líquida Rosa Metalizada - Liquid Eyeshadow Sparkle Océane Edition 4g', 'Com a Liquid Eyeshadow, Sua Maquiagem Ganha Um Toque de Brilho e Ousadia! Essa Sombra Líquida da Linha Océane Edition Tem Alta Pigmentação e Partículas de Brilho Que Iluminam o Olhar, Proporcionando Um Efeito Marcante e Sofisticado. A Cor Sparkle É Um Rosa Claro Irresistível com Acabamento Metalizado Super Brilhante, Ideal para Quem Busca Um Efeito Moderno e com Muita Cor. e Tem Mais: Sua Fixação Prolongada Garante Um Olhar Impecável Por Horas. Porque a Maquiagem Que a Gente Ama É Aquela Que Dura Muito! A Textura Líquida da Liquid Eyeshadow Proporciona Uma Aplicação Simples e Um Esfumado sem Esforço. para Facilitar Ainda Mais Sua Vida Na Hora de Se Maquiar, a Embalagem Transparente Desta Sombra Permite Visualizar Rapidamente a Cor No Seu Nécessaire. Além Disso, o Pincel Aplicador Garante a Dose Ideal de Sombra Nas Pálpebras, Trazendo Uma Beleza Smart e sem Complicações. E Sabe o Que Mais Você Vai Curtir Sobre a Liquid Eyeshadow? Ela É Um Produto de Maquiagem para Os Olhos Livre de Qualquer Ingrediente de Origem Animal, Sendo Uma Escolha Vegana e Cruelty-Free. Um Produto Perfeito para Quem Busca Estilo e Beleza de Um Jeito Consciente! Por Que Apostar Na Sombra Líquida? Se Você Ainda Não Se Rendeu às Sombras Líquidas, Está Na Hora de Dar Uma Chance! Elas Oferecem Alta Pigmentação, Garantindo Um Efeito Vibrante e Sofisticado. Além Disso, Suas Partículas de Brilho Fixam Bem Na Pele e Ainda Servem Como Base para Sombras em Pó. e Tem Mais: Por Terem Uma Textura Fluida, São Super Fáceis de Aplicar, Sendo Perfeitas para Quem Está Começando No Mundo da Maquiagem. Como Retirar a Sombra Líquida Dos Olhos sem Agredir a Pele? Aplicar a Liquid Eyeshadow É Simples, e Removê-La Também! Basta Usar Um Demaquilante e Aplica-Lo Suavemente Sobre As Pálpebras e Depois Enxaguar. Lembre-Se: Nada de Esfregar com Força, Viu? Assim, Você Cuida da Pele e Dos Cílios sem Causar Irritação.', 89.9, 89.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-8258m-mr25c5s23i1160', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F22298499482', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209112827', 'Torneira Para Banheiro Em Aço Inox Fosco Baixa Amazonas Pingoo - Preto', 'Na hora de construir ou reformar sua casa, todos os detalhes da decoração fazem a diferença. E tudo precisa estar em harmonia, inclusive a torneira. Que além de oferecer maior comodidade para a higiene das mãos, compõe também o projeto da casa. Além do seu design slim e moderno, a Torneira para Banheiro em Aço Inox Amazonas baixa oferece também atributos técnicos indispensáveis para a sua utilização, como funcionamento perfeito em baixa e alta pressão, com arejador que além de garantir economia de água, evita respingos e proporciona conforto para as mãos. Já o volante em alavanca 1/4 de volta que proporciona maior leveza na abertura e no fechamento, ideal para a sua casa. Todo acabamento dela é em Aço inox Fosco 304, que conserva a sua beleza por muito mais tempo. Material muito resistente, de ótima qualidade e melhor custo benefício. ESPECIFICAÇÕES: Marca: Pingoo Dimensões: Verificar nas Imagens do anúncio. Material Predominante: Aço inox 304 Acabamento: Fosco Pressão: 2 a 40 mca Misturador: Não Sistema: 1/4 de volta Bica Giratória: Não Arejador: Sim Spray: Jato Cartucho Cerâmico: Sim Extensível: Não Entrada Filtro: Não Aplicação: Banheiro Instalação: Bancada Furo da Bancada: 2,5 cm Itens inclusos: Anéis de Vedação Sistema de fixação', 89.9, 89.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-81zu2-mn633bfkzoqo9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1758065666%2F58209112827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
