INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999262955', 'BAN STICK DESODORANTE ROLL-ON SEM PERFUME COM 73G', 'Ban Stick Desodorante Sem Perfume 73g: Proteção Sólida e Discreta para Peles Sensíveis O Desodorante Stick Ban Roll-On Sem Perfume de 73g (formato sólido) oferece proteção antitranspirante potente e duradoura (24h), ideal para peles sensíveis ou para quem prefere não misturar fragrâncias. Sua fórmula sólida seca rapidamente e não deixa sensação úmida. Por ser livre de perfume e álcool etílico, o Ban Stick minimiza o risco de alergias e irritações, cuidando da pele delicada das axilas. O formato stick facilita a aplicação, evitando resíduos líquidos. É dermatologicamente testado. Embalagem de 73g econômica e prática. Proteção Sólida e Suave: Fórmula Sólida: Secagem rápida e sensação de axilas secas.Sem Perfume/Álcool: Ideal para peles sensíveis e alérgicas. Proteção 24h: Antitranspirante eficaz de longa duração. 73g Stick: Aplicação prática e econômica. Aplique nas axilas limpas e secas. Espere secar antes de se vestir. A proteção sólida e suave que sua pele sensível precisa, sem fragrância.', 79.41, 79.41, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rd5q-lvnk9yhudvi6bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F19999262955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207963655', 'Cereal Infantil Nestlé Mucilon Milho Sachê 180g', 'Mucilon Milho é um cereal infantil da Nestlé indicado a partir dos 6 meses. Enriquecido com probióticos, vitaminas e minerais, auxilia na imunidade, digestão e desenvolvimento cerebral. Prático de preparar com leite, é ideal para lanches intermediários e contribui para o crescimento saudável do bebê.', 13.32, 13.32, NULL, 'Mom & Baby > Milk Formula & Baby Food > Baby Porridge, Puree & Cereal', 'https://cf.shopee.com.br/file/sg-11134201-82625-mmhl394vdkhtdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547988074%2F58207963655', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
