INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40101143049', 'Livro Completando as aflições de Cristo | John Piper', 'Completando as aflições de Cristo O custo de levar o evangelho para as nações na vida de William Tyndale, Adoniram Judson e John paton Quando, em 430 d.C., Agostinho entregou a liderança de sua igreja, seu sucessor ficou tão devastado pelo sentimento de inadequação para o cargo que declarou: O cisne silenciou, temendo que a voz do gigante espiritual se perdesse com o tempo. Mas, por mil e seiscentos anos, Agostinho não silenciou nem aqueles que, depois dele, anunciaram fielmente a causa de Cristo. A vida deles tem inspirado todas as gerações de crentes e deve despertar em nós uma grande paixão por Deus. William Tyndale Entender a palavra de Deus na linguagem comum do homem foi a paixão propulsora de Tyndale. Ele foi combatido de forma cruel, acusado falsamente, preso e martirizado por causa de seu compromisso. Contudo, motivado pelo exemplo de Cristo, ele estava decidido a que toda pessoa tivesse acesso à verdade. Adoniram Judson Alcançar uma nação totalmente hostil para Cristo a despeito das devastadoras perdas, da mais sombria depressão e da tortura despótica foi o preço pago por Judson para revelar um Salvador poderoso. Sua dedicação inquebrantável à palavra e a fé em Deus moveram-o a ser o precursor de uma força cristã que permanece até hoje. John Paton Despertar a causa das missões mundiais foi o que motivou Paton a incitar colaboradores no mundo inteiro para a colheita e a viver corajosamente entre canibais para que eles pudessem conhecer Jesus. Seu ministério tornou-se uma história que anunciaria o chamado para as missões por gerações ainda por vir. Esses três homens foram embaixadores fiéis que enfrentaram aflições momentâneas e a morte, diariamente, para que outros pudessem colher a eternidade no céu. Que sua fidelidade e sacrifício possam intensificar sua paixão por tornar o amor e o mérito de Cristo conhecidos entre as nações. Título: Completando as aflições de Cristo Subtitulo: O custo de levar o evangelho para as nações na vida de William Tyndale, Adoniram Judson e John paton Autor: John Piper Páginas: 144 Formato: 21 x 14 x 1 cm Peso: 0,180 g. Acabamento: Brochura ISBN: 9788580380040 Editora: Sheed', 35.46, 35.46, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9kr68pjuzp5df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F40101143049', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22330824256', 'Você é ansioso? | Luiz Felipe Pondé', 'Você é ansioso? Reflexões contra o medo Quando decidiu escrever sobre ansiedade, o mundo ainda não conhecia a COVID-19. Mas, sob a antiga normalidade, Pondé entendia a ansiedade como um dos temas mais preocupantes e inquietantes para todos: dos seus jovens alunos universitários aos leitores mais velhos de suas colunas no jornal; de quem se via ansioso por uma falta de sentido na vida aos que mal tinham tempo para perceber isso. Somos todos ansiosos, dizia ele, com razão. À medida que escrevia e a pandemia se espalhava mundo afora, foi percebendo que a ansiedade havia se tornado um marco da nossa era com todos os tipos de medos provocados pelo vírus. O timing para o livro parecia perfeito assim como a sua intenção. A partir da filosofia, sua área de atuação, ele analisa como o comportamento e a cultura têm produzido e lidado com esse novo paradigma que é a ansiedade como perspectiva de mundo. Explica a nossa ansiedade contemporânea e aponta possíveis formas de lidar com ela. Pondé estuda algumas das inúmeras fontes do problema: desde as redes sociais e internet aos avanços da medicina, passando pela emancipação feminina, o desemprego e a competitividade no mercado de trabalho, fatores como o imperativo da felicidade, a coisificação das pessoas e o receio sobre o futuro da democracia. Até porque, segundo ele, a melhor forma de enfrentar a ansiedade é aceitar que ela jamais vai acabar e que atinge a todos nós. Se somos todos ansiosos, temos razão para sermos. Não se trata de um bando de idiotas ansiosos porque são bobos. Trata-se, antes de tudo, de um bando de ansiosos porque são informados. É um consolo... Título: Você é ansioso? Título: Reflexões contra o medo Autor: Luiz Felipe Pondé Páginas: 160 Formato: 21 x 14 x 1 cm Peso: 240 ISBN: 9786555350388 Editora: Planeta', 52.41, 52.41, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-wzdi7fpmihov4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F22330824256', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26183573726', 'Livro Meu Amigo Jesus | Livro de Colorir Com Versículos Bíblicos', 'Livro Meu Amigo Jesus | Livro de Colorir Com Versículos Bíblicos Livro de Colorir Meu amigo Jesus é um livro de colorir encantador, criado para apresentar às crianças alguns dos valores mais importantes do cristianismo, como amor, amizade, fé e bondade. Cada ilustração vem acompanhada de um versículo bíblico inspirador que convida à reflexão, enquanto as crianças se divertem colorindo cenas fofas que transmitem os ensinamentos transformadores de Jesus. Páginas:48 Dimensões:23 x 0.5 x 23 cm', 21.28, 21.28, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7reom-m8metnp93phc4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F26183573726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
