INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098721809', 'Espremedor De Frutas Britânia Bellagio 350 Turbo Preto 110V', 'Espremedor De Frutas Britânia Bellagio 350 Turbo Preto 110VPrepare sucos de maneira rápida e prática com o Espremedor de Frutas Britânia Bellagio 350 Turbo Preto! Com 35W de potência e dupla rotação, o Espremedor retira totalmente o suco da fruta. Conta ainda com peneira, que permite que o suco seja coado rapidamente, preservando os nutrientes e evitando que bagaço e sementes caiam dentro da jarra. Possui também dois cones em tamanhos diferentes para a extração e tampa com ajuste para a jarra. O acionamento é por meio de pressão da fruta sobre o cone, deixando tudo ainda mais fácil. o Espremedor de Frutas Britânia tem uma super capacidade de 1,5L e jarra transparente graduada, para verificar a quantidade de suco preparada. Se você busca praticidade no seu dia a dia, conte com a Espremedor de Frutas Britânia Bellagio 350 Turbo Preto! Principais Características - Potência de 35W - Encaixe rápido e prático da jarra - 2 Cones com dupla rotação - 2 Cones: um maior para alimentos como laranja e um menor para alimentos como limão - Acionamento automático por pressão - Tampa transparente de fácil manuseio - Jarra transparente com graduação - Super Capacidade da jarra 1,5 litros - Possui Peneira - Porta-fio - Baixo nível de ruído. Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas. Especificações Técnicas Marca: Britânia Modelo: Bellagio 350 Cor: Preto Capacidade da jarra: 1,5 L Estado: Potência: 35 W Acionamento: Por pressão Peneira: Sim Rotação: Dois sentidos Velocidades: 1 Altura do produto: 25 cm Largura do produto: 24,5 cm Comprimento do produto: 19 cm Peso do produto: 1,052 kg Altura com embalagem: 26,6 cm Largura com embalagem: 20,5 cm Comprimento com embalagem: 20,5 cm Peso com embalagem: 1,048 kg Garantia: 360 Dias', 186.9, 186.9, NULL, 'Home Appliances > Kitchen Appliances > Juicers, Blenders & Soya Bean Machines', 'https://cf.shopee.com.br/file/sg-11134201-7rdxw-mc7vvb8jeqhl36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23098721809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
