INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5986463216', 'Par Amortecedor Porta Malas Tampa Traseira Passat Até 1988', 'Par Amortecedor Tampa Traseira Porta Malas Passat até 1988 O amortecedor de porta malas é um item de extrema importância para os veículos, tanto para sua comodidade ao colocar bagagens no porta malas, quanto para sua segurança. Não hesite em fazer a substituição desse item, pois sua instalação pode ser feita com muita facilidade. Características do produto: - Compatível com: Passat até 1988 - Comprimento: 57 cm Especificações Gerais: - Fabricado em aço e ferro; - Mola (pressurização) a gás; - Força de expansão ou abertura 40 kg., Conteúdo da Embalagem: - 2 Amortecedores de Porta Malas Passat até 1988. Avisos Importantes: - Garantia: 3 meses; - Valor do Par; - Imagens Meramente Ilustrativas.', 63.9, 63.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/2872052029c7cab8f5d52d004c0835a0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F5986463216', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
