INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198006133', 'Bieleta Original Cofap Sportage Ix35 Hb20 Hb20s Taurus 2011 2012 2013 2014 2015 2016 2017 A 2020', 'Seja Bem-vindo(a)!! É um prazer imenso tê-lo em nosso anuncio. Abaixo algumas informações sobre o Produto e Aplicação. Por fim, conheça um pouco mais sobre a nossa loja. Produtos: 1 Bieleta Dianteria Lado Esquerdo ou Direito Marcas: Cofap Aplicação: Veículo: K. Sportage Motor: Todos Ano: 2011 2012 2013 2014 2015 2016 Veículo: H. Ix35 Motor: Todos Ano: 2010 2011 2012 2013 2014 2015 2016 2017 Veículo: H. Hb20 Motor: Todos Ano: 2012 2013 2014 2015 2016 2017 2018 2019 2020 Veículo: H. Hb20s Motor: Todos Ano: 2012 2013 2014 2015 2016 2017 2018 2019 2020 Veículo: F. Taurus Motor: Todos Ano: 1989 1990 1991 1992 1993 1994 1995 1996 Garantia: 90 dias. É novo, e acompanha nota fiscal Sim! Todos nossos produtos são novos acompanhados de nota fiscal. Sobre a Loja: Somos uma empresa que trabalha exclusivamente com o setor de peças para veículos leves e médios, sendo eles nacionais ou importados. Oferecemos peças com qualidade, prazo de entrega, parcerias com as melhores marcas e eficiência no atendimento. Temos uma equipe de profissionais qualificados para orientar o cliente nas suas mais variadas necessidades relacionadas à manutenção do seu veículo. Oferecemos também um amplo estoque de peças e envios diários. Visamos constantemente o aperfeiçoamento e melhoria dos serviços para a satisfação total do cliente. - ATENÇÃO Para garantia de AMORTECEDORES, só serão aceitas mediante apresentação do certificado enviado junto ao produto. Sem esse documento, não será possível efetuar a garantia do produto. Em caso do não recebimento do certificado, favor nos enviar assim que receber a mercadoria e notar a ausência.', 75.4, 75.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7renz-m1pmt2a6dadb93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373135807%2F22198006133', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497751516', 'Camiseta x Protect 360 Marinho - Mar Negro', '<u>Camiseta x Protect 360 - Mar Negro</u> A Camiseta x Protect 360 da Mar Negro é a escolha definitiva para quem busca conforto, proteção e praticidade em uma única peça. Desenvolvida com a mais alta tecnologia, esta camiseta oferece uma proteção 50 UV, essencial para proteger a pele contra os nocivos raios solares durante atividades ao ar livre. Confeccionada com uma mistura de 90% poliamida e 10% elastano, a Camiseta x Protect 360 proporciona um ajuste perfeito ao corpo, permitindo total liberdade de movimento. A tecnologia 360 de proteção de rosto é um diferencial que garante cobertura adicional, protegendo áreas frequentemente expostas ao sol, como rosto e pescoço. A luvinha de punho integrada é uma inovação que agrega ainda mais valor à camiseta, proporcionando conforto extra e evitando que as mangas subam durante atividades intensas. Seja para pesca, caminhada, corrida ou qualquer outro esporte ao ar livre, a Camiseta x Protect 360 foi projetada para oferecer o máximo de desempenho e proteção. Além de suas funcionalidades técnicas, esta camiseta também se destaca pelo design moderno e elegante, ideal tanto para práticas esportivas quanto para uso casual. A Mar Negro combina estilo e funcionalidade em uma peça que se adapta perfeitamente às suas necessidades, garantindo que você esteja sempre pronto para qualquer aventura. <u>Especificações</u> Marca: Mar Negro Modelo: Camiseta x Protect 360 Material: 90% poliamida, 10% elastano Proteção UV: 50 Tecnologia 360 de proteção de rosto Luvinha de punho', 207.9, 207.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-7rd3k-lwycr8eui5ak28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F18497751516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
