INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44252087194', 'X-Men: A Guerra Magnética (X-Men: As Maiores Sagas)', 'O Mestre do Magnetismo está de volta, e fará o que for preciso para garantir seu objetivo: Um lugar seguro para o Homo superior! À Medida que as ações de Magneto ameaçam o mundo, os X-Men encontram-se no meio de uma guerra pelo futuro da espécie mutante! Mas qual é a conexão de Magneto com seu companheiro de equipe Joseph – e qual será seu destino? Uma nova era começa para a nação de Genosha. Mas quando Magneto finalmente reivindicar seu trono, será que Vampira e Mercúrio ficarão ao seu lado e contra um mundo inteiro?', 170.64, 170.64, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rauw-ma6bvao3n06je3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F44252087194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
