INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494195534', 'Kit 10 un Soquete De Cerâmica Para Lâmpada Hb1/hb5 | 9004/9007 Tarponn', 'Soquete de cerâmica Tarponn 2024 para lâmpada HB1/HB5 | 9004/9007 Características: Maior resistência Fácil instalação Maior vida útil Segurança Encaixe perfeito Aplicação: Reposição de peças Maior resistência à altas temperaturas e fácil adaptação ao seu carro, assim é o Soquete de cerâmica Tarponn 2024 para lâmpada HB1/HB5 | 9004/9007! Com a sua base fabricada em cerâmica, inclui cabo para a emenda facilitada. Indicado para a reposição de peças, conforme a compatibilidade de cada carro, o soquete de cerâmica Tarponn 2024 para lâmpada HB1/HB5 | 9004/9007 promove uma maior vida útil de sua lâmpada e gerando assim, mais segurança, visto que diminui as chances do seu carro ficar no escuro. Além disso, possui um encaixe perfeito para a lâmpada. Conheça mais do Soquete de cerâmica Tarponn 2024 para lâmpada HB1/HB5 | 9004/9007! Ficha técnica: Linha: Standard Material: Cerâmica Base: HB1/HB5 | 9004/9007', 108.01, 86.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc9okdse6acg01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1564173886%2F22494195534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257085866', 'Gloss Labial Fran By Franciny Ehlke Franboesa', 'Gloss Labial Fran By Franciny Ehlke Franboesa 5g Gloss labial com brilho intenso e acabamento vinílico que realça a beleza dos seus lábios. Enriquecido com extrato de framboesa, óleo de semente de girassol e vitamina E, promove hidratação profunda e maciez, garantindo conforto e proteção durante o uso. Embalagem do gloss labial com design de morango vermelho, fundo rosa e branco Design exclusivo em formato de morango com tampa e anel rosa metálico, unindo charme e praticidade para aplicação precisa. Gloss labial em forma de morango vermelho, com tampa e anel de metal rosa, sobre fundo branco Fórmula vegana, livre de parabenos e glúten, que hidrata e protege os lábios com aroma delicado de framboesa. Modo de uso Aplique o gloss diretamente nos lábios com a ponteira chubby para cobertura uniforme e brilho intenso. 1 Preparação Certifique-se de que os lábios estejam limpos e secos para melhor aderência do gloss. 2 Aplicação Use a ponteira chubby para espalhar o gloss suavemente sobre os lábios. 3 Cobertura Garanta uma camada uniforme para obter brilho e hidratação prolongados. 4 Finalização Deixe o produto secar naturalmente e reaplique conforme desejar para intensificar o efeito. Características e benefícios Este gloss labial oferece uma combinação perfeita de brilho intenso e hidratação profunda. Sua fórmula enriquecida com extrato de framboesa antioxidante, óleo de semente de girassol e vitamina E proporciona lábios macios e protegidos, enquanto o design prático facilita a aplicação precisa e confortável. 1 Brilho Intenso Acabamento vinílico que realça o brilho natural dos lábios com efeito duradouro. 2 Hidratação Óleo de semente de girassol e vitamina E mantêm os lábios hidratados e macios. 3 Aplicador Prático Ponteira chubby que garante uma aplicação uniforme e fácil em uma única passada. 4 Fórmula Vegana Produto livre de parabenos, glúten e ingredientes de origem animal, respeitando sua pele e o meio ambiente. Especificações Técnicas Fran By Franciny Ehlke Gloss Labial Brilho Vinílico Fórmula Vegana Hidratação Profunda 5g Sobre a marca Fran By Franciny Ehlke Fran By Franciny Ehlke é conhecida por unir beleza e cuidado em produtos que valorizam a autenticidade e o bem-estar.', 94.99, 94.99, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-82614-mlxvjjc4f94z61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1587699638%2F58257085866', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
