INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22291099411', 'Chuveiro Ducha Para Camping Psicina Casa Telescopia Vonder Resistente Oferta Premium Oferta Top', '🚿 Chuveiro Ducha Telescópica para Camping/Piscina – VONDER Leve praticidade e conforto pra qualquer lugar com essa ducha telescópica da VONDER. Ideal pra praia, camping, piscina ou até uso em casa, ela garante um banho rápido e eficiente onde você precisar 🌊🏕️ Com altura ajustável e cabeça articulada, você tem total controle da direção da água e mais comodidade no uso. O suporte com tripé proporciona estabilidade, deixando tudo firme e seguro 🔥 📦 Itens Inclusos 1 Ducha telescópica 1 Suporte/tripé com parafuso de fixação ⚙️ Especificações Técnicas Altura regulável: 1,65 m a 2,20 m 📏 Material da cabeça: Plástico ABS Material da haste: Alumínio Conector: 1/2" (para mangueira – não inclusa) Cabeça articulada com 12 posições 🔄 Uso: Praia, camping, piscina e áreas externas 💥 Por que escolher este produto? Prática e fácil de montar Ajuste de altura para melhor conforto Cabeça articulável para melhor direcionamento da água 🚿 Estrutura leve, resistente e portátil Ideal para uso externo e viagens 🏕️ Produto novo e original Pronta entrega e envio em até 24 horas 🚚 Compra 100% segura IMPORTANTE: SUA SATISFAÇÃO GARANTIDA! ✔️ -----> Entrega assegurada pela Shopee com garantia', 174.9, 174.9, NULL, 'Home & Living > Bathrooms > Showerheads & Bidet Sprays', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mby7xznzuonte7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F22291099411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298054471', 'Suporte Com Rodas Para Mangueira Acompanha Mangueira Trançada 15 Metros Vonder', 'Suporte Com Rodas Para Mangueira Acompanha Mangueira Trançada 15 Metros Vonder. O Suporte com Rodas para Mangueira com Mangueira 15m Vonder é a solução perfeita para quem busca praticidade ao regar plantas, lavar veículos e limpar áreas externas. Este conjunto inclui um suporte para mangueira com rodas e uma mangueira para jardim, oferecendo eficiência e facilidade de uso. Destaques do Produto: Suporte com Rodas para Mangueira: Capacidade: Mangueiras de 1/2": Até 45 metros. Mangueiras de 5/8": Até 30 metros. Material: Base em plástico ABS. Alça metálica tubular para transporte e apoio. Funcionalidade: Acompanha 2 conectores 1/2" (fêmea) e 1 conector principal (macho). Possui manivela para enrolar a mangueira facilmente. Cor: Amarelo e preto. Massa Aproximada: 1,91 kg. Montagem Rápida: Não necessita de ferramentas. Mangueira para Jardim de 15m: Material: PVC resistente. Dimensões: Diâmetro interno: 7/16" (11,1 mm). Espessura da parede: 1,8 mm. Pressão Máxima de Trabalho: 140 lbf/pol². Cor: Transparente. Acessórios Inclusos: 1 conector 3/4". 1 adaptador 3/4" para 1/2". 1 esguicho plástico reto. Massa Aproximada: 1,146 kg. Aplicações: Irrigação de jardins. Lavagem de veículos. Limpeza de quintais e áreas externas. Com o suporte ergonômico e mangueira durável, você terá um aliado prático e eficiente para suas tarefas diárias!', 350.0, 350.0, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rffs-m33gyxfg6p8204', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F23298054471', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
