INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256673188', 'Areia Biodegradável Bionature 4kg - Super Premium - Receba em até 4horas', 'Areia Higiênica Wisecat Bionature Biodegradável Super Premium 4 Kg ____________________________________________________________________________ CARACTERÍSTICAS PRINCIPAIS Marca Wisecat Formato de venda Unidade Peso da unidade 4kg Material Derivado de Mandioca. É biodegradável Sim Fragrância Sem Fragrância _____________________________________________________________________________ A nossa loja está a mais de 10 anos no mercado, com produtos originais e com nota fiscal. _____________________________________________________________________________ AREIA HIGIÊNICA WISECAT BIONATURE BIODEGRADÁVEL SUPER PREMIUM 4 KG A Areia Higiênica Bionature Super Premium redefine os padrões de higiene para gatos ao oferecer uma solução inovadora, biodegradável e 100% natural. Desenvolvida a partir de derivados de mandioca, esta areia proporciona uma alternativa ecologicamente correta e conveniente para a higiene do seu gato, cuidando simultaneamente do meio ambiente. PRINCIPAIS BENEFÍCIOS: - Biodegradável e 100% Natural - Torrão Sólido Instantâneo. - Eliminação Eficiente de Odores. - Textura Macia e Confortável. - Monitoramento Renal. - Livre de Componentes Químicos Nocivos. INDICAÇÃO DE USO: - Para gatos de todas as raças e idades (filhotes, adultos e seniores) - Indicada para gatos de pequeno, médio e grande porte MODO DE USO: 1 - Coloque na bandeja uma camada de 5cm de altura. 2 - Remova o torrão formado pela urina ou fezes, repondo a quantidade retirada. 3 - Lave a bandeja e a pá coletora com detergente neutro ou desinfetante de acordo com sua necessidade. 4 - Complete novamente a bandeja, sempre que estiver abado do recomendado. 5 - Para um descarte correto do torrão, orientamos que descarte os torrões da Wisecat Bionature no lixo orgânico. _____________________________________________________________________________ Gostou? Não perca tempo, garanta já o seu!', 70.9, 42.9, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/sg-11134201-8261p-mlnxwhezl1xg26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760624219%2F58256673188', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899368698', 'Furolisin Diurético Vetnil Comprimido 10 mg para Cães e Gatos - 10 Comprimidos', '- Uso oral em seu amiguinho; - Potente ação diurética; - Rápida absorção do organismo; - Formulado com furosemida que possui propriedades vasodilatadoras, aumentando a perfusão renal e diminuindo a pré-carga cardíaca; * Consulte sempre o Médico Veterinário de sua confiança para o uso apropriado deste produto. Leia a bula ou informações descritas na embalagem. Detalhes O Diurético Vetnil Furolisin Comprimido 10 mg é um diurético a base de furosemida. Sua principal ação é no segmento ascendente da alça de Henle. A furosemida inibe a reabsorção de sódio, potássio e cloreto na porção espessa da alça de Henle, levando à diurese do seu pet. Dicas Especiais Modo de usar Produto indicado para cães e gatos, na dose de 2 a 6 mg/kg, por via oral.', 18.88, 13.62, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/sg-11134201-7rdyt-lz83kkj92pmk38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F20899368698', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
