INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799600145', 'Kit 12 Trincha 2” Cabo Vermelho Roma', 'A Trincha 2" Roma é a ferramenta ideal para quem busca um acabamento de qualidade em projetos de pintura com excelente custo-benefício. Com cerdas selecionadas, ela proporciona uma aplicação precisa e uniforme de tintas à base de látex e acrílicas, sendo perfeita para diversos usos. Seu cabo laranja é ergonômico, proporcionando maior controle e conforto durante o uso. Vantagens: Cerdas selecionadas para acabamento uniforme e suave. Ideal para tintas látex e acrílicas. Excelente relação preço/qualidade. Cabo ergonômico, proporcionando mais conforto e controle durante o uso. Dados técnicos: Marca: Roma Cor: Vermelho (cabo) Dimensões: 2" (largura da trincha) Tipo de cerdas: Selecionadas Aplicação: Tintas látex e acrílicas Garantia: Garantia de 3 meses pelo fabricante.', 130.8, 64.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5ymlt3bpghe88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F20799600145', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
