INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20597971230', 'Brinquedo Sortido Mini Carrinho do Sonic - Sonic Pull Back - Candide 4609', 'OBSERVAÇÃO: PRODUTO SORTIDO E UNITÁRIO, MODELO SERÁ ENVIADO DE ACORDO COM A DISPONIBILIDADE DO ESTOQUE. Apresentamos os incríveis Miniveículos Pullback Sonic, uma coleção de mini veículos de metal com os personagens mais amados do Sonic, como Sonic, Tails, Knuckles, Robotnik e Shadow. Esses miniveículos vão te surpreender com sua função especial de puxar para trás e soltar, proporcionando uma velocidade impressionante. Com cinco sortimentos únicos para descobrir, os fãs do Sonic têm a oportunidade de conhecer todos esses miniveículos e reviver aventuras emocionantes ao lado de seus personagens favoritos. Feitos com materiais de alta qualidade, esses carrinhos são duráveis e vão adicionar um toque especial à sua coleção. Prepare-se para a diversão em alta velocidade! Cada miniveículo Pullback Sonic é um verdadeiro tesouro para os fãs de todas as idades. Não perca a chance de ter todos os personagens e criar suas próprias histórias cheias de adrenalina. Adquira hoje mesmo os Miniveículos Pull back Sonic e leve a ação e a emoção do Sonic para o próximo nível! Tipo de Produto: Produto unitário Gênero: Meninos Faixa Etária Recomendável: Acima de 3 anos Origem: Importado Certificado: INMETRO Dimensões da Embalagem: (aproximado) C:2,5cm / L:13cm / A:16cm Características: - Marca: Candide - Modelo: 4609 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 1 Veículo de Brinquedo Sortido; Carrinho - Brinquedo - Sonic - Carrinho de brincar do Sonic', 19.9, 19.9, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7reox-m1x1qrymsdod3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F20597971230', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
