INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893588469', 'Base Baú Physical Branco Casal (138x188x39) - Ortobom', 'Base Baú Physical Corino Branco Casal (138x188x39) As Bases Baú Physical Corino Ortobom unem funcionalidade e design moderno, criando a combinação perfeita com o seu colchão e com a decoração do ambiente. Seu visual contemporâneo agrega sofisticação e praticidade ao quarto. O espaço interno do baú oferece uma solução inteligente para armazenamento, ajudando a manter o quarto organizado e aproveitando melhor o ambiente. Produzida com madeira 100% de reflorestamento, reforçando o compromisso da Ortobom com a sustentabilidade e o uso responsável dos recursos naturais, além de espuma de poliuretano, que garante toque agradável, firmeza e durabilidade prolongada. Possui 42,5 cm de altura total — sendo 39 cm da base e 3,5 cm dos pés — oferecendo suporte seguro para o colchão. Seu suporte é de até 150 kg por pessoa (além do peso do colchão). A base baú conta com pistões de amortecimento, alça de sustentação e kit de pés em PVC, que permitem abertura estável, segura e sem esforço. Com design elegante, a Base Baú Physical Ortobom é a solução ideal para quem busca conforto, praticidade e espaço em um único produto.', 1362.9, 1199.35, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rati-mb48k2df30pd3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1537615778%2F23893588469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
