INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40056479538', 'Jogo Chaves Philips e Fenda Sata Isoladas VDE 7pç ST09303', 'Jogo Chaves Philips e Fenda Sata Isoladas VDE 7pç ST09303 Descrição: - As chaves de fenda SATA possuem todos os recursos profissionais que você espera, além de inovações de ponta; - Não importa se você é técnico em manutenção ou eletricista, às vezes, você quer algo a mais nas suas ferramentas; - A Sata atendeu essa necessidade, com as chaves de fenda isoladas certificadas pela VDE, com classificação de até 1000 V para segurança; - Vá além com ferramentas de alto desempenho, só da SATA. Vantagens: - Pontas magnetizadas; - Isolação de 1000V para correntes alternadas; - Certificação VDE 1000V; - Processo de fabricação conforme norma IEC 60900, com ensaios de aderência, de pressão, elétrico, de impacto e de flamabilidade; - Pontas oxidadas; - As chaves podem ser penduradas diretamente pelo cabo, que possui um furo para esta função; - Chaves são feitas de materiais tri-componente. Dados Técnicos: - Marca: Sata; - Modelo: ST09303; - Quantidade de peças: 7; - Certificação VDE; - Isolamento de 1000V para correntes alternadas. Itens Inclusos: - 03 Chaves philips: PH0 x 60mm / PH1 x 80mm / PH2 x 100mm; - 04 Chaves fenda: 2,5 x 75mm / 4 x 100mm / 5,5 x 125mm / 6,5 x 150mm.', 188.0, 125.96, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbija9qni1gi9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F40056479538', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992987609', 'Chinelo 3D Patrick - Bob Esponja', 'Mesmo morando no fundo do mar e pisando em areia você sente um desconforto no pé? A gente te ajuda! Com esse chinelo seus rolês pela Fenda do Biquini ficam mais confortáveis e completos! Não importa se você vai caçar água viva ou ir ao Siri Cascudo, esse chinelo acompanha todos os seus passos! A pantufa é importada e é uma excelente companhia para os dias de home office! Mas não para por ai, em dias gelados em casos de extrema preguiça e previsão de cama e série para o dia todo, essas pantufas te acompanham em todos os seus episódios favoritos! Além de quentinha, é muito confortável e possui sola emborrachada! Especificações: Altura: 12cm| Comprimento: 33cm| Largura: 43cm| Peso; 0,455gr Adulto ou Criança - Unissex Tamanho P: Calça 33 - 35 Tamanho M: Calça 36 - 38 Tamanho G: Calça 39 - 41 Tamanho GG: Calça 42 - 44 Cuidados e recomendações de uso: Lavar a mão com água fria. Não usar alvejante. Secar na horizontal. Secagem natural. Não passar e limpar a seco.', 144.9, 144.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-825zx-mm0scubvc3k0f6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F22992987609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
