INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492240326', 'Desodorante Aerossol Dove 150ml', 'O Desodorante Antitranspirante Aerossol Dove Original ajuda a reduzir a irritação da pele que pode ser causada após a depilação, possui uma fragrância sutil que ajuda na sensação de limpeza e refrescância durante o dia todo, pensando sempre no melhor para a suas axilas. Com ¼ de creme hidratante para o cuidado da pele, oferece até 48 horas de proteção antitranspirante Modo de uso: Agite o frasco, segure-o a cerca de 15cm de distância de suas axilas (mais ou menos na altura do seu cotovelo) eAplique com um jato rápido. #html-body [data-pb-style="646BA64F17AFC"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64F17B10"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 26.71, 26.71, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkz93kjwt3jc45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22492240326', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19677028663', '6x Reparo Compatível Driver JBL Selenium D250x Corneta 8 Ohms 100W Som Automotivo', 'Kit com 6 reparos compatíveis para driver JBL Selenium D250x e D-250x. Produto indicado para reposição em corneta e sistemas de som automotivo, com impedância de 8 Ohms e potência de 100W, oferecendo ótimo custo-benefício para manutenção e substituição. Especificações Técnicas: • Impedância: 8 Ohms • Potência: 100W • Aplicação: reparo para driver • Compatível com JBL Selenium D250x • Compatível com D-250x • Indicado para corneta e som automotivo • Quantidade: 6 unidades Conteúdo da Embalagem: • 6 Reparos para Driver D250x / D-250x Importante: • Verifique o modelo do seu driver antes da compra • Confirme medidas, impedância e compatibilidade antes da instalação • Recomendamos instalação por profissional especializado reparo driver d250x, reparo jbl selenium d250x, reparo compatível d250x, kit 6 reparos driver, reparo driver corneta 8 ohms, reparo driver 100w, reparo d 250x, reparo corneta jbl selenium, reparo som automotivo, diafragma d250x, reparo driver paralelo, reparo driver d250 selenium', 111.2, 111.2, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-820ld-mnn8l2z9x3b4e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F19677028663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297150529', 'Patins Inline Flexx 3.0 Ajustável Laranja (33-36) Bel', 'Andar de patins é mais que um esporte que inclui manobras radicais, é um ótimo exercício físico que estimula a coordenação motora, equilíbrio, agilidade e resistência. O patins inline Flexx 3.0 da BEL é ideal para grandes aventuras; além de possuir um alto padrão de estilo e qualidade. Bel em seus melhores momentos! Informações: · In-line - 4 rodas em fila · Tuck e chassi em Alumínio · Botas em Poliéster, extra confortáveis com revestimento interno · Rolamento ABEC-7 · Rodas em PU de alta performance', 361.9, 361.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Boardsports', 'https://cf.shopee.com.br/file/sg-11134201-7ratq-maispi3cv52a60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F21297150529', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899264904', 'Wella Professionals Oil Reflections Light - Óleo Capilar 30ml', 'Óleo para todos os tipos de cabelos, especialmente os finos. Wella Professionals Oil Reflections Reflective Light nutre instantemente os fios, sem pesar, com efeito luminoso. Sua fórmula foi desenvolvida especialmente para dar uma sensação de fios mais densos e com brilho saudável. O Óleo Capilar Wella Professionals Oil Reflections Light é o que chamamos de produto multifuncional. Isso porque ele pode ser usado antes da química para proteger dos danos, como pré-shampoo e tratamento noturno. Como usar: Aplique nos fios quando desejar, comprimento e pontas. Você pode usá-lo adicionando algumas gotas à máscara da linha, aumentando a reparação e garantindo maior maleabilidade. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 81.9, 81.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-825zo-mjydmh8pubr69e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F23899264904', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898422552', 'Pastilha de Freio Dianteiro Ka 1997 a 2015 Syl 1229', 'Descrição: A Pastilha de Freio SYL 1229 é uma peça que serve na posição Dianteiro, lados Direito / Esquerdo dos veículos FORD FIESTA, KA. Confira abaixo as especificações e aplicações detalhadas. Especificações Técnicas: - Comprimento: 141,3 mm - Espessura: 16,1 mm - Lado: DIREITO / ESQUERDO - Largura: 44,3 mm - Posição: DIANTEIRO - Sistema de freio: SISTEMA TEVES Aplicação: - FORD FIESTA 1.0 L 8V SOHC L4 1996 a 2010; - FORD FIESTA 1.3 L 8V SOHC L4 1995 a 1999; - FORD KA 1.0 L 8V SOHC L4 1997 a 2015; - FORD KA 1.3 L 8V SOHC L4 1997 a 2000; Sobre o Peça Aí: Com o Peça Aí, você acha a peça certa para cada carro e compra num só lugar. É o maior estoque digital de peças do país! São mais de 100 mil itens originais e de reposição à sua disposição. Importante: • Dúvidas: Caso tenha qualquer dúvida sobre as aplicações do produto, entre em contato conosco. • Instalação Profissional: Recomendamos que a instalação do produto seja realizada por profissionais especializados. • Responsabilidade: Não nos responsabilizamos por montagens mal realizadas e equívocos de instalação." • Produto novo, original e com nota fiscal.', 48.95, 48.95, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/sg-11134201-7rfgp-m96mmxo2w3he03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343288194%2F23898422552', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
