INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594491125', 'Barrinha de Proteina - 1 Barra 45g Doce de Leite - Eat Clean', 'A barra de proteína vegana da Eat Clean é a combinação perfeita de pasta de castanha de caju com proteína vegetal, resultando em barrinhas proteicas, cremosas e com um sabor surpreendente. Cada unidade contém 45g com 12g de proteína. 100% à base de plantas, sem açúcar, sem glúten, sem lactose e vegana! Como Tomar Consumir até 2 unidades ao dia ou conforme orientação profissional. Ingredientes Blend proteico (proteína isolada de ervilha, proteína concentrada de arroz), pasta de castanha-de-caju EAT CLEAN sabor doce de leite, cobertura vegana sabor chocolate branco, ganache vegano sabor doce de leite, xarope de tapioca, pasta de tâmara, polidextrose, castanha-de-caju granulada, sal rosa do Himalaia, emulsificante (lecitina de girassol - INS 322), aromatizantes naturais, antioxidantes (extrato de alecrim e vitamina E). ALÉRGICOS: CONTÉM CASTANHA-DE-CAJU. PODE CONTER: AMENDOIM, AMÊNDOA, AVEIA, AVELÃ, CASTANHA-DO-BRASIL, MACADAMIA, NOZES, PECÃ E PISTACHE. NÃO CONTÉM GLÚTEN. Os ingredientes utilizados são veganos. Baixo teor de açúcares. Este não é um alimento com valor energético reduzido. ...', 25.5, 25.5, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/sg-11134201-824hn-mfot8yzpgiru74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F23594491125', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693528594', 'Reparo Bico Injetor Gm Montana 2009 a 2012 - 191366 - 1245', 'Reparo Bico Injetor Gm Montana 2009 a 2012 191366 1245 1.0/1.4 8v Flex - (Multi Point) (4 filtros + 8 O''rings) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 48.59, 48.59, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7reqf-m2h5w0ksho7004', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22693528594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
