INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201748944', 'Kit Haskell Tutano Vegetal 3 Peças - Nutrição Profunda para Cabelos Frágeis e Ressecados', 'O Kit Haskell Tutano Vegetal é a escolha perfeita para quem deseja restaurar a força, o brilho e a maciez dos cabelos frágeis e ressecados. Com fórmula vegetalizada e altamente nutritiva, ele promove um tratamento completo e duradouro, devolvendo aos fios sua vitalidade natural. A combinação de ativos vegetais fortalece a fibra capilar, repõe os óleos essenciais e cria uma barreira protetora contra o ressecamento, deixando o cabelo mais resistente, maleável e com brilho intenso. Ideal para uso frequente, o kit é perfeito para quem busca resultados de salão em casa. Benefícios: • Tratamento profundo com ativos de origem vegetal • Fortalecimento da fibra capilar • Nutrição intensa e brilho natural • Toque macio e fios mais resistentes • Ação emoliente e regeneradora O KIT CONTÉM: • Shampoo Tutano Vegetal 1L: limpa suavemente, devolve a vitalidade e prepara os fios para os tratamentos. • Condicionador Tutano Vegetal 1L: promove hidratação e desembaraço imediato, fortalecendo os fios. • Máscara de Tratamento Tutano Vegetal 900g: hidrata profundamente, proporciona brilho e maciez com efeito prolongado. Indicação: cabelos frágeis e ressecados Direção olfativa: floral frutal', 361.7, 361.7, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-822xf-mi34vz96yg3s98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1562135680%2F58201748944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
