INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799605665', 'Pedal de Freio Gp Biz 125 11/19 Biz 100 12/15 Biz 100i 16/22', 'PEDAL FREIO GP7 MOTO HONDA BIZ 125 2011 Complete o conjunto de freio da sua moto com o Pedal de Freio GP, Trazendo ainda mais segurança durante a pilotagem. Esta é uma peça produzida em liga metálica inoxidável, ou seja, possui alta qualidade e excelente performance. Compatível: - HONDA BIZ 125 - 2011 A 2019 - HONDA BIZ 100 - 2012 A 2015 - HONDA BIZ 100i - 2016 A 2022 Peças de excelente qualidade, e ótimo custo benefício. Ouse Sempre Com O Melhor Para A Sua Moto! >ATENÇÃO Garantia de 3 Meses. Imagens Meramente Ilustrativas. Recomendamos que a instalação seja feita por profissional especializado. Não nos responsabilizamos pelo mau uso ou aplicação do produto.', 72.45, 68.83, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6sgljvjxenb02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F937893879%2F21799605665', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299715327', 'Óleo Semi-Sintético - Mineral + Alquilbenzeno B5.2 Bitzer UCAPR001501 5 Litros', 'Óleo Semi-Sintético - Mineral + Alquilbenzeno B5.2 Bitzer UCAPR001501 5 Litros O Óleo Semi-Sintético Mineral + Alquilbenzeno B5.2 Bitzer UCAPR001501 é a escolha ideal para quem busca desempenho superior e confiabilidade em sistemas de refrigeração e climatização. Com 5 litros de capacidade, este óleo foi formulado para proporcionar excelente lubrificação e proteção para compressores e outros componentes essenciais, garantindo maior eficiência e vida útil dos seus equipamentos. Sua combinação de óleos minerais e alquilbenzeno oferece uma performance otimizada, mesmo em condições de operação intensa. A fórmula especial do óleo semi-sintético Bitzer UCAPR001501 garante resistência superior à oxidação e estabilidade térmica, o que resulta em um desempenho prolongado e confiável. Com a viscosidade adequada, ele reduz o atrito e o desgaste das peças internas, melhorando a eficiência do sistema e reduzindo custos com manutenção. Este produto foi desenvolvido para atender às necessidades de quem busca eficiência e menor impacto no consumo de energia, mantendo os sistemas de refrigeração funcionando de forma estável e eficaz. Além disso, o Óleo Semi-Sintético Bitzer UCAPR001501 é altamente versátil e pode ser utilizado em uma ampla gama de compressores de sistemas de climatização, proporcionando excelente proteção contra a corrosão e o desgaste. Sua embalagem de 5 litros é prática e ideal para quem precisa de um óleo de alta performance, que garante a operação ideal dos seus equipamentos de forma eficiente e econômica. Com esse produto, você assegura a máxima qualidade e a durabilidade dos seus sistemas de refrigeração.', 839.9, 839.9, NULL, 'Home Appliances > Large Household Appliances > 