INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492879568', 'Motocultivador Gasolina 7HP com Rodas e Enxadas TK90R TEKNA', 'Motocultivador Gasolina 7HP com Rodas e Enxadas TK90R TEKNA Detalhes do produto: Desenvolvido para atender diversas necessidades, este equipamento chega para simplificar e aprimorar suas atividades com motor a gasolina de 7HP permite atingir uma velocidade de até 8,4 km/h. Versátil, ele pode ser utilizado na agricultura familiar, horticultura, no nivelamento de superfície em quadras esportivas de areia após a chuva, no transporte de carretinha – suportando até 350kg – e em diversas outras aplicações. Detalhes Técnicos: Guidão rotacional e regulável; Filtro de ar banhado a óleo; 24 lâminas para uma aração do solo; Entregue de fábrica com as enxadas modulares montadas; Disco de arado, para aprimorar o acabamento nas extremidades dos canteiros; Farol integrado, para facilitar as atividades noturnas ou em locais com pouca iluminação; Rodas de 8", para otimizar o deslocamento até a área de cultivo; Porta objetos, prático para armazenamento de ferramentas e acessórios; Embalagem de madeira, facilitando o empilhamento e transporte do produto. Marca: TEKNA Referência: 2512101 Garantia: 3 Meses *Imagens meramente ilustrativas.', 3352.9, 2629.9, NULL, 'Home & Living > Gardening > Lawn Mowers', 'https://cf.shopee.com.br/file/sg-11134201-7rcdh-lsjt9p6inx1n94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F23492879568', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8831972155', 'Maçaneta Interna Porta Esquerda Fiesta Após 2002 - Cor Preta', 'Envio Rápido: Encomende até 12h30 e tenha seu pedido ENVIADO no mesmo dia! Nosso compromisso é com a sua satisfação e com a entrega ágil dos produtos. Esta maçaneta de cor preta é a solução ideal para peças desgastadas ou danificadas, oferecendo funcionalidade e estilo ao seu veículo. Receba seu produto rapidamente e renove a aparência do seu Fiesta em pouco tempo. Aplicação: Compatível com os seguintes veículos da Ford: Ecosport 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011 e 2012 Fiesta de 2002 até atualmente Especificações: Marca: Universal Número da Peça (Part Number): 2S65.A22601.BF.37Q Código Universal do Produto (EAN): 7895272307918 Código IPI: 87082999 Código NCM: 8871 SKU Universal: 30791 Renove a funcionalidade e o visual do seu Fiesta com a Maçaneta Interna da Porta Esquerda. Faça seu pedido agora e aproveite a entrega rápida para ter seu veículo pronto para novas aventuras!', 44.14, 39.73, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/fab67a74eb40c049348f633fd8b322c0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290883399%2F8831972155', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
