INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252400236', 'Kit 12 Litros Mercon Lv + Filtro Óleo Do Câmbio Ford Ranger', 'Somos concessionária autorizada Ford e trabalhamos exclusivamente com peças genuínas. Todas as peças são novas, originais de fábrica, acompanham nota fiscal e possuem garantia. Compre com segurança, procedência garantida e atendimento especializado. Por se tratar de peça original Ford, eventuais atendimentos de garantia podem ser realizados em qualquer concessionária autorizada Ford do Brasil, conforme as condições do fabricante. VEÍCULOS COMPATÍVEIS: Ford: • Ranger 2017 2.2 16V Automático 6R80 • Ranger 2018 2.2 16V Automático 6R80 • Ranger 2019 2.2 16V Automático 6R80 • Ranger 2020 2.2 16V Automático 6R80 • Ranger 2021 2.2 16V Automático 6R80 • Ranger 2022 2.2 16V Automático 6R80 • Ranger 2023 2.2 16V Automático 6R80 DESCRIÇÃO: KIT 12 LITROS DE MERCON LV + FILTRO DE OLEO DA CAIXA DE TRANSMISSÃO AUTOMÁTICA FORD RANGER. APLICAÇÃO: FORD RANGER DUPLA 4X4 COM TRANSMISSAO AUTOMATICA DE 6 VELOCIDADES (6R80) COM DATA DE FABRICAÇÃO DE 12/03/2012 EM DIANTE FORD RANGER GARANTIA: 3 meses Antes de realizar a compra, verifique cuidadosamente se a peça é compatível com o seu veículo, considerando modelo, ano e versão. Em caso de dúvida, utilize o campo de perguntas e, se desejar, envie o número do chassi. Nossa equipe poderá consultar e confirmar a compatibilidade da peça com o seu veículo antes da compra.', 3248.98, 3248.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-81zv9-min2c4mco2rm27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676459102%2F58252400236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40830814218', 'Aspirador De Pó Vertical 2 Em 1 Portátil Gaabor 650w', 'Aspirador de Pó Vertical Gaabor 2 em 1 – Potência e Praticidade para sua Limpeza O Aspirador de Pó Vertical Gaabor 2 em 1 Portátil é perfeito para quem busca uma limpeza prática, rápida e eficiente no dia a dia. Com design 2 em 1, ele pode ser utilizado como aspirador vertical para pisos e tapetes ou portátil para sofás, carros, móveis e cantos difíceis. Sua potente sucção de 650w remove poeira, pelos de animais e sujeiras com facilidade, enquanto o sistema de tripla filtragem HEPA ajuda a manter o ar mais puro e saudável. Leve, ergonômico e silencioso, o Aspirador Gaabor oferece mais conforto durante o uso. Além disso, conta com bocal articulável 90° e reservatório removível de 1,5L, garantindo mais praticidade na limpeza completa da casa. Destaques * Aspirador vertical e portátil 2 em 1 * Potência de 650w * Tripla filtragem HEPA * Ideal para pelos de pets e poeira * Bocal articulável 90° * Reservatório removível de 1,5L * Leve, silencioso e fácil de usar', 219.99, 124.99, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/br-11134207-820m8-mo5vncqk1ssi68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F342086228%2F40830814218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
