INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252434854', 'Tubo Isolante Esponjoso Vix Blindado 3/8 Preto', 'Tubo Isolante Esponjoso Vix Blindado 3/8 PretoO Tubo Isolante Esponjoso Vix Blindado 3/8 Preto é fabricado em polietileno expandido, em diversos diâmetros e espessuras. Promove a praticidade da instalação com excelente acabamento, podendo ser utilizado em novas ou em tubulações já existentes. Protege a tubulação contra corrosão, e resistente à vários agentes químicos. Devido ao seu alto nível de atuação, geram uma economia de até 80% da energia consumida em tubulações de refrigeração, ar condicionado e água quente. Aplicação: Utilizado para isolamento térmico de tubos de cobres em refrigeração e climatização', 2.66, 2.66, NULL, 'Home Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-82607-mkzabu40dts023', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1323031590%2F58252434854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
