INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11195360633', 'Viseira Capacete Para Capacetes Norisk FF370 / FF345 (Articulado) Antirrisco 2.2mm', 'Viseiras Polivisor Antirrisco 2.2mm: Proteção e Visibilidade para Seu Capacete! Compatível com Capacetes: Norisk: FF370 / FF345 Para capacete estilo Robocop — ou seja, modular, com queixeira articulada. - Tamanhos: 56, 58, 60 e 62 Conteúdo da Embalagem: 01 Viseira Polivisor Cristal Antirrisco 2.2mm Características: - Tratamento Antirrisco: Resistente a riscos e arranhões - Material: Policarbonato de alta qualidade com 2.2mm de espessura - Proteção UV: Proteção contra raios UV para uma visão segura - Durabilidade: Alta durabilidade e resistência para um uso prolongado - Transparência: Alta transparência para uma visão clara e precisa - Fácil Instalação: Fácil de instalar e remover Benefícios: - Proteção: Proteção contra riscos e arranhões para uma visão segura - Visibilidade: Alta transparência para uma visão clara e precisa - Durabilidade: Alta durabilidade e resistência para um uso prolongado Instruções de Uso: - Limpe com sabão neutro e água corrente - Evite solventes químicos, gasolina ou produtos abrasivos - Não aplique vernizes ou adesivos - Troque sua viseira regularmente para garantir a segurança e visibilidade Marca Confiável: A Polivisor é a maior fabricante de viseiras para capacetes no Brasil, com mais de 20 anos de experiência e investimentos constantes em tecnologia para desenvolver produtos de alta qualidade. Importante !! - Não nos responsabilizamos pelo mau uso do produto. - Antes da compra verifique se a viseira é realmente compatível com seu capacete!', 57.9, 51.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmet Visor Shields', 'https://cf.shopee.com.br/file/br-11134207-820lk-mp9ev12r5jb7c2', 'https://shope.ee/an_redir?o