INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13376398136', 'CACHACA SAGATIBA 700ML', 'Cachaça Sagatiba Cristalina Prata 700 ml. A CACHAÇA QUE REINVENTOU A CACHAÇA. Sagatiba Cristalina é aquela cachaça brasileira que você já conhece, só que diferente. Ela é feita com um moderno e inovador processo de destilação (a primeira marca a produzir dessa maneira!): a Multidestilação. Nesse processo, destilamos a cachaça mais de uma vez, separando qualquer impureza. O resultado é um líquido puro e cristalino, que cai bem com qualquer mistura, desde a tradicional caipirinha até drinks! CARACTERÍSTICAS: Produzida no Interior de Minas Gerais. Graduação alcoólica: 38% vol. Volume: 700 ml.', 59.9, 59.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/a98a313ff386a5868e367ed87e061bc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F13376398136', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
