INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15922560763', 'Caramanhola Linea 700ml Azul c/ Suporte Garrafa para Bike', 'A Caramanhola Térmica PTK Linea 700ml é ideal para manter-se hidratado nos pedais, possui parede térmica para manter a temperatura da sua bebida, por até 3 horas. Fabricada em materiais flexíveis garante maior praticidade para o uso durante seus pedais e melhor fixação junto aos suportes de garrafa de quadro. Conta com formato ergonômico, a caramanhola Linea da PTK permite melhor encaixe junto aos suportes de garrafa, garantindo maior fixação mesmo nos terrenos mais difíceis de Mountain Bike (MTB). Assim como, conta com bico e tampa desenvolvidas especialmente para o ciclismo, mantém o fluxo de líquidos com melhor vazão e sem desperdícios. Possui protetor de bico, evitando o acúmulo de sujeira durante seus passeios, provas e treinos. Especificações da Caramanhola Térmica PTK Linea 700ml - Fabricação de alta qualidade - formato ergonômico, mantém o encaixe junto aos suportes muito mais seguros e com maior facilidade para beber enquanto pedala; - Bico ergonômico - maior fluxo de líquidos e menos desperdícios; - Volume máximo comportado: 700ml; - Capacidade térmica - leve sua bebida favorita com a temperatura ideal por muito mais tempo sem alterações; - Boca larga - reabasteça e higienize com mais praticidade.', 49.9, 49.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/9273cd0cba02296962496dc4429e6afc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F15922560763', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
