INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794627876', 'Condicionador Seda Amino-Silk Complex Toque de Seda 250ml', 'Condicionador Seda Amino-Silk Complex Toque de Seda - Cabelos Sedosos, Fortes e Com Brilho O Condicionador Toque de Seda é enriquecido com 4% Amino-Silk Complex, um poderoso mix com a proteína da seda, que se conecta com as fibras capilares, resultando em um cabelo mais forte e com toque macio. Em combinação com o shampoo, este produto capilar oferece o combo perfeito para seu momento de lavagem com controle prolongado do frizz e garante 1,5x mais maciez e sedosidade. A nova linha Toque de Seda é ideal para quem busca um aliado no controle do frizz e não abre mão de fios sedosos com brilho intenso e movimento. Todos os produtos são enriquecidos com Amino-Silk Complex, a novidade de Seda para entregar cabelos mais macios por 1 semana. Conheça e experimente a linha completa para resultados ainda mais incríveis e desfrute de um cabelo mais sedoso que desliza como a seda. Benefícios: - Condicionador Toque de Seda, fórmula com 4% Amino-Silk Complex. - Amino-Silk Complex é um complexo que se conecta com as fibras capilares, resultando em um cabelo com fios mais fortes e com toque macio. - Condicionador seda, controle de frizz prolongado - Cabelos mais macios por 1 semana. - Fios 1,5x mais sedosos. Como Usar? Após o Shampoo, aplique uniformemente nos cabelos molhados do meio às pontas, massageie suavemente e depois enxágue. Sobre Seda Seda é uma das marcas mais amadas quando o assunto é cuidado capilar, oferecendo soluções inovadoras para todos os tipos de cabelo. A marca é referência em hidratação, nutrição e reconstrução dos fios, sempre combinando ciência e beleza.', 28.74, 28.74, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-821do-mgi9dejfy39k7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23794627876', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898311677', 'Sabonete Íntimo em Barra Protex Delicate Care 85g', 'Protex Cuidado Íntimo Fresh Equilibrium é um produto desenvolvido especialmente para cuidar da saúde da mulher que oferece proteção delicada e sensação prolongada de frescor. Contém exclusivo Protex System com ácido láctico, que fortalece a barreira natural da área íntima para manter o pH equilibrado e uma sensação prolongada de frescor. E sua fragrância é suave.', 20.39, 20.39, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd3q-m76yvkfgu03w40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F22898311677', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099276515', 'Duo Controle de Frizz Hidratei: Óleo Multifuncional Capilar 60ml + Leavin Controle Absoluto 60ml', '- Controle Absoluto oferece um super poder antifrizz que deixará seus fios resistentes à umidade como nunca antes. Descubra o segredo para fios impecáveis com o Controle Absoluto. Seus cabelos resistentes à umidade como jamais imaginou. Nossa fórmula exclusiva, quando termo ativada, proporciona um brilho fantástico, uma leveza incrível e uma sedosidade indescritível. É um poderoso ativo antifrizz que age desde o primeiro uso, alinhando os fios de maneira surpreendente. Além disso, o Controle Absoluto conta com silicones tecnológicos, que proporcionam um efeito liso prolongado sem deixar resíduos indesejados. Esses silicones restauram a hidrofobicidade dos cabelos danificados, melhoram a penteabilidade, reparam as pontas duplas, diminuem o frizz e o volume, deixando seus cabelos perfeitamente alinhados e irresistivelmente macios ao toque. - Óleo Multifuncional Hidratei Sete benefícios, uma fonte de poder. Cabelo impecável sete dias da semana. Produto com ações de reparação, umectação, termoproteção, pré-poo, selagem, redução de frizz e efeito gloss. Vegano, versátil e muito prático. O Óleo Multifuncional é perfeito para quem corre contra o tempo em busca de concluir todas as tarefas do dia e ter o cabelo bonito como prioridade. Mesmo com a rotina agitada, agora é possível ter fios hidratados, nutridos e protegidos 24 horas por dia, 7 dias da semana. Em um único óleo, sete benefícios e sua fonte de poder.', 294.9, 159.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rcdz-ltft0xzgwypm78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F555452587%2F18099276515', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
