INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398400164', 'Conjunto De Sinos De Metal 26 cm Infantil Phx Mini 8K-1A', 'O Conjunto de Sinos de Metal 8K-1A PHX é uma excelente escolha para crianças e iniciantes no mundo da música. Feito com sinos de metal de alta qualidade e acabamento colorido, o conjunto oferece uma sonoridade rica e envolvente. Acompanha uma baqueta, facilitando o uso e garantindo a produção de sons claros e melodiosos. Ideal para atividades educativas, brincadeiras musicais e desenvolvimento da percepção sonora.', 174.11, 161.93, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Percussion Instruments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8evufkisqa920', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F297648539%2F22398400164', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
