INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093508084', 'Mascara de Cilios Mari Maria Lash Up', 'Descrição: A Mascara de Cilios Mari Maria Lash Up com nossa fórmula 5 em 1, a máscara de cílios LashUP proporciona volume desde a primeira aplicação e combinada ao pincel macio e flexível curva e alonga cílio a cílio, da raiz às pontas, garantindo definição e alongamento excepcionais, sem acumular produto. Além disso, é resistente ao suor, à umidade e não transfere, permitindo que você vivencie a experiência de um olhar marcante e sofisticado o dia todo. Curvatura precisa, Cor intensa, Comprimento alongado, Definição extrema e Volume máximo. MODO DE USAR: Aplique diretamente nos cílios, penteando os fios da raiz até ponta. Reaplique até alcançar o efeito desejado. Busque fazer o movimento de "ziguezague" para não concentrar o produto. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 6g. Composição: Sua fórmula contém cera de carnaúba, manteiga de karité e óleo de canola que proporcionam hidratação para os fios. Efeito cílios postiços. É bom saber: hipoalergênico, dermatologicamente testado, oftalmologicamente testado, adequado para todos os tipos de pele, não irritante, sem parabenos, sem perfume, sem crueldade. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 63.99, 54.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-7renq-m21fhf1sna5ee6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F23093508084', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
