INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204219600', 'The Penguin (Batman Returns) – DC Theatrical Deluxe – 7” WV2 – McFarlane', 'Figura de 7” do vilão Penguin inspirada no filme Batman Returns (1992), integrante da linha DC Theatrical Deluxe Wave 2, produzida pela McFarlane. Apresenta escultura detalhada fiel ao visual cinematográfico, com expressão marcante, figurino icônico e pintura de alta qualidade. Possui múltiplas articulações que permitem poses variadas e acompanha acessórios característicos do personagem. Ideal para fãs da DC Comics e colecionadores que buscam uma peça diferenciada, com forte presença e perfeita para exibição.', 349.99, 349.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-82622-mk1433vxlqtca7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1191775191%2F58204219600', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44555050361', 'Kit Churrasco Jumbo Brinox Faca 4,5" + Garfo de Mesa em Aço Inox', 'O Kit Churrasco Jumbo Brinox reúne dois utensílios essenciais para quem valoriza cortes precisos e firmeza ao servir carnes. Produzidos em aço inox de alta durabilidade e com cabos em polipropileno, oferecem resistência, conforto no manuseio e fácil limpeza — ideais para uso doméstico ou profissional. 1. Faca para Churrasco 4,5" Jumbo Aço Inox – Brinox Perfeita para cortes eficientes de carnes, a faca conta com lâmina afiada, resistente à corrosão e design ergonômico para mais segurança e controle. Material: Aço inox Cabo: Polipropileno Dimensões: 2 x 23 x 2 cm Cuidados: Lavar com detergente neutro e esponja macia. Secar imediatamente. Evitar abrasivos. 2. Garfo de Mesa para Churrasco Jumbo – Brinox Garante firmeza ao servir e manusear carnes. Fabricado em aço inox polido, é higiênico, durável e confortável no uso. Espessura: 1,8 mm Uso: Doméstico / Profissional Material: Aço inox Cabo: Polipropileno Dimensões: 20 x 2,3 x 1,5 cm Peso: 34 g Cuidados: Produto perfurante. Manter fora do alcance de crianças. Conteúdo da Embalagem: - 01x Faca para Churrasco Jumbo 4,5" – Brinox (2554/010) - 01x Garfo de Mesa para Churrasco Jumbo – Brinox (2554/011)', 26.85, 26.85, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-8262i-mjr59kv9uvic61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F44555050361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40810815550', 'Pulverizador Snow Foam 3X1 2LT Overvision OVER2426 Spray Automotivo Veicular Limpeza Carro Moto', 'Pulverizador Snow Foam 3X1 2LT Double Action é um pulverizador de compressão manual profissional de altíssima qualidade. Pulverize todos os tipos de produtos químicos e espumantes. Produz uma espuma espessa e aderente. Fácil de usar! Basta encher com seu shampoo automotivo favorito (não fornecido na embalagem), diluir com a quantidade correta de água, bombear a alça para aumentar a pressão e pressionar o gatilho para aplicar o produto no veículo. Sua trava do gatilho e a capacidade de 2L fornecem um trabalho contínuo por mais tempo. Economize tempo: Leque de 55° que amplia a área de aplicação tornando a aplicação mais ágil. Características: - Marca: Overvision - Modelo: OVER2426 Imagens Meramente Ilustrativas Conteúdo da Embalagem: - 01x Pulverizador Snow Foam pulverizador snow foam 3 em 1 Overvision, Overvision OVER2426 pulverizador, pulverizador espuma lavagem automotiva, foam sprayer manual 2 L, pulverizador automotivo snow foam, gerador de espuma 2 litros Overvision, pulverizador manual espuma densa, lavadora espuma snow foam, acessório limpeza carro espuma, pulverizador profissional espuma automotiva, aplicador espuma snow foam Overvision, pulverizador com trava gatilho foam, pulverizador 3 em 1 limpeza carro, pulverizador espuma espuma aderente veículos', 75.52, 64.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvv-mcs65u69d7pw2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F40810815550', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
