INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599040575', 'Pelúcia Puffy Bob Esponja', 'Depois de um dia cheio de aventuras, você precisa de uma mãozinha na hora de descansar? A gente te ajuda! Com enchimento e tecido em Poliéster é a melhor companhia para um cochilinho depois de um dia cheio de aventuras de tirar o folego! Não importa se você é trouxa ou bruxo, essa almofada te acompanha em todas as suas aventuras! O produto é importado, com detalhes incríveis que vão fazer você se apaixonar! Se depois de um dia corrido, tudo o que você precisa é de um abraço fofinho e uma companhia agradável, a gente te ajuda! Com tecido e enchimento em Poliéster, possui um toque muito macio e é incrivelmente fofinho! É a melhor companhia para você repousar a sua cabeça e descansar! Não importa se a aventura é no sofá ou na cama, essa pelúcia vai aonde você for! Especificações: Altura: 28cm| Largura: 30cm| Comprimento: 26cm| Material: Poliéster| Enchimento: Poliéster Cuidados e recomendações de uso: Passar com temperatura máxima de 110° (sem vapor). Não alvejar. Permitido uso de centrifuga e máquina secadora. Temperatura máxima de lavagem 40°.', 124.9, 124.9, NULL, 'Home & Living > Furniture > Cushions', 'https://cf.shopee.com.br/file/sg-11134201-825af-mg5gt015z40a41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F23599040575', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
