INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22132044154', 'Massinha Play Doh Mundo Mágico dos Unicórnios - Hasbro F3616', 'DIVERSÃO MÁGICA: As crianças a partir dos 3 anos podem criar divertidas histórias em um incrível mundo de fantasia com este kit Play-Doh 10 FERRAMENTAS: Os cortadores incluídos ajudam as crianças criar histórias incríveis de unicórnios, dragões e castelos nas nuvens 3 POTES DE DUAS CORES: Cada pote contém duas cores diferentes, incluindo 1 pote de Play-Doh com glitter para um toque extra de magia PRESENTE DIVERTIDO PARA CRIANÇAS: Este brinquedo criativo é uma excelente atividade para crianças que gostam de artes e artesanato e massa de modelar.', 70.99, 65.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134201-23030-99kjvrve4oovdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F22132044154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42368092941', 'Boneco Quarteto Fantástico O Coisa Titan Hero 30cm - Hasbro G1328', 'Ben Grimm, também conhecido como O Coisa, é um membro formidável do Quarteto Fantástico. Imagine ação e aventura fantásticas de super-heróis com a linha de brinquedos Quarteto Fantástico, Procure mais brinquedos do Quarteto Fantástico para construir uma coleção incrível ou presentear crianças, incluindo bonecos de ação, conjuntos de brinquedos, veículos e itens de dramatização para meninos e meninas! • FIGURA DE AÇÃO MARVEL EM ESCALA DE 12 POLEGADAS (30 CM): O boneco O Coisa da Marvel em grande escala apresenta decoração e design inspirados em Quarteto Fantástico: Primeiros Passos, da Marvel Studios, parte do Universo Cinematográfico Marvel. • CRIAR POSES: Os brinquedos do Quarteto Fantástico da série Titan Hero da Marvel apresentam 11 pontos de articulação, para que as crianças possam colocá-los em poses para aventuras de salvar o mundo que imaginarem! • EMBALAGEM COLECIONÁVEL: Esta figura de ação O Coisa da Marvel vem em uma caixa de janela temática do Quarteto Fantástico que apresenta um design de inspiração retrô, que ficará incrível em exibição.', 220.99, 207.73, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meedq4z38d8i61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F42368092941', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29740483063', 'Conjunto Infantil Feminino Doçura Da Infância', 'Descrição: Conjunto Infantil Feminino Doçura Da Infância Conjunto em meia malha e moletinho perfeito. O cropped na cor branca conta com estampa frontal e manguinhas bufantes muito delicadas. O short azul possui cadarço decorativo que da um charme para a peça! Tudo pensado e produzido com muito amor e carinho. Selecionamos os melhores materiais para crianças que desejam ser destaque por onde passam! Guia de Tamanhos Como medir a criança? Utilizando uma fita métrica, envolva as regiões a serem medidas. Busto: Enrole a fita métrica em torno do corpo, na linha do peito. Comprimento: Comece pelo topo do ombro e meça até chegar no comprimento desejado. Quando for calça, short ou saia, comece medindo na linha da cintura. Cintura: Enrole a fita métrica em torno da cintura, sem apertar. As medidas da tabela abaixo são referentes á parte frontal da peça, então busto e cintura você deve multiplicar por 2. A tabela pode sofrer alterações de 1 á 2 cm para mais ou menos, leve isso em conta na hora de selecionar o tamanho adequado. Características: - Estação: Verão - Gênero: Feminino - Tecido Parte Superior: Meia Malha - Tecido Parte Inferior: Moletinho - Composição Parte Superior: 50% Algodão e 50% Poliéster - Composição Parte Inferior: 60% Algodão e 40% Poliéster - Faixa Etária: 1 à 12 anos - Evento: Não - Garantia: 1 Mês - Tipo de Roupa: Conjunto - Tabela de Medidas: Tabela de Medidas Cropped: Tamanho | Busto | Comprimento 1 | 28CM | 23CM 2 | 30CM | 25CM 3 | 32CM | 28CM 4 | 34CM | 30CM 6 | 36CM | 33CM 8 | 38CM | 36CM 10 | 39CM | 39CM 12 | 41CM | 42CM Tabela de Medidas Short: Tamanho | Cintura | Comprimento 1 | 18CM | 21CM 2 | 19CM | 23CM 3 | 20CM | 25CM 4 | 22CM | 27CM 6 | 23CM | 29CM 8 | 24CM | 30CM 10 | 25CM | 31CM 12 | 26CM | 32CM', 39.9, 29.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-824ig-mdvob15ng6ipe2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717393801%2F29740483063', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594803957', 'Wella Professionals Nutricurls - Condicionador 200ml', 'Condicionador para cabelos cacheados e ondulados. Wella Professionals Nutricurls nutre as curvas instantaneamente, conferindo nutrição e brilho. O Condicionador Nutricurls, de Wella Professionals é enriquecido com ingredientes nutritivos e que suavizam profundamente a fibra do fio. Além disso, a tecnologia de toda a linha Nutricurls garante efeito antifrizz, maciez e muita definição, sendo ideal para quem sente dificuldade em ter cachos marcados. Como Usar: Depois de lavar, aplique o condicionador pelo comprimento e pontas do cabelo, mas sem passar na raiz. Espere 30 segundos e depois enxágue abundantemente. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 164.9, 164.9, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-8262a-mjy8cvjzdx5387', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F23594803957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
