INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47411591695', 'Os Irmãos Karamázov | Volume Único | Fiódor Dostoiévski', 'Último romance de Dostoiévski, Os irmãos Karamázov representa uma síntese de toda sua produção e é tido por muitos como sua obra-prima. Um marco da literatura universal, influenciou pensadores como Nietzsche e Freud, que o considerava "o maior romance já escrito" e sucessivas gerações de escritores em todo o mundo. Um livro ao mesmo tempo filosófico e policial, que trata da conturbada relação entre o devasso Fiódor Karamázov e seus três filhos: Aliócha, "puro" e místico; Ivan, intelectual e atormentado; e Dmitri, orgulhoso e apaixonado. Com mão de mestre, Dostoiévski conduz o leitor numa viagem única pelos recantos mais sombrios e luminosos da alma humana e, com uma trama hipnotizante, consegue prender nossa atenção ao longo das centenas de páginas do volume - agora traduzido diretamente do russo por Paulo Bezerra. 888 páginas 16x23 cm', 146.9, 134.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-823rh-mp06m06oamfhb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F47411591695', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
