INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54251544028', 'Capa De Chuva Impermeável Forrado Com Capuz Epi Preto', 'Capa de Chuva Impermeável Forrada com Capuz – EPI Preta Descrição: Capa de chuva confeccionada em material impermeável e resistente, projetada para proteção contra chuva, vento e umidade em ambientes de trabalho ou uso urbano. Possui forro interno para maior conforto térmico e capuz ajustável para proteção da cabeça e pescoço. Características Técnicas: Material externo: PVC, nylon ou poliéster emborrachado (varia conforme modelo) Forro interno: Tecido sintético ou algodão leve Cor: Preta Fechamento: Zíper frontal com aba protetora e botões de pressão Costuras: Soldadas eletronicamente ou termo seladas para garantir impermeabilidade Capuz: Integrado e ajustável Classificação: EPI – Proteção do tronco e membros superiores contra umidade proveniente de precipitações Tamanhos disponíveis: ADULTO Aplicações: Serviços externos expostos à chuva (segurança, obras, transporte, limpeza urbana, agricultura, etc.) Atividades de lazer ou deslocamento em dias chuvosos!', 59.99, 19.0, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Rain Coats', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjpyq1swit4yc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F54251544028', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698486313', 'Livro para colorir | Cozy Time | Coleção Cute & Cozy | Azul', 'O livro que ganhou espaço nas redes sociais e conquistou o coração de quem é apaixonado por pintura! Descubra o prazer de colorir e relaxar em um universo de conforto e tranquilidade com Cozy Mood, esses livros são desenhos leves, aconchegantes e confortantes, que focam em ilustrações encantadoras, trazendo momentos de paz e calmaria. Se você ama momentos de calma e aconchego, você não pode deixar de adquirir esse título incrível que com certeza se tornará seu companheiro em todas as horas. Desperte sua criatividade, alivie o estresse do dia a dia e transforme cada página em uma verdadeira obra de arte. Pegue seu lápis de cor, relaxe e aproveite essa experiência única! Mais de 40 páginas com desenhos únicos, papel especial para não ultrapassar a outra folha e recomendado a partir de 5 anos de idade. 18x26cm 48 Páginas', 16.9, 7.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rffp-m9upoblqdcto64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22698486313', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494667369', 'O Jardim Secreto | Frances Hodgson Burnett | Brochura', 'Após ficar órfã, Mary Lennox vai morar na Inglaterra com seu tio viúvo. A mansão tem quase cem quartos e seu tio se mantém trancado lá. Os jardins que cercam a grande propriedade despertam a curiosidade de Mary. Ao decidir explorá-los, a órfã descobre um jardim secreto, cercado por muros e trancado com uma chave perdida. Com a ajuda de dois companheiros, Mary descobre como trazer o jardim de volta à vida.272 páginas15,5x22,6 cm', 18.9, 15.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821dy-mglng2ssy68d8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22494667369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
