INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498106232', '365 Palavras cruzadas plus - volume 3', 'Fazer palavras cruzadas é uma forma criativa e divertida de desenvolver o raciocínio, deixar o pensamento mais ágil e enriquecer o vocabulário, além de você se manter atualizado sobre diversos assuntos. 15x22cm 288 Páginas', 19.1, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7ra2d-m4gnka8ozdu01f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23498106232', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
