INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093949074', 'Livro de Colorir | Sweet e Fun: Raposas em Ação', 'A coleção Sweet & Fun traz as Raposas em uma jornada de ação e diversão! As páginas deste livro são repletas de ilustrações cheias de energia e charme, ideais para quem busca um momento de descontração e criatividade. Fique off das redes sociais e liberte sua imaginação enquanto pinta essas raposas espertas em movimento. Perfeito para todas as idades, este livro oferece a combinação ideal de relaxamento e diversão em cada página. 28x21 cm 32 Páginas', 17.9, 14.32, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7repf-m8s7z6tj1y95d5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22093949074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21299333103', 'Linha Multifilamento Victoria 4x 100m Verde - Maruri', 'Linha Multifilamento Victoria 4x 100m Verde - Maruri Construída por 12 fios trançados fortemente, a Linha para pesca Victória desenvolvido pela Maruri é diferente de qualquer outra do mercado, já que conta com confecção feita toda em polietileno de alta performance, o que garante grande força e sensibilidade, com a finalidade de proporcionar arremessos mais longos e precisos. Projetada com diâmetros ultrafinos, o que oferece alta resistência à abrasão. Com baixa absorção de água, sendo capaz de deslizar facilmente pelos passadores, o que garante maior durabilidade ao produto. Os pescadores, sem sombra de dúvida, vão sentir a diferença em relação a outras linhas. Especificações: Marca: Maruri Modelo: Victória 4X 100 metros Multifilamento Material: Polietileno 0,14mm: 22lbs 10kg 0,18mm: 24lbs 11kg 0,20mm: 29lbs 13,2kg 0,24mm: 35lbs 15,9kg 0,27mm: 39lbs 17,7kg 0,30mm: 44lbs 20kg 0,34mm: 48lbs 21,8kg 0,40mm: 53lbs 24,1kg 0,50mm: 75lbs 34kg 0,55mm: 81lbs 36,8kg 0,58mm: 90lbs', 30.9, 30.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3xi2ku3ihpxbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567374315%2F21299333103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393726617', 'Par de Palhetas Limpador Parabrisa Multiclip Original Bosch Chery Tiggo 5X 2018 A 2024', 'Par de Palhetas Limpador Parabrisa Multiclip Original Bosch Chery Tiggo 5X 2018 A 2024 A alta performance ficou ainda melhor. Palhetas que garantem mais Eficiência, Segurança, Durabilidade e Qualidade. Se é BOSCH, pode confiar. Enxergue o que vem pela frente. Kit composto por: - 1 Palheta Multiclip lado direito BOSCH Aerofit Original - 1 Palheta Multiclip lado esquerdo BOSCH Aerofit Original Medidas: - Palheta motorista: 22" (55 cm) - Palheta Passageiro: 16" (40 cm) - Use o adaptador 4 Compatível com: - Chery Tiggo 5X 2018 a 2024 Características: - Palheta BOSCH Aerofit Multiclip Original - Instalação mais fácil e segura. - Maior durabilidade e eficiência comprovadas. - Sem partes metálicas expostas. Livre de desgastes de pintura e corrosão. - Spoiler aerodinâmico para ter uma distribuição uniforme de força, mantendo a varredura eficiente mesmo em altas velocidades. - Maior estabilidade em todas as situações de uso. - Funcionamento ultra suave, devido ao seu tratamento de grafite, para um movimento sem ruídos ou trepidações. - Nova embalagem moderna e atrativa. Perguntas Frequentes: Quando devo trocar as Palhetas do meu carro? - A troca deve ser realizada aos primeiros sinais de desgaste nas Palhetas. Isso porque o componente com desgaste tem a eficiência comprometida e atrapalha a visibilidade. Quais os sinais de desgaste da palheta? - Os sinais de uma Palheta com desgaste são: a Palheta não retira todo o excesso de água, faz barulho durante o funcionamento, risca o parabrisa do carro, lâmina de borracha torta, quebrada ou ressecada. Qual o prazo para a substituição das Palhetas? - Substitua as Palhetas pelo menos uma vez por ano. As Palhetas são originais? - Sim. Somos fornecedores autorizados BOSCH. Todos os produtos são originais e acompanham Nota Fiscal. Observação: - Em caso dúvidas sobre o modelo correto da Palheta para o seu carro, faça uma pergunta na parte inferior do anúncio. Temos uma equipe especializada para tirar as suas dúvidas. - O limpador de parabrisa é um acessório obrigatório por lei (artigo 230, XIX, do CTB). O não funcionamento perfeito ou mau uso do mesmo, é caracterizado como infração grave, com direito a multa e retenção do veículo. Mantenha a sua família segura. Compre Palhetas Originais BOSCH Aerofit.', 154.97, 154.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rccv-m6mzktkkksyi12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F372102753%2F23393726617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
