INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14159440206', 'Sonda Lambda - OZA720EE1 P/ Celta Corsa Meriva', '.IDEAL AUTO PECAS - Desde 1992 - IDEAL PARA SEU CARRO! Sonda Lambda - Original NTK APLICACAO: CELTA 1.0 8V GASOLINA DE 2000 A 2005 PRE CATALIZADOR CELTA 1.4 8V GASOLINA DE 2003 A 2005 PRE CATALIZADOR CORSA 1.0 / 1.4 / 1.6 8V EFI GASOLINA DE 1994 A 2000 PRE CATALIZADOR CORSA 1.0 / 1.4 / 1.6 8V MPFI GASOLINA DE 1996 A 2001 PRE CATALIZADOR CORSA 1.0 / 1.4 / 1.6 8V MPFI ALCOOL DE 1996 A 2001 PRE CATALIZADOR CORSA 1.0 8V VHC GASOLINA DE 2005 A 2005 PRE CATALIZADOR CORSA 1.8 8V GASOLINA 2002 E 2003 PRE CATALIZADOR MERIVA 1.8 8V GASOLINA 2002 E 2006 PRE CATALIZADOR (SONDA DE UM FIO) DESCRICAO DO PRODUTO A sonda lambda e basicamente um sensor de oxigenio, visto que sua funcao e medir e comparar o nivel de oxigenio presente nos gases emitidos pelo escapamento e o nivel de oxigenio presente no ar externo. Para que assim, ela possa emitir um sinal preciso para a injecao eletronica.', 174.9, 174.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0ojrfvtsfb5d0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F433880234%2F14159440206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498919598', 'Pantufa Feminina Pegada Com Forro de Pelinho Marrom/bege', 'A Pantufa Feminina Pegada Com Forro de Pelinho Marrom/bege é a escolha perfeita para quem procura um calçado elegante, confortável e quentinho para dias frios. Confeccionada em tecido super macio de alta qualidade, esta Pantufa garante durabilidade e uma sensação de suavidade ao toque. O material interno têxtil fofinho promove conforto durante todo o dia, enquanto a palmilha também em tecido oferece um conforto para os pés . Um dos destaques desta da pantufa é o detalhe da logo da marca com enfeite na parte de cima do cabedal, adicionando um toque de sofisticação e originalidade ao design. As Lojas Radan conta com 10 lojas físicas no Rio Grande do Sul, oferecendo esta e uma grande variedade de produtos e marcas de calçados e vestuário feminino, masculino, infantil e esportivo. Compre online com entrega rápida (envio em até 24h) para todo o Brasil ou em uma de nossas lojas físicas, aproveitando nossa experiência e adquirindo produtos de qualidade. Aproveite! Produto original vendido pela Lojas Radan. A cor do produto nas fotos pode sofrer alteração em decorrência do uso do flash ou da configuração do seu monitor. Características: Indicado: Dia a dia Material: Têxtil Material interno: Têxtil Palmilha: Têxtil Fechamento: sem fechamento Solado: PVC Diferencial: Material Macio atoalhado Peso: 518g', 159.89, 159.89, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Indoor Slippers', 'https://cf.shopee.com.br/file/sg-11134201-825bb-mqz2wadxk2rw09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577790116%2F23498919598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
