INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19798786475', 'Relé Auxiliar Automotiva Universal Reversor 5 Terminais 40/10A – 24V Com Suporte Corrente DNI0240', 'Relé Auxiliar Automotiva Universal Reversor 5 Terminais 40/10A – 24V Com Suporte Corrente DNI0240 Relé Auxiliar Automotiva Universal Reversor DNI0240, uma solução prática e versátil para otimizar a funcionalidade elétrica do seu veículo. Com 5 terminais e suporte, este relé reversor possui uma corrente de 40/10A e é especialmente projetado para operar com voltagem de 24V, garantindo desempenho confiável e eficiente. Aplicações diversificadas: Este relé auxiliar é perfeito para diversas aplicações, incluindo farol alto/baixo, ventilador, luzes internas, faróis auxiliares, freio, mudança de câmbio, controle de filtros e ar saturado, entre outras funcionalidades automotivas. Compatibilidade com caminhões e ônibus: O Relé Auxiliar DNI0240 é compatível com diversos veículos das marcas Caio, Marcopolo, Mercedes-Benz, Scania e Volvo, sendo uma opção ideal para atender às necessidades elétricas desses modelos. Construção durável: Fabricado com materiais de alta qualidade, este relé apresenta uma construção durável e confiável, garantindo sua eficiência e resistência em diferentes condições de uso. Tenha o controle elétrico completo em seu veículo e aproveite todas as funcionalidades com o Relé Auxiliar Automotiva Universal Reversor DNI0240. Garanta agora mesmo essa solução prática e indispensável para melhorar a performance elétrica do seu automóvel ou veículo de carga.', 20.5, 20.5, NULL, 'Home Appliances > Electrical Circuitry & Parts > Others', 'https://cf.shopee.com.br/file/sg-11134201-7qvem-ljwnlg0ui48u6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F19798786475', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
