INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393676290', 'CONDICIONADOR ELSEVE SUPER ALINHADOR LISO DOS SONHOS LORÉAL 200ML LANÇAMENTO 2025', 'CONDICIONADOR ELSEVE LISO DOS SONHOS 200ML O Condicionador Efeito Liquid Hair sela e restaura a superfície da fibra para um liso com efeito liquid hair: desmaiado, com movimento super fluido e brilho intenso. Enriquecido com AHA + QUERATINA VEGETAL, Elseve Liso dos sonhos é o nosso 1ª tratamento em casa que transforma os fios para 1 semana de cabelos lisos e à prova de umidade. Resultados que resistem até 5 lavagens. - 2X mais liso, 2x menos frizz - 15X mais sedoso - 3X mais fácil de desembaraçar Modo de Uso Após o uso do shampoo, aplique no comprimento até as pontas, deixe agir e enxágue.', 24.99, 24.99, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7rbkh-m5pvqloujlhc4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F23393676290', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257792582', 'Escova Progressiva 150g + Tônico Capilar Vello 90ml - Ybera', 'Alisamento Prático, Seguro e Eficiente A Fashion Gold 150g é a escova progressiva sem formol da Ybera desenvolvida para quem deseja fios mais lisos, alinhados e com brilho, em um formato prático e econômico. Ideal para quem busca resultado profissional com segurança e conforto no dia a dia. Indicada para reduzir o volume e disciplinar os fios, a Fashion Gold oferece alisamento progressivo com efeito natural, preservando a integridade da fibra capilar. Fórmula avançada com ácidos orgânicos Sua composição conta com um sistema inteligente de ácidos orgânicos, que atuam na reorganização da fibra capilar sem causar danos. Essa tecnologia garante fios mais macios, alinhados e com brilho intenso desde a primeira aplicação. Ativos nutritivos de alta performance Quinoa Hidrolisada: rica em aminoácidos, contribui para a força e resistência dos fios. Óleo de Sacha Inchi: nutre profundamente e ajuda a recuperar o brilho natural. Óleo de Coco: mantém a hidratação e protege contra a quebra. Benefícios do tratamento Alisamento seguro e sem formol Redução de frizz e volume Toque sedoso e brilho espelhado Compatível com cabelos quimicamente tratados Ideal para quem busca: Manutenção do alisamento Uso pessoal Versão compacta e prática Resultado profissional em menor quantidade', 402.9, 334.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8262d-mmc7q1824c1ud4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1350034564%2F58257792582', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
