INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10386457737', 'Kit Bucha Eixo Traseiro Vectra 2.0 2.2 8v 16v De 1996 A 2000', 'IDEAL AUTO PECAS - Desde 1992 - IDEAL PARA SEU CARRO! Kit Bucha Eixo Traseiro - Axios APLICACAO: Vectra 2.0 2.2 8v 16v De 1996 A 2000 DESCRICAO DO PRODUTO: Sao pecas como essa que sao essenciais para o conforto e seguranca do automovel, pois essa bucha e capaz de impedir a presenca de ruidos entre pecas e impedir a passagem de vibracoes.', 541.9, 541.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/96311ae5ef8dfb32ac5720e8478ccd67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F10386457737', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51300821981', 'A Bíblia em um minuto | Capa Dura | Hernandes Dias Lopes', 'E se você pudesse conhecer toda a Bíblia em apenas alguns dias? Você já sentiu vontade de ler a Bíblia toda, mas se intimidou com seus 66 livros e mais de 1.100 capítulos? Que tal uma visão panorâmica das Escrituras para preparar você para essa aventura espiritual e fortalecer sua fé? O livro. A Bíblia em um minuto é a solução que você estava esperando! Este livro revolucionário apresenta cada um dos 1.189 capítulos da Bíblia resumidos em textos concisos de até 300 caracteres, o que é perfeito para nossa era digital. Mas não se engane: não é uma versão simplificada das Escrituras. Na linguagem de cinema, ele é um “trailer” da Bíblia para que você queira assistir ao filme completo da Palavra de Deus e deseje conhecê-la do começo ao fim. E para não ficar apenas no nível do resumo, você é conduzido por reflexões profundas que iluminam cada trecho. Elas foram escritas por Hernandes Dias Lopes, autor consagrado e um dos maiores expoentes das Escrituras da atualidade. Milhões de pessoas ao longo da história encontraram esperança, direção e propósito nas páginas da Bíblia. Agora, é a sua vez! Prepare-se para se apaixonar pela Palavra de Deus. Título: A Bíblia em um minuto Autor: Hernandes Dias Lopes Número de páginas: 304 Acabamento: Capa dura Dimensões: 16 cm larg. x 23 cm alt. Editora: Hagnos', 54.9, 54.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821gb-mgo1j0g1og0945', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F51300821981', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
