INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56400316312', 'CAPACETE RACE TECH HIT ANDROID ROSA', 'Produto acompanha apenas a viseira Cristal - Foto meramente ilustrativa. Famosas pelas jaquetas de alta qualidade com excelente custo/benefício, a RACE TECH tem o prazer de apresentar o HIT, novo capacete da marca que chega ao mercado brasileiro. Características: • Viseira resistente a riscos, proteção UV, 2,2 MM em policarbonato e troca rápida de viseira; •Entrada de ar inferior, entrada de ar superior e saídas de ar sob o spoiler; •Spoiler integrado; •Abs injetado de alta pressão; •1385 GR +- 50; •Forração removível e lavável, detalhes refletivos, tecido antialérgico; •Fecho micrométrico; •EPS de multidensidade.', 382.68, 382.68, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-82589-mge2cx61hibsd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F806887225%2F56400316312', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
