INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393412364', 'Kit com 2 Portas Sanfonada de Pvc 210x94cm Bariri', 'A porta sanfonada de PVC é o produto ideal para quem tem pouco espaço e precisa de uma solução na divisão de ambientes em apartamentos e casas pequenas. Por ser retrátil, esse modelo economiza espaço na sua abertura e fechamento, possibilitando a instalação em cozinhas, banheiros, lavanderias, despensas, salas de estar, escritórios, oficinas etc. Garantia: 03 Meses Tipo de Porta: Sanfonada Material Principal Construção e Acabamento: PVC Marca: Bariri Cor do Produto: Preto absoluto Cor Predominante: Preto', 441.35, 441.35, NULL, 'Home & Living > Decoration > Others', 'https://cf.shopee.com.br/file/sg-11134201-822wt-mo6v4jslklq947', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22393412364', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693126244', 'Cômoda de Bebê 120,30cm 1 Porta e 4 Gavetas 100% MDF Maya Clássico Espresso Móveis Branco/Brilho/Amêndoa Branco', 'A cômoda infantil tem estilo provençal e apresenta uma estrutura resistente em 100% MDF com acabamento em Pintura UV atóxica, priorizando a segurança de toda família. Possui cabideiro metálicos, 4 gavetas com corrediças telescópicas para facilitar o acesso e 1 porta . Os pés e puxadores em plástico garantem durabilidade e facilidade de manutenção, enquanto seu design cria um ambiente elegante e funcional no quarto dos pequenos. Estilo: Provençal Modular: Não Peso (kg): 48.1 Garantia: 03 Meses Altura (cm): 113 Acabamento: Pintura UV Largura (cm): 120.3 Possui Pés: Sim Possui Nichos: Não Possui Portas: Sim Tipo de Porta: Bater Altura dos Pés: 6 Pés Reguláveis: Não Porta Janelada: Não Possui Gavetas: Sim Possui Rodízio: Não Suporta Até (kg): 40 Tipo de Cômoda: Bebê Possui Espelhos: Não Possui Trocador: Não Profundidade (cm): 50.3 Escala de Brilho: Semi-Brilho Gaveta com Chave: Não Material dos Pés: Plástico Material da Porta: MDF Material do Fundo: HDF Origem do Produto: Nacional Ambiente Principal: Quarto Infantil Material da Gaveta: MDF Material Principal: MDF Necessita Montagem: Sim Possui Prateleiras: Sim Acabamento da Porta: Pintura UV Sapatas Niveladoras: Não Acabamento da Gaveta: Pintura UV Material da Prateleira: MDF Peso Máximo por Gaveta: 4 Acabamento da Prateleira: Pintura UV Complexidade da Montagem: Alta: deve ser montado por um montador especializado Tipo de Puxador da Porta: Externo Escala de Brilho da Porta: Semi-Brilho Tipo de Puxador da Gaveta: Externo Escala de Brilho da Gaveta: Semi-Brilho Formato da Janela da Porta: Não Possui Peso Máximo por Prateleira: 5 Tipo de Corrediça da Gaveta: Metálica Telescópica Material do Puxador da Po