INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999246500', 'Sensor Pedal Acelerador Gm Zafira 2003 a 2012 - 191413 - 2203', 'Sensor Pedal Acelerador Gm Zafira 2003 a 2012 191413 2203 (Cartão Refil) Quando o pedal é pressionado, o sinal elétrico do sensor é utilizado pela uCe que, por sua vez, identifi ca a posição do pedal. Com os dados enviados por outros sensores (sensor de temperatura, sensor map etc) a uCe faz algumas correções e gerencia a demanda de torque através da borboleta para que esta tenha uma abertura exata. A borboleta é controlada por um motor elétrico que consegue atingir a sua abertura total, obtendo, assim, uma total aceleração e uma marcha lenta perfeita.', 189.91, 189.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-823r8-mp16fguuqx34c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20999246500', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
