orta Cor Predominante: Preto Linha ou Coleção: Linha Veneza', 1379.09, 1379.09, NULL, 'Home & Living > Decoration > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259j-mqz4eovgxtl297', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F23897896676', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599441978', 'Pneu Tracmax Transporter RF09 195/70 R15C 104R', 'Experimente a máxima confiança ao dirigir com o pneu Tracmax Transporter RF09 195/70 R15C Aro 15 104/102R. Projetado com tecnologia avançada, esse pneu oferece tração e estabilidade excepcionais, garantindo uma condução segura e suave em qualquer superfície de estrada. O índice de velocidade R indica especificamente uma capacidade de velocidade máxima de até 170 Km/h, enquanto o índice de carga máximo é indicado por 104 (900 Kg) / 102 (850 Kg).', 426.38, 426.38, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-81zu5-mn3cmo3dxma0e8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F540643031%2F22599441978', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
