INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200212912', 'Varal de Chão Slim Alumínio', 'O Varal de Chão Slim Alumínio da Mor é a maneira mais barata e ecológica para secar suas roupas. Prático e funcional, é perfeito para quem não tem muito espaço em casa ou apartamentos. Sua estrutura resistente foi desenvolvida em tubo de alumínio, que garante sua durabilidade. Como não enferruja é ideal para regiões litorâneas. Pode ser carregado facilmente para onde você preferir e, quando não estiver utilizando, basta dobrá-lo e guardar em qualquer cantinho. Possui 5 varetas com capacidade para até 5,91m de roupa ou 16Kg de roupas úmidas distribuídas uniformemente. Suas peças plásticas são de polipropileno, incluindo as ponteiras em seus pés que ajudam a proteger o piso. Com o Varal de Chão Slim as tarefas do dia a dia ficarão muito mais simples!', 133.0, 133.0, NULL, 'Home & Living > Home Care Supplies > Clotheslines & Drying Racks', 'https://cf.shopee.com.br/file/sg-11134201-825aq-mg52i9ker6kt72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F58200212912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
