INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23119584244', 'Kit Antiacne 6 itens PhalleBeauty', 'Kit Antiacne 6 itens PhalleBeauty 1x Mousse Micelar Antiacne 1x Sabonete Antiacne PhalleBeauty 1x Gel Secativo Antiacne PhalleBeauty 1x Tônico Antiacne PhalleBeauty 1x Demaquilante Antiacne PhalleBeauty 1x Sérum Antiacne PhalleBeauty Foi especialmente desenvolvido para atender às necessidades das peles ,oferecendo uma limpeza suave e eficaz. Sua fórmula exclusiva combina ingredientes de alta qualidade para auxiliar no tratamento da acne, enquanto equilibra a oleosidade da pele, melhorando sua aparência e restaurando seu brilho natural. Use desta forma: Se estiver de maquiagem aplique primeiramente o demaquilante antiacne e prossiga na sequência, ou, se estiver sem maquiagem inicie desta forma: Passo 1: Lave seu rosto com o Sabonete Antiacne ou Mousse Micelar Antiacne , massageando gentilmente até fazer espuma. Enxágue com água corrente; Passo 2: Com a pele limpa, aplique o tônico antiacne com a ajuda de um lenço ou algodão; massageie e enxágue em seguida; Passo 3: Aplique o Sérum antiacne espalhando uniformemente diversas gotas. Faça movimentos circulares com as pontas dos dedos e não enxágue; Passo 4: Para a finalização, aplique sobre as acnes o gel creme secativo e aguarde a absorção.', 79.99, 79.99, NULL, 'Beauty > Skincare > Acne Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98q-lm3iv00ytbzqa3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F23119584244', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
