INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898468475', 'Kit Máscara e Tônico SOS Crescimento - Dabelle Hair', 'A linha SOS Crescimento da DaBelle é especialmente desenvolvida para fortalecer cabelos frágeis e quebradiços, promovendo um crescimento saudável e reduzindo a quebra dos fios. Máscara de Hidratação - SOS Crescimento 400g O que é: Uma máscara capilar enriquecida com óleo de rícino, D-pantenol e biotina, que proporciona hidratação profunda e fortalecimento aos fios. Ações: Hidrata intensamente, melhora a elasticidade, fortalece a fibra capilar e reduz a quebra dos cabelos. Resultado no cabelo: Cabelos profundamente hidratados, mais fortes, com brilho e maciez, além de redução significativa da quebra. Modo de uso: Após lavar os cabelos com shampoo, aplique a máscara no comprimento e nas pontas dos fios. Massageie da raiz às pontas e penteie delicadamente com os dedos ou com um pente de dentes largos. Deixe agir por 3 minutos e enxágue bem. Use de 2 a 3 vezes por semana para melhores resultados. Tônico Fortificante - SOS Crescimento 100ml O que é: Um tônico capilar formulado para fortalecer a raiz e estimular o crescimento saudável dos cabelos. Ações: Fortalece a raiz, hidrata profundamente os fios, melhora a elasticidade e o brilho, reduz a quebra e promove a saúde do couro cabeludo. Resultado no cabelo: Cabelos mais fortes desde a raiz, com crescimento acelerado, redução da quebra e aumento da densidade capilar. Modo de uso: Com o cabelo limpo e seco, divida o cabelo em seções e aplique o tônico diretamente no couro cabeludo, massageando suavemente com as pontas dos dedos. Não enxágue. Utilize diariamente ou conforme a necessidade.', 47.9, 44.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-81zwm-mimquot0afb677', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939411398%2F18898468475', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50909764014', 'Sapato Democrata Metropolitan Clark Pulse Preto 604202-001 - Masculino', 'Sapato Democrata Metropolitan Clark Pulse Preto - Masculino: Clássico e Sofisticado para o Homem Moderno Ficha Técnica: Material: Couro Altura do Salto: 2,5 cm Palmilha: Acolchoada e removível Solado: Micro expandido Detalhes: Recorte lateral para um toque refinado Ajuste: Cadarço de elástico para segurança e ajuste perfeito Indicação: Ideal para o Dia a Dia e eventos formais Gênero: Masculino Cor: Preto com detalhes em branco e marrom Detalhes: Pespontos contornam o sapato Marca: Democrata Conteúdo da Embalagem: 1 Par de Sapato Democrata Metropolitan Clark Pulse Preto - Masculino O Sapato Metropolitan Clark da Democrata é uma peça versátil que eleva qualquer visual com sua estética clássica e acabamento refinado. Confeccionado em couro de alta qualidade, este sapato alia durabilidade e elegância. O design é realçado por um discreto recorte lateral, um detalhe que destaca a sofisticação do modelo. A palmilha oferece conforto duradouro, enquanto o solado em micro expandido proporciona leveza e estabilidade, perfeito para o uso prolongado.', 459.99, 311.99, NULL, 'Men Shoes > Oxfords & Lace-Ups', 'https://cf.shopee.com.br/file/sg-11134201-820l5-mnokm2vh86io2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F50909764014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
