INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27486607882', 'Bíblicos Pop-Up | A Arca de Noé | 3 Anos', 'Livro Bíblicos Pop-Up | A Arca de Noé | 3 Anos Sinopse do Livro: Um dia, Noé constrói uma arca, algo como um grande navio. Muitos animais e algumas pessoas entram na arca. Então, começa a chover. A chuva é tanta, que toda a terra fica coberta de água. Será que a arca permanecerá flutuando? Descubra o que acontecerá nesta história especial da Bíblia. Especificações do livro: Título: Bíblicos Pop-Up | A Arca de Noé | 3 Anos Ano de Edição: 2023 Capa: Capa Dura Acabamento: Laminação Brilhante Miolo: Papel Cartão Brilhante Páginas: 8 Dimensões: Altura: 15 cm Largura: 20 cm Profundidade: 0.6 cm Peso: 0.120 kg ISBN: 9786556178479 Editora: Todo Livro', 14.1, 14.1, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9kscw6kvqpu9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F27486607882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210271963', 'Salgadinho de Batata Pringles sabor Creme e Cebola 37g', 'A Pringles® Sabor Creme e Cebola 37g traz a combinação clássica do sabor creme e cebola em um snack de batata com textura única e crocância característica de Pringles®. Conhecido em todo o mundo, este salgadinho de batata sabor creme e cebola oferece um sabor marcante e equilibrado em cada mordida. Agora em um novo tamanho prático de 37g, é perfeito para levar na mochila, bolsa ou para aproveitar em qualquer momento do dia. Ideal para lanche da tarde ou da noite, para dividir com amigos ou para acompanhar momentos de lazer. Os salgadinhos de batata Pringles® são reconhecidos pelo seu formato icônico e encaixe perfeito na língua, além da crocância que torna cada snack ainda mais saboroso. Uma opção prática de snack salgado crocante para quem gosta de Pringles®.', 7.49, 7.49, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-8258v-mqnelgirbklc9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555155%2F58210271963', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41350650239', 'Devocional Graciosa Mãe | Ana Maria Cavalaro', 'Devocional Graciosa Mãe O Livro de João Devocionais para mãe de todas as idades. Começar minhas manhãs na presença de Deus, absorvendo Suas palavras e meditando em Sua orientação, trouxe uma transformação profunda à minha vida, proporcionando segurança e direção em minha jornada. À maternidade traz desafios e preocupações, mas compartilhar este livro é uma alegria, pois não só compartilho as revelações que o Senhor trouxe por meio do evangelho de João, mas também ofereço um guia diário para fortalecer um relacionamento pessoal com Deus, inspirando a intimidade e abrindo portas para descobertas divinas. Especificações do Devocional Graciosa Mãe Título: Devocional Graciosa Mãe Título: Devocionais para mãe de todas as idades. Autor(es): Ana Maria Cavalaro Ano de Edição: 2023 Capa: Brochura Acabamento: Laminação Fosca com Verniz Localizado Miolo: Papel Offset Páginas: 124 Dimensões: Altura: 21 cm Largura: 15 cm Profundidade: 0,5 cm Peso: 0,210 kg ISBN: 9786587533551 Editora: 100% Cristão', 35.81, 35.81, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9ksnuqjhypu60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F41350650239', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997994381', 'Volante Esportivo Mustang Vw Gol G1 Quadrado Saveiro Voyage Parati', 'Oferecemos durabilidade e resistência incomparáveis. O volante Mustang foi projetado para oferecer máxima segurança, garantindo aderência firme e conforto, proporcionando controle absoluto em todas as suas viagens. CONTEÚDO DA EMBALAGEM: • Volante Esportivo Personalizado; • Diâmetro de 370mm; • Cubo Adaptativo; • Emblema; • Parafusos para instalação. COMPATIBILIDADES: • Volkswagen Gol Quadrado (G1) Até 1995 • Volkswagen Parati Até 1998 • Volkswagen Saveiro Até 1997 • Volkswagen Santana Até 1995 • Volkswagen Fusca 1977 À 1996 • Volkswagen Brasília 1977 À 1982 • Volkswagen Buggy (Estria Fina) • Volkswagen Bugre (Estria Fina) • Volkswagen Kombi 1950 À 1982 EXCLUSIVIDADE • Qualidade superior em poliuretano: Volantes com toque macio, controle preciso e resistência excepcional, graças ao poliuretano de alta tecnologia e cubos metálicos que garantem segurança e durabilidade. • Personalização única: Volantes em diversas cores e compatibilidades, ideais para realçar o estilo e a personalidade do seu carro. • Atendimento especializado: Se não encontrar seu modelo em nossa descrição, entre em contato com nossa equipe e nós ajudaremos a encontrar a solução ideal para você. IMPORTANTE: • Verifique a compatibilidade do anúncio com seu veículo. Tire suas dúvidas ANTES da compra. • Entrega rápida: Compras realizadas hoje serão despachadas no próximo dia útil. • Recomendamos a instalação por um profissional. • A instalação dos nossos volantes resulta na perda da funcionalidade do airbag. Eleve a experiência ao dirigir com nossos volantes', 379.98, 197.59, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7reog-m21ctgujhou8fa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F955071389%2F23997994381', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
