INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499228460', 'Sabonete em Barra Palmolive Naturals Nutrição Cremosa Leite e Pétalas de Rosa 85g', 'O sabonete em barra Palmolive Naturals Hidrata & Perfuma une a deliciosa fragrância das pétalas de rosas com o poder hidratante do leite, proporcionando uma pele suave e perfumada. Além disso, sua fórmula contém ingredientes 100% de origem natural. Nutre sua pele, nutre sua vida. Benefícios para você: Deixe sua pele macia e nutrida com este sabonete em barra Palmolive Naturals. Os ingredientes naturais funcionam como alimento para sua pele, nutrindo-a. Fórmula nutritiva infusionada com ingredientes 100% de origem natural. Com leite e pétalas de rosa. Cuida e nutre sua pele. Embalagem econômica para sua família.', 32.02, 20.84, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rcdb-lt1fxs3q9gx7df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F18499228460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
