INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694058543', 'Sandália crocs mickey and friends baya clog juvenil multi', 'Faça uma declaração confortável do crocs com o crocs baya clog. uma reviravolta em nosso classic clog de assinatura, ele apresenta a construção leve e durável que você ama com ventilação avançada para respirabilidade e ajudar a drenar água e detritos. •material croslite ™ totalmente moldado para amortecimento leve máximo •adequado à água e flutuante; super leve •a ventilação avançada mantém os pés frescos e ajuda a drenar água e detritos •fácil de limpar e rápido de secar •tiras de salto giratórias para um ajuste mais seguro •personálizavel ??com jibbitz ™ •iconic crocs comfort ™: leve. flexível. conforto de 360 ??graus. as imagens do site podem sofrer pequena alteração de cor dependendo do monitor e da resolução em que elas sejam visualizadas.', 289.0, 216.75, NULL, 'Men Shoes > Sandals & Flip Flops > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-8261d-ml5kbd6521an20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757311881%2F23694058543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
