INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40304869931', 'Brinquedo Infantil Máquina Pop Bubble Animal Dinossauro Verde Fenix - POP-303V', 'Transforme qualquer momento em uma divertida explosão de bolhas com o Bichinhos Pop Bubble! Este adorável dinossauro verde é uma máquina de bolhas automática que encanta crianças de todas as idades. Com um design superfofo e fácil de usar, ele é perfeito para estimular a coordenação motora, divertir em festas ou simplesmente alegrar o dia dos pequenos. Basta adicionar a solução de bolhas inclusa, apertar o botão e assistir centenas de bolhinhas tomarem o ar em segundos! Ideal para ambientes internos e externos, proporciona diversão segura e educativa. Destaques do Produto: - Design de dinossauro verde - Gera dezenas de bolhas por minuto automaticamente. - Estimula a coordenação motora e a interação social. - Operação simples: apenas um botão para ligar e desligar. - Acompanha frasco de solução para bolhas. - Indicado para crianças acima de 3 anos. - Produto leve, seguro e prático de transportar. Recomendações: - Utilize sempre sob a supervisão de um adulto. - Produto ideal para festas, brincadeiras ao ar livre ou momentos especiais em família! Características: - Marca:FENIX - Modelo:POP-303V *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 1 Máquina de Bolhas Bichinhos Pop Bubble. - 1 Frasco de Solução para Bolhas.', 70.65, 63.58, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rat2-mb3yzvhtms7lec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F40304869931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58107027429', 'PASTILHA FREIO YBR 125 FACTOR 09-13/ FAZER 150 13-15 (D)/ NMAX 160 (T) MAXX 078592', 'Descrição: Pastilha de Freio Traseira – YBR 125 / Factor / Fazer / NMAX Pastilha de freio desenvolvida para garantir eficiência na frenagem, segurança e durabilidade no uso diário. Produzida com composto de alta qualidade, proporciona excelente desempenho, menor desgaste e melhor dissipação de calor. Compatível com: YBR 125 Factor 125 Fazer 250 NMAX Aplicação: Traseira Características do Produto: Composto de fricção de alta resistência Excelente poder de frenagem Menor desgaste do disco Baixo nível de ruído Alta durabilidade Produto novo. Emitimos nota fiscal para todos os pedidos. Garantia de 3 meses contra defeitos de fabricação. Recomendamos que a instalação seja realizada por profissional especializado para garantir o correto funcionamento do sistema de freio.', 18.9, 16.07, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260t-mlnl3yav5z45e2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462404558%2F58107027429', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694759035', 'Super Tweeter JBL ST500 Ultimate 500 Watts RMS', 'Super Tweeter JBL ST500 Ultimate 500 Watts RMS Super tweeter feito para quem quer brilho, presença e definição nas altas frequências. O JBL ST500 Ultimate entrega até 500W RMS em 8 Ohms com resposta ampla de 3.000 a 20.000Hz, garantindo agudos fortes e precisos mesmo em volumes mais altos. Com alta potência nominal (300W com HPF a 5kHz e 500W com HPF a 8kHz), ele trabalha seguro em sistemas mais exigentes, trazendo aquele ataque e nitidez característicos da JBL em qualquer projeto automotivo. Especificações Técnicas: • Potência nominal (HPF 5KHz): 300 RMS; • Potência nominal (HPF 8KHz): 500 RMS; • Impedância nominal: 8 OHMS; • Impedância mínima: 6,9(@10.788Hz); • Resposta de frequencia: 3.000 a 20.000 Hz; Conteúdo da Embalagem: • 01 Super Tweeter ST500 Ultimate • Manual e Certificado de Garantia Importante: • Garantia de 273 dias. • Valor da unidade. Todos os Nossos Produtos São Novos, Originais e Acompanham Nota Fiscal.', 486.99, 364.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mifx6l0ed79de4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1101226660%2F22694759035', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
