INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492415200', 'Armário De Cozinha Suspenso 4 Peças Liris Boreal - Móveis Arapongas', 'O Armário Modulado Suspenso de Cozinha 4 Peças Liris projetado para combinar estilo e funcionalidade, tornando-o uma adição prática e elegante à sua casa. É uma escolha versátil e funcional, perfeita para criar um ambiente organizado e atraente na sua cozinha! Medidas da Cozinha Montada: A: 156cm | L: 181,5cm | P: 37cm - Balcão - A: 61,5CM | L: 90CM | P: 37CM - Paneleiro Simples - A: 156CM | L: 30CM | P: 27,5CM - Aéreo 2 Portas - A: 40CM | L: 90CM | P: 26CM - Aéreo com Nichos - A: 28,2CM | L: 61,5CM | P: 26CM Detalhes Técnicos - MDP 12mm e 15mm - Pintura UV - Corrediça metálica - Puxadores em PVC - Tonalidade: Boreal - Prateleiras e gaveta suportam até 5kg - Produto suspenso, não possui pés Conteúdo da Embalagem - 01 Cozinha 4 peças - Manual de Montagem - Acessórios para Montagem Observações Importantes - Imagens ambientadas meramente ilustrativas, objetos decorativos não compõe o produto; - Produto novo, garantia somente para defeitos de fabricação: 3 meses; - Não realizamos entregas em zonas rurais, via caminhos fluviais e distritos, NÃO ACEITAMOS CEP GERAL; - Não trabalhamos com entrega agendada. O recebedor deve ter mais de 18 anos. O valor do frete não inclui: subida de escada, elevador ou lançamento de produto, em condomínio residencial a entrega é feita somente até a portaria. As entregas são realizadas em dias e horários comerciais; - Ao receber o produto observe se a embalagem está em perfeita condição. Confira atentamente a quantidade de volumes; - Produto entregue desmontado. É responsabilidade do cliente a montagem/instalação do produto, inclusive despesa para sua realização. Recomendamos a contratação de um profissional especializado; - Evitar a exposição direta à luz solar e à umidade. Limpar com pano macio e seco, não utilizar produtos químicos; - A cor do produto pode variar de acordo com o monitor, a iluminação do ambiente ou sua percepção visual.', 759.0, 672.83, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8261j-mk3yzfzkpq1171', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F653044811%2F23492415200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897356864', 'Pek Eclipse 5l Efeito Super Gloss Promove Alta Resistencia', 'Pek Eclipse é um vitrificante e cristalizante exclusivo ideal para granitos, mármores, polidos e concretos lapidados. Revigora a cor natural das superfícies e torna os materiais mais resistentes à abrasão e menos escorregadios.Além de aumentar o brilho, Pek Eclipse confere maior resistência mecânica, promove efeito antiderrapante, corrige pequenas fissuras (preenchendo-as) e facilita a manutenção dos revestimentos em que é aplicado. Aprimora o brilho natural de granitos e mármores polidos. Impermeabiliza revestimentos. Pode ser usado na manutenção de concretos lapidados. Reforça e abrilhanta estes pavimentos.', 536.49, 348.72, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rces-ls2o4dv78bzc75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F22897356864', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
