INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15501796931', 'Conjunto de 6 Xícaras Grandes 220ml Com Pires Ryo White', 'Buscar a beleza no imperfeito: essa é a premissa de uma filosofia japonesa muito inspiradora. O conceito se tornou uma grande tendência de design que aposta no uso de formas orgânicas e naturais. A coleção Ryo segue essa tendência e traz peças com formatos sinuosos. Louças lindas que apostam na imperfeição e na autenticidade. O nome Ryo é uma palavra em japonês que significa “excelente”. Conteúdo da embalagem: 6 xícaras para chá com 220ml de capacidade / 6 pires para chá com 16cm de diâmetro - Garantia: 12 Meses para Gretagem - Uso: Resistente a micro-ondas e lava-louças - Tipo da embalagem: Papelão pardo - Tipo: Xícara - Cor: Branco - Material: Porcelana - Formato: Outros - Utilizações seguras: Micro-ondas e lava-louças - Tipo do jogo: Xícara - Capacidade em volume: 220ml ATENÇÃO: Para compras de pessoa jurídica, cadastre os dados exatamente como consta em seu cartão do CNPJ', 248.29, 248.29, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/5115322aeb479f57481421d37e676be5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F548911108%2F15501796931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
