INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23296590125', 'Máscara Explosão de Brilho DaBelle Hair 400g', 'A Máscara Explosão de Brilho DaBelle Hair foi desenvolvida para proporcionar hidratação intensa e realçar o brilho natural dos cabelos. Ideal para fios opacos, ressecados ou danificados, sua fórmula nutritiva ajuda a recuperar a maciez, suavidade e vitalidade dos fios.Auxilia no desembaraço, controla o frizz e deixa os cabelos alinhados, sedosos e com aspecto saudável e luminoso.Conteúdo:1 Máscara Explosão de Brilho – DaBelle Hair 400g', 25.9, 25.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-825zv-ml5lqfevqvb439', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939411398%2F23296590125', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53655729293', 'Verniz Marítimo Acetinado/Brilhante 900ml Poliulack Sayerlack', 'POLIULACK - Verniz Marítimo – Premium Exterior e Interior Indicado para acabamento de portas, janelas, lambris e madeiras decorativas em geral. Verniz marítimo com triplo filtro solar, alto rendimento e secagem rápida e durabilidade de até 3 anos. Pode ser tingido com Tingilack – Tingidor Concentrado em até 2% no máximo. Cor: Transparente OBS. Aplicar o produto com temperatura ambiente entre 10 e 40º. C e umidade relativa do ar entre 40 e 80%. Tempo de Secagem: Entre as demãos: 12 horas Completa: 24 horas Rendimento: ACETINADO: Mínimo 5 m² / 900ml / Acabado SAYERLACK', 63.52, 44.47, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-82633-mk89wrzn3g8wb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F53655729293', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098226986', 'Verniz Tingidor Acetinado Mogno Ipe Montana 900ml', 'Verniz Premium Tingidor Base Solvente • Acetinado Para onde serve: Verniz Tingidor Premium é um verniz que além de proporcionar cor, protege a madeira contra as intempéries naturais, exposição à chuva e luz solar direta. Ideal para madeiras novas e para restauração. Onde usar: A aplicação do Verniz Tingidor Premium é indicada para dar cor às madeiras novas, renovar e impermeabilizar superfícies de madeira aplainadas, lixadas ou rústicas (portas, portões, janelas, beirais, forros e estruturas de telhado). Por que usa • Fácil aplicação; • Secagem rápida; • Ótimo alastramento; • Duplo filtro solar; • Resistência a intempéries. Versões: Quatro opções de cores: Castanho Imbuia Mogno Ipê Rendimento: Até 4 m² / 0,9 L / acabado', 69.62, 48.74, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcj4624jgpa977', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F23098226986', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
