INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41562025289', 'Kit 40 Bateria Pilha Moeda Cr1620 8 Cartela 3v Relógio Elgin', 'Oii, é um prazer ter você aqui! Seu relógio ou dispositivo precisa de energia confiável e duradoura? O Kit 40 Baterias Pilhas Moeda CR1620 8 Cartelas 3V Relógio Elgin é a escolha perfeita para manter seus aparelhos funcionando com máxima eficiência. Confira por que você deve escolher est O que é: - 40 Baterias Moeda CR1620 3V Elgin. - Modelo: Cr1620. - Marca: Elgin. - 3 Volts. O que tem: - 8 Blister com 5 unidades de Bateria. - Dimensões: 2,0 x 16,0 mm - 0% de Metais Pesados. - Alta Durabilidade. - Economia e Qualidade. Onde usar: - Relógios. - Brinquedos. - Rádios. Como usar: - Abra o compartimento de pilhas do seu aparelho. - Remova as pilhas antigas, se houver. - Insira as Baterias Cr1620, garantindo que os polos positivo e negativo estejam na posição correta. - Feche o compartimento das pilhas. - Seu aparelho está pronto para uso novamente! Com excelente durabilidade, confiabilidade da marca Elgin e energia ideal para seus dispositivos, o Kit CR1620 é a solução completa para o seu dia a dia. Adquira já e mantenha seus aparelhos sempre prontos para uso! Surgiu alguma dúvida? Entre em contato com a gente! Boas Compras :)', 91.23, 72.98, NULL, 'Home Appliances > Batteries', 'https://cf.shopee.com.br/file/sg-11134201-7rdvx-md686b0xwge19e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F41562025289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699605562', 'Aromatizante limpador concentrado Orquídea 120ml Coala', 'Com Coala Essências - Limpador Perfumado de Ambientes de Orquídea, seu ambiente vai ficar limpo e com um aroma incrível. Pode ser usada em todos os ambientes. Detalhes: - Fragrância agradável - Tem perfume duradouro - Garante a sensação prolongada de limpeza e bem-estar- Modo de usar Diluir 8 gotas da Essência Limpadora concentrada em 1 litro de água e com o pano úmido e passar sobre a superfície desejada. Precauções Testar o produto em uma pequena área antes do uso, para evitar possíveis manchas. Manter o produto em sua embalagem original, sempre fechada. Guardar sob abrigo da luz do sol, pois o calor excessivo pode danificar o produto e sua eficácia. Além disso, é importante manter fora do alcance de crianças e animais de estimação.', 28.68, 19.8, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Air Fresheners & Home Fragrance', 'https://cf.shopee.com.br/file/sg-11134201-7rd5u-m6qt5pms6ccs1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F20699605562', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
