INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298200772', 'Capa para Mala Big Face Mickey Grande Azul', 'Capa para Mala Big Face Mickey Grande Azul A Capa para Mala Big Face Mickey Grande Azul é mais do que apenas uma proteção para sua bagagem, ela garante uma segurança extra para suas viagens tornando sua bagagem fácil de localizar. Com um design elegante e funcionalidade excepcional, esta capa de mala oferece a combinação perfeita de proteção e estilo. Principais Características: -Proteção de Qualidade: Feita com materiais duráveis e resistentes, nossa capa de mala protege sua bagagem contra arranhões, sujeira e danos durante o transporte. -Design Personalizado: Com uma variedade de cores e estampas, nossa capa de mala permite que você personalize sua bagagem e a torne facilmente identificável na esteira de bagagens. -Tamanhos Variados: Disponível em diferentes tamanhos para atender às dimensões da sua mala, nossa capa é adequada para malas de diversos estilos e tamanhos como por exemplo: capa de mala media, capa de mala de bordo, capa de mala pequena e capa de mala grande. Especicações: Marca: Bagaggio Material: Poliéster Peso (kg): 0.500kg Marca: Bagaggio Idade: Adulto Gênero: Unissex Tipo: Capa de mala Tamanho da Capa: G'' Garantia: 3 meses', 159.9, 159.9, NULL, 'Travel & Luggage > Travel Accessories > Luggage Protectors & Covers', 'https://cf.shopee.com.br/file/sg-11134201-7rcfa-m66yl8qrdk4736', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1462563752%2F23298200772', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
