INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298208961', 'Boneco Funko Pop! Disney Vida Real - Mickey com Roupa de Corrida', 'Prepare-se para acelerar com o Boneco Funko Pop! Mickey Mouse! Esta figura exclusiva traz o icônico Mickey Mouse em uma vibrante roupa de corrida, capturando seu espírito competitivo e divertido. Com detalhes incríveis e uma pose dinâmica, este Pop! é a adição perfeita para qualquer fã de Disney e colecionador de Funko Pop! que deseja adicionar um toque de emoção e estilo à sua coleção. Não perca a chance de celebrar a energia e a magia de Mickey Mouse com este modelo único!', 164.99, 164.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rbkp-m5yrhs44rzp050', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F22298208961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23696981968', 'Linha Multifilamento Kairiki 4 Fios Cinza 150m - Shimano', 'Pensando em nossos clientes e amigos, em parceria com a Shimano trazemos esse grande lançamento a Linha Multifilamento Kairiki 4 Fios Cinza 150 m - Shimano. Caracterizada como uma Linha Multifilamento, essa é categoria preferida dos pescadores sabe por quê? Simples, devido a seu custo e benefício! Essa linha, pode proporcionar diversas possibilidades de uso ao pescador. A nova Linha Multifilamento Shimano Kairiki 4X possui tecnologia VT em sua construção que ajuda a evitar emaranhados, esta nova tecnologia (VT Construction Method) conta sistema de fabricação onde é usado alta tensão em direções opostas durante o processo de trança da linha, sua fibra é tecida uniformemente em todos os ângulos, o que a torna mais suave com menos atrito. Com acabamento liso, essa linha possui menor atrito com as guias, resultando em um arremesso mais longo e preciso, devido à sua suavidade e baixo diâmetro, o Kairiki 4 é uma ótima linha para utilizar com jigging pois possui baixa resistência à água e devido a sua elasticidade máximo de 3,0% também o torna muito mais sensível às fisgadas. Vantagens da utilização da Linha Multifilamento: - Custo baixo; - Pode ser utilizada em grande maioria das modalidades de pesca; - Praticidade para dar nós. As Linhas Multifilamento são compostas por vários fios como seu próprio nome já diz, feito em Polietileno. São indicadas para pescadores que procuram uma pesca mais barata, de paciência e sem uma alta resistência a fisgadas. Essa linha é comercializada nos seguintes diâmetros: - Diâmetro: 0,06 mm | Resistência: 2,72 kg equivalentes a 06,00 Libras; - Diâmetro: 0,10 mm | Resistência: 3,62 kg equivalentes a 8,00 Libras; - Diâmetro: 0,13 mm | Resistência: 4,53 kg equivalentes a 10,00 Libras; - Diâmetro: 0,16 mm | Resistência: 6,80 kg equivalentes a 15,00 Libras; - Diâmetro: 0,19 mm | Resistência: 8,16 kg equivalentes a 18,00 Libras; - Diâmetro: 0,20 mm | Resistência: 9,07 kg equivalentes a 20,00 Libras; - Diâmetro: 0,215 mm | Resistência: 11,33 kg equivalentes a 25,00 Libras; - Diâmetro: 0,23 mm | Resistência: 13,60 kg equivalentes a 30,00 Libras; - Diâmetro: 0,28 mm | Resistência: 18,14 kg equivalentes a 40,00 Libras; - Diâmetro: 0,315 mm | Resistência: 22,67 kg equivalentes a 50,00 Libras; Cada carretel possui cerca de 150 metros de linha. A grande vantagem na coloração dessa linha está no alto poder de camuflagem quando está submersa na água, principalmente em rios e pesqueiros que a água costuma-se ser mais turva. Sendo assim ela auxilia na diminuição do reflexo promovido pelo sol, ajudando a não espantar o peixe. ATENÇÃO: ESCOLHA O DIÂMETRO DA LINHA DESEJADA ANTES DE FINALIZAR A COMPRA, SEGUINDO OS PADRÕES DE RESISTÊNCIA DESEJADA! Especificações Técnicas: - Marca: Shimano - Origem: Japão - Material: Polietileno - Cor: Cinza - 4 Fio - Tecnologia: VT - PE - Modelo: Linha Multifilamento Kairiki 4 Fios Cinza 150 m - Shimano - Compatibilidade: Molinetes e Carretilhas - Validade indeterminada - Peso: 80g - Dimensões embalagem (A x L x C ): 2,5 cm x 13,5 cm x 11 cm. Itens Inclusos - 01 Linha Multifilamento Kairiki 4 Fios Cinza 150 m - Shimano', 165.29, 165.29, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7rbm3-lmdjpdbqonkpfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063297286%2F23696981968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
