INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46363154574', 'Filtro de Combustível Honda City Civic Fit HR-V 2009 a 2026 Original', 'FILTRO DE COMBUSTÍVEL Produto novo, de alta qualidade, desenvolvido para garantir a filtragem eficiente do combustível, protegendo a bomba de combustível, os bicos injetores e todo o sistema de injeção eletrônica. Conteúdo da embalagem 01 Filtro de Combustível Aplicação Honda City 1.5 16V i-VTEC Flex – 2009 a 2026 Honda Civic 1.8 16V i-VTEC Flex – 2012 a 2016 2.0 16V Flex – 2013 a 2024 1.5 Turbo – 2016 a 2023 2.4 Si – 2014 a 2015 Type R 2.0 Turbo – 2023 Honda Fit 1.4 16V Flex – 2006 a 2014 1.5 16V i-VTEC Flex – 2008 a 2023 Honda HR-V 1.8 16V Flex – 2015 a 2023 Benefícios Alta capacidade de retenção de impurezas. Protege a bomba de combustível e os bicos injetores. Proporciona melhor desempenho do motor. Mantém o sistema de alimentação limpo. Produto com excelente durabilidade. Importante Verifique a compatibilidade com seu veículo antes da compra. Em caso de dúvidas, informe o modelo, ano e motorização do veículo. Recomendamos a instalação por profissional especializado. Produto novo, com Nota Fiscal. Garantia de 90 dias contra defeitos de fabricação.', 34.99, 24.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820m0-mq3ydmx33aptcf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560163381%2F46363154574', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
