INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897832924', 'Caneta hidrográfica Brush Sign Pen Amarelo Pentel', 'A caneta Sign Pen da Pentel tem alta qualidade e mistura características da esferográfica com pincel, resultando em uma ponta porosa que possibilita tanto o traço fino quanto o traço mais grosso, podendo ser usada para escrita comum e trabalhos com lettering e desenhos. Detalhes: - Caneta pincel que permite criar diferentes traços. - Ponta flexível de poliéster e polioximetileno. - Ideal para caligrafia, desenhos, ilustrações e o que mais sua imaginação permitir.', 25.12, 25.12, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-81zva-mmq1p211k5xd06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F22897832924', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
