INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998292496', 'Kit 2 Shampoo Elseve Reparação Total 5+ 400ml', 'SHAMPOO ELSEVE REPARAÇÃO TOTAL 5+ Cabelos danificados. As agressões dia após dia, causam danos imperceptíveis a olho nu. Se não tratados eles evoluem e causam 5 problemas recorrentes: Quebra, rigidez, opacidade, ressecamento e pontas duplas. A linha que faz uma reparação total dos 5 sinais de danos para um efeito de plástica capilar. Modo de usar: Aplique nos cabelos molhados e massageie suavemente. Enxágue. Repita a operação se necessário.', 69.98, 69.98, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-823qg-momywvfx6lmq2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F19998292496', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
