INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892383825', 'Sunga Boxer Masculina Basica Acqua Rio Moda Praia Adulto Com Forro e Com Cordao de Regulagem', 'Sunga Boxer Adulto Acqua Rio Ref: 680400 A Sunga Boxer Basica Acqua Rio Praia Adulto Lisa e a escolha perfeita para homens que buscam uma combinacao de estilo minimalista e conforto durante seus dias na praia ou na piscina. Esta sunga boxer, da marca Acqua Rio Praia, oferece um design liso e clean, perfeito para aqueles que preferem um visual descomplicado e um ajuste seguro para suas atividades aquaticas. * Confeccionada em Poliamida com elastano * Modelo Boxer. * Com forro * Design Basico, a sunga possui um design liso e simples, proporcionando um visual elegante e atemporal. * Cintura com cos elastico e regulador interno, para melhor ajuste. * Detalhe do filete nas laterais * Logo Acqua Rio Praia ao lado esquerdo * Garante maior conforto gracas ao tecido de maior elasticidade * Estilo e conforto para os dias quentes ou para pratica esportivas como natacao. A marca Acqua Rio, faz parte do Grupo Dilady. Empresa possui mais de 50 anos de experiencia no segmento de moda intima e desenvolve com sucesso as marcas: Dilady Lingerie, Love Secret Lingerie, Banho de Mar Acqua Shape, Zero Barriga e Doctor Secret. E agora lanca sua nova Colecao no segmento de Moda Praia Masculina. Aproveite ao maximo suas aventuras aquaticas com um toque de elegancia e qualidade, com as Sungas Acqua Rio Praia. Composicao: Tecido: 86%Poliamida 14%Elastano Forro: 90%Poliester 10%Elastano.', 68.9, 68.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Swimming Attire', 'https://cf.shopee.com.br/file/sg-11134201-7rbnk-lo7932jy0td13b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308601970%2F23892383825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
