INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201839523', 'Estojo Fluffy Pelúcia Chapéu Seletor Harry Potter - DAC', 'Estojo Fluffy Pelúcia Chapéu Seletor Harry Potter - DAC O Estojo Fluffy Pelúcia Chapéu Seletor Harry Potter DAC é um item indispensável para fãs do bruxinho mais famoso do mundo. Inspirado no icônico Chapéu Seletor de Hogwarts, o estojo traz design detalhado em pelúcia marrom com textura macia e expressão bordada fiel ao personagem dos filmes. O formato tridimensional oferece excelente espaço interno para guardar lápis, canetas, borrachas e outros itens escolares, mantendo tudo bem organizado. Possui fechamento em zíper na parte frontal, que garante praticidade e segurança no uso diário. Além disso, acompanha uma elegante caixinha presenteável — ideal para colecionadores e apaixonados pelo universo mágico de Harry Potter. Ficha Técnica: Quantidade: 1 unidade Modelo: Chapéu Seletor (Harry Potter) Tipo: Estojo Fluffy Pelúcia Tamanho: 26 cm x 19 cm x 19 cm Material: Pelúcia macia e resistente Fechamento: Zíper frontal reforçado Compartimentos: 1 compartimento principal Textura: Fluffy (toque suave) Cor predominante: Marrom Acompanha: Caixinha presenteável Personagem: Chapéu Seletor (Harry Potter) Marca: DAC Palavras-chave: estojo chapeu seletor dac, estojo harry potter dac, estojo pelucia harry potter, estojo criativo harry potter, estojo fofo dac, estojo 3d harry potter, estojo presenteavel harry potter, papelaria harry potter, estojo personagens harry potter, presente geek harry potter, estojo escolar pelucia, estojo premium dac', 187.9, 187.9, NULL, 'Stationery > School & Office Equipment > Pencil Cases', 'https://cf.shopee.com.br/file/sg-11134201-822yg-mi5axujw0t8nc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1042749449%2F58201839523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699866094', 'Impact Pre Lavagem Vonixx 1,5l Limpa Motor E Caixa De Roda', 'O Impact Pre Lavagem 1,5l Limpa Motor E Caixa De Roda Vonixx é o produto perfeito para manter o motor e as caixas de roda do seu veículo sempre limpos e livres de sujeira. Com a marca Vonixx, referência em produtos automotivos, você pode confiar na qualidade e eficiência desse desengraxante.Fabricado no Brasil, o Impact Pre Lavagem é seguro de usar, pois não é inflamável. Sua fórmula especial foi desenvolvida para remover com facilidade a sujeira acumulada no motor e nas caixas de roda, deixando-os com aspecto de novos.Com um volume de 1500 mL, essa embalagem rende bastante e garante que você tenha produto suficiente para várias aplicações. Além disso, o desengraxante é muito fácil de usar, basta aplicar diretamente nas áreas desejadas e aguardar alguns minutos antes de enxaguar.Mantenha seu veículo sempre limpo e com um motor impecável com o Impact Pre Lavagem 1,5l Limpa Motor E Caixa De Roda Vonixx. Garanta já o seu e desfrute de um produto de qualidade que irá facilitar a sua rotina de limpeza automotiva.', 41.49, 41.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rdwg-md0svgwnwpxqc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151751638%2F18699866094', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
