INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294645095', 'Boia Redonda Ø 60cm - rosa', 'Com estampas sortidas com motivos aquáticos, cores alegres e vibrantes, a Boia Redonda tem tudo a ver com o verão. Diversão para os dias quentes de verão, vão acompanhar a garotada nas maiores aventuras nas águas das piscinas. Produzidas em PVC resistente, são pré-testadas, acompanha kit reparo, uma câmara de ar independente e uma válvula de segurança. São recomendadas para crianças de 3 a 6 anos. Atenção! Este não é um equipamento salva-vidas. Nunca deixe crianças sozinhas perto da água sem supervisão de um adulto.', 12.0, 12.0, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-825aw-mgftmqylxlhn23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23294645095', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
