INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19098023458', 'Paquímetro de Plástico Cortag 150mm/6" Mecânica Marcenaria', 'PAQUÍMETRO DE PLÁSTICO 150MM/6" - CORTAG ------------------------------------------------------------------------------------------- #cortag #paquimetroplastico #ferramentasdemedicao ------------------------------------------------------------------------------------------- O Paquímetro de Plástico Cortag 150mm/6" é a solução ideal para quem busca praticidade, precisão e leveza. Com um design ergonômico e resistente, ele oferece medições confiáveis para diversas aplicações, sendo recomendado para quem deseja um produto simples e eficiente para medições gerais. PRINCIPAIS CARACTERÍSTICAS: Medição precisa: Escala de 0 mm a 150 mm, com precisão de 0,05 mm. Leve e resistente: Produzido em plástico de alta resistência para maior durabilidade. Fácil de usar: Ideal para marcenaria, eletrônica, hobby e medições simples do dia a dia. Versátil: Indicado para medições internas, externas e de profundidade. ------------------------------------------------------------------------------------------- DÚVIDAS FREQUENTES O paquímetro é digital? Não, este modelo é mecânico e de leitura direta. O material do paquímetro é resistente? Sim, ele é produzido em plástico de alta resistência, garantindo leveza e durabilidade. Esse paquímetro pode ser usado para trabalhos profissionais? Ele é mais indicado para medições gerais e trabalhos simples. Para medições industriais de alta precisão, recomenda-se um modelo de aço inoxidável. #paquimetro #medicaoprecisa #ferramentaspraticas #paquimetromecanico #ferramentasdemarcenaria #medicaohobby #equipamentosdemedicao #paquimetroplastico #ferramentascortag', 28.9, 28.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5wt0vm9ipvpbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1350652530%2F19098023458', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19902944133', 'Memórias póstumas de Brás Cubas', 'É após a morte que Brás Cubas decide narrar suas memórias. Nesta condição, nada pode suavizar seu ponto de vista irônico e mordaz sobre uma sociedade em que as instituições se baseiam na hipocrisia. O casamento, o adultério, os comportamentos individuais e sociais não escapam à sua visão aguda e implacável, nesta obra fundamental de Machado de Assis.', 34.0, 32.3, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/2cb4873bc25774d096a57ec0d330e96b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F19902944133', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
