INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498883906', 'Sonda Lambda 4 Fios Universal Fiat / Chevrolet / Ford / Volkswagen ES10778', 'Sonda Lambda 4 Fios Universal Fiat / Chevrolet / Ford / Volkswagen ESPECIFICAÇOES TÉCNICAS: Cabo 95Cm Conector 4 Fios GASOLINA COMPATÍVEL COM OS MODELOS: Universal Chevrolet Universal Fiat Universal Ford Universal Volkswagen NUMERO ORIGINAL/SIMILAR: ES10778 / 7774 GARANTIA: 3 MESES DUVIDAS FREQUENTES: VOCÊS SÃO CONFIÁVEIS? R: SIM, BASTA OLHAR NOSSA REPUTAÇÃO E MEDALHA . PRESTAMOS UM ÓTIMO ATENDIMENTO E DESPACHAMOS OS PRODUTOS NO PRAZO. AS FOTOS DO PRODUTO SÃO REAIS? R: SIM, FOTO REAL DA PEÇA. A QUALIDADE DO PRODUTO É BOA? R: SIM, TODOS OS NOSSOS PRODUTOS SÃO NOVOS E COM GARANTIA. QUAL O PRAZO DE ENTREGA? R: VOCÊ PODE VERIFICAR O PRAZO DE ENTREGA NA TELA INICIAL ABAIXO DO PREÇO DO PRODUTO. VARIA DE REGIÃO PARA REGIÃO. DEVOLUÇÃO E TROCAS COMO FAZER? R: A DEVOLUÇÃO É GRÁTIS; VOCÊ PODE TROCAR O PRODUTO SE NÃO FICAR SATISFEITO (PRAZO DE 30 DIAS APÓS RECEBER). EM CASO DE GARANTIA COMO FAZER? R: EM CASO DE GARANTIA, ENTRAR EM CONTATO VIA CHAT PARA FAZER A TROCA DA PEÇA. POSSO RASTREAR MEU PEDIDO? R: SIM, APÓS A COMPRA, LIBERA O CÓDIGO DE RASTREAMENTO PARA VOCÊ ACOMPANHAR O PEDIDO EM TEMPO REAL ATÉ A CHEGADA. APÓS A COMPRA, PODEREI MADAR MENSAGEM PARA O VENDEDOR? R: SIM, APÓS A COMPRA CONFIRMADA, O CHAT É LIBERADO. ACESSE O CHAT NO MENU "MINHAS COMPRAS". O PRODUTO É COMPATÍVEL COM MEU VEÍCULO? R: OBSERVE QUE NA DESCRIÇÃO DISPONIBILIZAMOS A COMPATIBILIDADE DA PEÇA. SE O SEU VEÍCULO NÃO ESTIVER LISTADO, NOS FAÇA UMA PERGUNTA AQUI ABAIXO ENVIANDO MODELO E ANO QUE CONFIRMAREMOS A APLICAÇÃO. 04 de setembro de 2025', 154.49, 154.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-824id-me8jrx3rr4slb5', 'https://s