INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899317423', 'Módulo Amplificador Soundigital 800.1 Evo5 1 Canal 2 ou 4 Ohms', 'DANJASOM | Qualidade, confiança e envio rápido Módulo Amplificador SounDigital 800.1 EVO 5 O 800.1 EVO 5 na versão 2 Ohms é um amplificador monobloco com design compacto e tecnologia avançada, projetado para entregar potência consistente e áudio limpo em sistemas automotivos de baixa frequência. Ideal para subwoofers e aplicações que exigem alto desempenho com controle preciso e eficiência energética. Classe e Potência VERSÃO 2 OHMS Potência RMS @ 2 Ohms: 800W Potência RMS @ 4 Ohms: 535W VERSÃO 4 OHMS Potência RMS @ 2 Ohms: Não aplicável Potência RMS @ 4 Ohms: 800W Desempenho Sonoro: Resposta de frequência (-3dB): 10Hz ~ 20kHz Relação sinal-ruído (SNR): 2Ω: 96dB - 4Ω: 97dB Sensibilidade de entrada (RCA): 0.2V ~ 2V Sensibilidade de entrada alta: 1.5V ~ 15V Filtros e Recursos de Áudio: Filtro subsônico (HP 12dB/8): 10Hz ~ 80Hz Filtro passa baixa (LP 12dB/8): 50Hz ~ 20kHz Alimentação e Consumo: Tensão de alimentação: 8V ~ 16V Consumo com sinal musical: 2Ω: 40,8A - 4Ω: 38,7A Eficiência total: 2Ω: 79,4% - 4Ω: 78,9% Conexões e Cabos Recomendados: Cabo de alimentação: 10mm² (7 AWG) Cabo de saída de áudio: 2 x 2.5mm² (13 AWG) Fusível recomendado (uso musical): 40A Bateria recomendada (mínimo para uso musical): 60Ah Dimensões e Peso: Largura: 11.3 cm Comprimento: 14.8 cm Altura: 5.1 cm Peso: 0.75 kg DANJASOM ¬ Distribuidor oficial das maiores marcas ¬ Todos os produtos com NOTA FISCAL ¬ Envio rápido e seguro ¬ Garantia direto do fabricante Em caso de dúvidas, utilize o chat e converse conosco — nossa equipe está pronta para ajudar você a montar seu projeto com segurança e performance.', 529.0, 486.67, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkcuulizgdmr96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F901722804%2F23899317423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
