INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200333024', 'Kit 10 Cuecas Zorba Boxer Max Algodão 702', 'DESCRIÇÃO: Kit com 10 Cuecas Zorba Boxer Algodão Max. 100% Algodão. Possui a tecnologia Go Tagless, sem etiquetas costuradas, não arranha e não irrita a pele. Veste do P ao XGG. Cueca com a tecnologia Maxfresh: Regula a sensação térmica. Protege contra odores e bactérias. Tecnologia Seamless: Sem costura nas laterais. Ajuste perfeito ao corpo. COMPOSIÇÃO: 100% algodão. | Mescla: 88% Algodão, 12% Poliéster PAÍS DE ORIGEM: Brasil. INSTRUÇÕES DE LAVAGEM: Temperatura máxima de lavagem 30ºC; processo suave; não alvejar; não secar em tambor; secagem em varal por gotejamento a sombra; temperatura máxima da base do ferro a 110ºC sem vapor; não limpar a seco. INDICAÇÃO: Dia a dia. CONTÉM: 01 kit com 10 unidades. TABELA DE MEDIDAS: P – 38 ao 40 - Cintura entre 76 e 80 cm M – 42 ao 44 - Cintura entre 84 e 88 cm G – 46 ao 48 - Cintura entre 92 e 96 cm GG – 50 ao 52 - Cintura entre 100 e 104 cm XG – 54 ao 56 - Cintura entre 108 e 112 cm XGG – 58 ao 60 - Cintura entre 116 e 120 cm Caso sua medida esteja no intervalo das medidas entre um tamanho e outro, considerar o tamanho maior.', 294.9, 294.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-821g8-mgo3j3v6wydna4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F421856066%2F58200333024', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
