INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18745625828', 'PARAQUEDAS DE RESISTENCIA', 'O Paraquedas de resistência da WCT Fitness é um equipamento excelente para condicionamento físico e treinamento de força e velocidade sem necessidade de uma segunda pessoa para realizar o treinamento. Ideal para treinamentos esportivos, como prática de aceleração explosiva, para esportes como futebol, tênis, rugby, etc. Ajuda a fortalecer os músculos dos membros inferiores e core, desenvolvendo a forca e resistência do atleta. Fabricado em nylon de alta resistência, podendo ser utilizado em qualquer ambiente, interno ou externo. Ele é Preto com Branco com 57 Polegadas. Acompanha uma bolsinha para estar carregando o paraquedas. Acompanha uma fita que já vai anexada no paraquedas com 1,30m, para estar tendo mais resistência, e mais durabilidade do produto.', 89.9, 75.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/af175cc2bdeaf1f9e772f7ea7c317c50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F504750919%2F18745625828', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
