INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18198245179', 'Sapata De Freio Traseira Fiat Strada 1.4 De 2003 A 2014 Fire', 'IDEAL AUTO PARTS Desde 1990 IDEAL PARA SEU CARRO Sapata Freio Traseira FRASLE APLICAÇÃO FIAT Brava 1.6 16v De 2002 A 2004 Fiorino De 1994 A 2001 Idea De 2006 A 2010 Marea 1.6 16v De 2006 A 2010 Marea 1.8 16v De 2006 A 2010 Palio Weekend 1.0 De 1997 A 2000 Palio Weekend 1.3 De 1997 A 2000 Palio Wekkend 1.5 De 1997 A 2000 Palio Weekend 1.6 De 1997 A 2000 Palio Weekend Adventure De 1999 A 2004 Strada De 1999 A 2008 Tempra De 1992 A 1998 Uno Turbo 1.4 8v De 1994 A 1996 MEDIDAS: 228 X 42mm APLICA SE PARA SISTEMA FREIO BOSCH/BENDIX FRASLE FI91CP CONTEÚDO DA EMBALAGEM 04 SAPATA FREIO TRASEIRA QUALIDADE Produto Novo GARANTIA 03 Meses De Garantia NOTA FISCAL Sim SUPORTE PÓS VENDA Sim SOBRE A IDEAL AUTO PARTS Fundada em 1990, somos uma empresa do ramo de comércio e varejo de peças novas para veículos automotores. São mais de 30 anos oferecendo peças reconhecidas nacionalmente e internacionalmente com os melhores preços do Brasil. A paixão por automóvel e o crescimento do mercado, contribuiu para a expansão da marca e hoje contamos com quatro endereços físicos, localizados em pontos estratégicos na cidade de Limeira, Artur Nogueira e Rio Claro, no interior de São Paulo. Contamos com uma equipe especializada para prestar o melhor atendimento e oferecer exatamente o que nosso cliente precisa. São mais de 35 mil Itens de diversas montadoras a disposição em nossas lojas. CASO TENHA ALGUMA DÚVIDA USE O CAMPO DE PERGUNTAS, ESTAREMOS A DISPOSIÇÃO PARA TE ATENDER', 161.9, 161.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rav9-mamsa9rtlnbkeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F433880234%2F18198245179', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22999414332', '365 HÁBITOS SIMPLES E PODEROSOS', 'Se você está lendo este texto, é porque está determinado a transformar a sua vida! Já se questionou por que algumas pessoas alcançam o sucesso enquanto outras não? E se eu revelar que há hábitos comuns entre essas pessoas bem-sucedidas? Hábitos que você pode começar a incorporar em sua vida a partir de hoje. Será fácil? Não, a construção de hábitos bem-sucedidos exige foco, disciplina e uma grande dose de determinação. Ao longo do processo, você enfrentará diversos desafios, desde pessoas que não torcem pelo seu sucesso até a resistência do seu próprio cérebro, que tentará persuadi-lo a economizar energia. Acreditar em si mesmo é crucial! Não existem atalhos para acelerar o percurso da evolução; é um progresso de degrau em degrau. Faça a d', 33.36, 33.36, NULL, 'Books & Magazines > Books > Careers, Self Help & Personal Development', 'https://cf.shopee.com.br/file/sg-11134201-8260g-mlwb1kvu9k3n8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F22999414332', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397661052', 'Sandália Infantil Feminina Rasteirinha Super Delicada Napa Borboleta Encantada Dourada Metalizada', 'TABELA DE MEDIDAS N° 25 - 17.5 cm N° 26 - 18 cm N° 27 - 18.5 cm N° 28 - 19.5 cm N° 29 - 20 cm N° 30 - 20.5 cm N° 31 - 21.5 cm N° 32 - 22 cm N° 33 - 22.5 cm DESCRIÇÃO Olha só que delicadeza esse modelinho, uma verdadeira joia para os pés! Ideal para usar com calça, saia, vestido, jeans, camisetas, blusas neutras e estampadas. Ótima opção para montar conjuntos casuais e dia a dia. Por se tratar de um modelo básico e bastante clássico, ele tem a versatilidade e facilidade de se encaixar com as suas roupas, assim, você aproveita mais os estilos sem precisar renovar suas peças. Vem com a sola produzida em EVA macio o que ajuda a reduzir o impacto na pisada e proporciona mais conforto. LIMPEZA E CONSERVAÇÃO Evite usar substâncias abrasivas como álcool, detergentes ou solventes nos calçados. Nunca mergulhe na água ou os deixe de molho ou lave na máquina. A secagem dos produtos deve ser feita à temperatura ambiente e na sombra, nunca no sol ou em máquinas.', 99.9, 78.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8owie2w7de9b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296584125%2F22397661052', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
