INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43531963560', 'Garrafa Alumínio Lilica Ripilica 500ml Com Canudo Rígido - Pacific', 'A garrafa de alumínio da Lilica Ripilica, fabricada pela Pacific, é uma escolha prática e divertida para crianças que adoram a encantada lilica. Feita de alumínio, ela é leve e durável, sendo uma excelente opção para o uso diário, seja na escola, em passeios ou durante atividades esportivas. Além de apresentar uma estampa vibrante e atraente da personagem Lilica, a garrafa também é fácil de limpar e ajuda a manter a temperatura da bebida por mais tempo. CARACTERÍSTICAS: - Marca: Pacific - Tema: Lilica Ripilica - Material: Alumínio e Plástico Injetado - Capacidade: 500 ml - Idade recomendada: +12 meses - BPA Free - Canudo Rígido - Bico ergonômico de fácil uso - Resistente e ideal para uso diário - Peso: 100g - Dimensões da Embalagem (LxCxA): 7cm x 8cm x 21cm - Dimensões do Produto (LxCxA): 8cm x 8cm x 20cm', 59.99, 59.99, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-820m2-mputd9xos1s0ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F43531963560', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8117131507', 'Câmbio Traseiro Shimano RD-TY300 6 / 7v', 'Câmbio Traseiro Shimano Tourney Ty300 6 a 7 Velocidades. Utilizando a tecnologia do índice SIS e uma gaiola mais longa para um tamanho máximo da coroa é de 40 dentes, o câmbio traseiro Shimano Tourney está otimizado para aplicações de montanha, rodovias ou de turismo onde a confiabilidade e a versatilidade são fundamentais. • Indicação de Uso: Mtb, Cicloturismo, Urbano. • Mudança suave e confiante. • Mecanismo servo-panta duplo. • Montagem rápida e fácil • Porca de fixação do cabo interno pré-montada Especificações: Marca: Shimano; Linha: Tourney; Modelo: RD-TY300; Cor: Preto; Capacidade máxima cassete/roda livre: 34D; Peso aproximado: 315g; Compatibilidade de 6/7 velocidades; Corrente Shimano compatível: HG / UG 6/7.', 109.9, 102.21, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/c3864c14546516b7746b94fee3d5c708', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389286080%2F8117131507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599255201', 'Dazzle Deo Colônia 60ml', 'Fragrância Feminina Dazzle Hinode A Fragrância Feminina Dazzle Hinode é marcante, com uma exuberante explosão de frutas vermelhas, framboesa, morango e cereja, que causam um frescor sustentado por um acorde de bergamota. As notas de seu corpo foram selecionadas à base da flor de laranjeira, jasmim e rosa vermelha. De forma misteriosa e perturbadora, as notas de fundo sândalo, baunilha, âmbar, musk e fava tonca revelam com graciosidade a fragrância Dazzle. FAMÍLIA OLFATIVA: Oriental Vanilico NOTAS OLFATIVAS: Saída: Bergamota, Frésia, Frutas Vermelhas, Violeta Corpo: Marshmallow Stt, Rosa, Peônia, Jasmim Fundo: Cedro, Musk, Baunilha, Âmbar', 129.9, 129.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134201-820lj-mqxe15omo7wn3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F876865394%2F20599255201', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
