INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193657037', 'Protetor Facial Sunless FPS 50 Stick Translúcido 12g', 'Carcterísticas do produto: Marca: Sunless Ean: 7896902288140 Peso: 12g FPS: 50 Informações adicionais: Proteção: Alta contra raios UVA e UVB Indicação: Peles muito sensíveis à queimadura solar Fórmula: Translúcida e adaptável a todos os tons de pele Ação: Antioxidante e antissinais Benefícios: Não comedogênico (não obstrui os poros) Testes: Testado dermatologicamente Uso: Cuidado diário, proteção e prevenção do envelhecimento precoce Modo de Uso: Aplicar generosamente sobre a pele antes da exposição ao sol. Reaplicar conforme necessário, especialmente após nadar, suar ou se secar com toalha Precauções: Manter fora do alcance de crianças e animais Proteger da luz solar direta e do calor excessivo Em caso de contato direto com os olhos, enxágue com água em abundância Se ocorrer irritação na pele, suspenda o uso e consulte um médico A reaplicação é necessária para manter a efetividade Evite exposição prolongada ao sol, principalmente em crianças Em contato com tecidos, pode causar manchas Fornecedor: FARMAX DISTRIBUIDORA SA', 64.53, 64.53, NULL, 'Beauty > Others', 'https://cf.shopee.com.br/file/sg-11134201-824if-mpibd29g3xfv73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F22193657037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497838391', 'Sabonete Cremoso Facial Sens Herbalis Hinode 250ml', 'Descubra a Pureza e Suavidade do Sabonete Cremoso Facial Sens Herbalis 250ml Introduzindo o Sabonete Cremoso Facial Sens Herbalis 250ml, sua nova escolha para uma pele impecavelmente limpa e hidratada. Criado com uma fórmula exclusiva, este sabonete facial é perfeito para quem busca uma limpeza profunda sem comprometer a hidratação natural da pele. Enriquecido com extratos naturais e óleos essenciais, ele oferece uma experiência de limpeza suave e eficaz, respeitando o equilíbrio do pH da sua pele. Este sabonete não é apenas um produto de limpeza; ele é um tratamento diário que deixa sua pele com uma sensação de frescor e uma fragrância suave que acalma os sentidos. Ideal para todos os tipos de pele, especialmente as mais sensíveis, o Sabonete Cremoso Facial Sens Herbalis é a escolha perfeita para quem valoriza produtos com ingredientes de qualidade e resultados comprovados. Características Textura Cremosa: Proporciona uma sensação aveludada e confortável durante a limpeza. Componentes Naturais: Formulado com extratos de plantas e óleos essenciais cuidadosamente selecionados. pH Balanceado: Mantém a integridade e a saúde da barreira cutânea. Benefícios Hidratação Profunda: Ingredientes hidratantes que nutrem a pele, deixando-a suave e radiante. Limpeza Suave: Limpa eficazmente sem despojar a pele de seus óleos naturais. Tratamento e Prevenção: Auxilia no tratamento de condições da pele, promovendo uma aparência saudável e revitalizada. Diferenciais Fórmulas Enriquecidas: Contém vitaminas e antioxidantes que protegem e revitalizam a pele. Aromaterapia: Oferece uma experiência olfativa relaxante e terapêutica com sua fragrância suave. Eco-Amigáveis: Compromisso com o meio ambiente através de embalagens recicláveis e ingredientes sustentáveis. Recomendações Para resultados ótimos, use o Sabonete Cremoso Facial Sens Herbalis duas vezes ao dia, pela manhã e à noite. Após o uso, sinta sua pele revitalizada, suave e pronta para receber outros produtos de cuidado facial. Não esqueça de complementar sua rotina com um hidratante adequado ao seu tipo de pele. Transforme sua rotina de cuidados faciais com o Sabonete Cremoso Facial Sens Herbalis 250ml e sinta a diferença de uma pele profundamente limpa, hidratada e saudável. Adquira já o seu e comece a desfrutar de uma pele mais bonita e cuidada todos os dias!', 32.9, 32.9, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rdyo-m0k8p3r4124k41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F876865394%2F23497838391', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
