INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211181191', 'KIT 2 Pneus Forceland Vitality F22 205/55R17 Aro 17 95W XL', 'KIT 2 Pneus Forceland Vitality F22 205/55R17 Aro 17 95W XL Aumente a sua segurança com a avançada tecnologia do Pneu Forceland Vitality F22 205/55R17 Aro 17 95W XL. Este pneu proporciona distâncias de frenagem seguras e uma aderência superior, proporcionando-lhe tranquilidade ao volante. O índice de velocidade W indica especificamente uma capacidade de velocidade máxima de até 270 Km/h, enquanto o índice de carga máximo é indicado por 95 (690 Kg).', 1192.97, 778.08, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-823pv-moirk9y3ksg1f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F540643031%2F58211181191', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
