INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15152546751', 'Ração Premier Nattu para Cães Adultos de Pequeno Porte Sabor Abóbora - 2,5Kg', 'Pensada para proporcionar uma alimentação cada vez mais saudável para seu melhor amigo, a linha PremieR Nattu possui ingredientes selecionados, nutritivos e satisfação comprovada. Com uma fórmula sem corantes e aromatizantes, PremieR Nattu Abóbora é recomendado para a alimentação de cães adultos de pequeno porte e traz em sua base de ingredientes Frango, Abóbora, Brócolis, Quinoa e Blueberry, itens de alta densidade nutricional, que oferecem muitos nutrientes e poucas calorias, proporcionando uma dieta mais equilibrada para seu cão. Uma exclusividade deste alimento são os ovos utilizados na formulação, provenientes do sistema de criação Cage Free, no qual as aves possuem liberdade de movimento, com acesso a ninhos, permitindo assim sua total locomoção. Se você busca o alimento certo para uma dieta natural e repleta de benefícios para seu pet, não deixe conhecer todos os produtos de nossa linha Nattu.', 146.35, 117.08, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/18c18882b6af26a59dcc0168411cc23c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438604073%2F15152546751', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
