INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599325809', 'Aquecimento global não dá rima com legal', 'Neste livro você vai conhecer, de uma maneira bem diferente, o tema do aquecimento global. Suas causas, consequências e soluções são contadas por meio de diversas modalidades de estrofes da literatura de cordel. Além disso, textos escritos em prosa vão aprofundar seus conhecimentos para além das geleiras derretidas, dos ciclones e da vida dos ursos polares. Nesta segunda edição, além da atualização das informações, foi acrescentado conteúdo sobre o desmatamento da Floresta Amazônica, questões relacionadas às terras indígenas e aos saberes ancestrais da floresta, além de dados sobre bioconstrução e agricultura orgânica.', 77.3, 77.3, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdy7-lxq7tuzpf2qnd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F21599325809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799549654', 'Par de Palhetas Limpador Parabrisa Multiclip Original Bosch Ford Transit 2008 A 2011', 'Par de Palhetas Dianteiras Limpador Parabrisa Multiclip Original Bosch A alta performance ficou ainda melhor. Palhetas que garantem mais Eficiência, Segurança, Durabilidade e Qualidade. Se é BOSCH, pode confiar. Enxergue o que vem pela frente. Kit composto por: - 1 Palheta Multiclip lado direito BOSCH Aerofit Original - 1 Palheta Multiclip lado esquerdo BOSCH Aerofit Original Medidas: - Palheta motorista: 26" (65 cm) - Palheta Passageiro: 22" (55 cm) - Use o adaptador 1 - Montagem 1A Compatível com: - Transit 2008 - Transit 2009 - Transit 2010 - Transit 2011 Características: - Palheta BOSCH Aerofit Multiclip Original - Instalação mais fácil e segura. - Maior durabilidade e eficiência comprovadas. - Sem partes metálicas expostas. Livre de desgastes de pintura e corrosão. - Spoiler aerodinâmico para ter uma distribuição uniforme de força, mantendo a varredura eficiente mesmo em altas velocidades. - Maior estabilidade em todas as situações de uso. - Funcionamento ultra suave, devido ao seu tratamento de grafite, para um movimento sem ruídos ou trepidações. - Nova embalagem moderna e atrativa. Perguntas Frequentes: Quando devo trocar as Palhetas do meu carro? - A troca deve ser realizada aos primeiros sinais de desgaste nas Palhetas. Isso porque o componente com desgaste tem a eficiência comprometida e atrapalha a visibilidade. Quais os sinais de desgaste da palheta? - Os sinais de uma Palheta com desgaste são: a Palheta não retira todo o excesso de água, faz barulho durante o funcionamento, risca o parabrisa do carro, lâmina de borracha torta, quebrada ou ressecada. Qual o prazo para a substituição das Palhetas? - Substitua as Palhetas pelo menos uma vez por ano. As Palhetas são originais? - Sim. Somos fornecedores autorizados BOSCH. Todos os produtos são originais e acompanham Nota Fiscal. Observação: - Em caso dúvidas sobre o modelo correto da Palheta para o seu carro, faça uma pergunta na parte inferior do anúncio. Temos uma equipe especializada para tirar as suas dúvidas. - O limpador de parabrisa é um acessório obrigatório por lei (artigo 230, XIX, do CTB). O não funcionamento perfeito ou mau uso do mesmo, é caracterizado como infração grave, com direito a multa e retenção do veículo. Mantenha a sua família segura. Compre Palhetas Originais BOSCH Aerofit.', 159.97, 139.18, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7repk-m1yi82yb32n65c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F999741980%2F21799549654', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
