INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994334368', 'LICOR BALLENA CHOCOLATE E CARAMELO 750ML', 'Em 1905, na costa mediterrânea espanhola, foi avistado um animal que se parecia com um peixe, mas que respirava ar e dava leite para os seus filhotes. Um bicho enorme e rosado, mas ao mesmo tempo doce e fofo. García, o pescador mais antigo da região, costumava usar iscas banhadas com tequila, em um belo final de tarde se deparou com o enorme animal. O pescador impressionado, logo percebeu que seria impossível pescar e resolveu alimentá-lo com suas iscas temperadas. Isso ligou os dois pra sempre! O enorme animal passou a voltar todo final de tarde para comer as iscas do pescador, que o apelidou carinhosamente de Ballena. O novo sabor de licor Balena é uma deliciosa mistura do sabor de chocolate e caramelo, a pegada da tequila e a cremosidade do leite, assim formam esse licor fino que é a sensação do momento. Feito para ser apreciado puro bem gelado, em shots', 177.9, 120.99, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdon8d9o8xix84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F22994334368', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
