INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19306832615', 'Motor Partida Arranque Honda Cg Titan Fan Xlr Nxr Bros 125 150 Cbx Nx Xr 150 200 Original Magnetron', 'PREÇO REFERENTE A UMA UNIDADE DE MOTOR DE ARRANQUE CÓDIGO: 90205520 MARCA: MAGNETRON ______________________________________________ APLICAÇÕES: • HONDA XR 200 R | 1994 ATE 2002 CG 125 TITAN ES | 2000 ATE 2004 CG 125 TITAN KSE | 2002 ATE 2004 NXR 125 BROS ESN | 2003 ATE 2005 NX 150 | 1989 ATE 1992 NX 200 | 1993 ATE 2001 XLR 125 | 1996 ATE 2002 XLR 125 ES | 2000 ATE 2002 NXR 150 BROS ESD | 2003 ATE 2005 CBX 150 AERO | 1989 ATE 1992 CBX 200 STRADA | 1994 ATE 2002 _____________________________________________ OBSERVAÇÕES IMPORTANTES: * Produto com garantia de 3 meses. * Produto novo na caixa. * Produto em estoque e com envio em imediato. * Recomendamos que os produtos sejam instalados por profissionais especializados FUNÇÃO: O motor de partida tem a função de dar início à partida da motocicleta, substituindo o pedal de partida. ATENÇÃO SE... O motor de partida não aciona ou gira muito devagar; • Você ouve um estalo quando o motor de partida funciona; • Aparecem ruídos estranhos ao ligar o motor de partida; • O motor de partida aciona, mas o motor a combustão não. Se você notar que existe alguns dos problemas listados acima no sistema de partida, a primeira dica é não sair trocando peças antes de consultar um especialista, durante a manutenção. E escolher peças de qualidade. Assim o serviço será bem executado você poderá rodar tranquilo por muito tempo.', 234.0, 180.14, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwfsq7bvltx10a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F780646899%2F19306832615', NULL, NULL, '2026-07-28T02:11:31.708458+