INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297780477', 'Cabeceira Estofada Cama King 195 Cm Luísa Suede E Frame marrom', 'Cabeceira Estofada Cama King 195 Cm Luísa Suede E Frame Cor:marrom Transforme sua decoração com a elegância da Cabeceira Estofada King Size Carla! Ideal para quem busca estilo e conforto, a Cabeceira Cama King Carla é o toque perfeito para o seu quarto. Com um design único e detalhes que encantam, a Cabeceira Alta Carla é a escolha certa para acompanhar sua cama e garantir momentos de relaxamento ainda mais aconchegantes. Seja para apoiar as costas enquanto lê um livro ou assistir TV, ela proporciona conforto incomparável. Fabricada com materiais de alta qualidade, como madeira eucalipto e revestimento em suede, esta cabeceira é durável e resistente, garantindo não apenas estilo, mas também funcionalidade para o seu ambiente. Não perca tempo! Adquira já a sua Cabeceira Moderna Carla e transforme seu quarto em um espaço ainda mais acolhedor. Aproveite agora mesmo! Dimensões: Altura: 126 cm Largura: 195 cm Profundidade: 10 cm Altura dos pés: 13 cm Peso: 13 Kg Especificações do Produto: Estrutura: Madeira Eucalipto de alta qualidade Tecido: Suede Espuma: D-20 Material dos pés: Plástico Acompanha o kit frame Os parafusos para fixação do frame e os pés serão enviados dentro do forro, na parte de trás da cabeceira Montagem: O produto vai montado, necessitando apenas rosquear os pés (2) Instruções de Limpeza: Utilizar um pano limpo e levemente úmido Você irá receber: 01 volume Observações Relevantes: Produto para uso residencial em ambiente interno, não devendo ficar exposto diretamente ao sol, calor e umidades excessivas; As imagens são meramente ilustrativas, não acompanham objetos de decoração e eletros; Cabeceira Casal Cabeceira Queen Cabeceira de cama Cabeceira capitonê Cabeceira king de madeira Cabeceira rústica king Cabeceira retrô king Cabeceira sob medida king Cabeceira king MDF', 407.33, 407.33, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rdxr-m020soqcwqi605', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22297780477', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22499454761', 'Danone Morango Iogurte Líquido', 'O iogurte líquido Danone de morango é perfeito para o dia a dia da sua família, pronto para consumo e feito com frutas naturais. Fonte de cálcio e vitaminas C e D. Esta embalagem supereconômica de 1,25kg em garrafa é ideal para quem busca praticidade e sabor em um só produto. Agite antes de beber e mantenha resfriado após aberto.', 20.79, 20.79, NULL, 'Food & Beverages > Dairy & Eggs > Yogurt & Cultured Milk', 'https://cf.shopee.com.br/file/sg-11134201-825b1-mqneli7yjdabc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703290516%2F22499454761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698402041', 'Máquina De Waffle Pratic Gw-01 Grill 220V-Preto/Inox', 'Máquina De Waffle Mondial Pratic Waffle Gw-01 Grill Waffle-220v-preto/inox Preparo fácil e divertido o Grill Waffle - Pratic Waffle da Mondial, é prático e versátil, prepara 4 waffles deliciosos para toda família, sendo tradicional, doces, salgados, pão de queijos e outras receitas. Possui design sofisticado com acabamento em inox, chapas antiaderentes que impedem o alimento de grudar, facilitando o preparo e a limpeza. O aparelho Pratic Waffle Mondial, possui 1200 W de potência, mantém as chapas aquecidas por iguais. Seu controle de temperatura ajustável permite deixar a temperatura ideal e garantir melhores resultados. Possui alça fria e guarda fio, podendo guardar o produto na vertical, economia de espaço no armário. Lâmpada-piloto, ajuda no indicamento do funcionamento. Acompanha livro de receitas - para preparar deliciosas receitas com alegria em família. 1 ano de garantia. Modelo - GW-01 Cor - Preto/Inox Voltagem (Tensão) - 220V Potência - 1200w Capacidade - 04 waffles Prepara quais alimentos - Doces, salgados, pão de queijos e outras receitas Revestimento - Antiaderente Trava de segurança - Não Luz indicadora - Sim Tempo de Preparo - Não se aplica Dimensões do produto - 25,80cm x 21,80cm x 10,80cm (AxLxP) Peso do produto - 1,500kg Garantia - 01 ano', 139.9, 139.9, NULL, 'Home Appliances > Kitchen Appliances > Specialty Cookware', 'https://cf.shopee.com.br/file/sg-11134201-7rep3-m8nt72lvfpqt3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23698402041', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202419583', 'Par Alto Falante Pioneer Quadriaxial TS6990BR 6x9Pol 4Ohms 150WRms', 'Par Alto Falante Pioneer Quadriaxial TS6990BR 6x9Pol 4Ohms 150WRms O TS-6990BR é o novo alto-falante da Pioneer. Com visual moderno e sofisticado e alta potência, você ouve suas músicas preferidas com mais peso e qualidade sonora. O modelo possui um conjunto de mid-range e tweeters que regulam e alinham a faixa de frequência, além de ter um conjunto magnético poderoso, ideal para potências elevadas e que se encaixa perfeitamente ao estilo do seu carro. Especificações: • Potência RMS - 150 W • Resposta em frequência – 40 Hz a 20.000 Hz • Sensibilidade (1 W/1 m) – 88 dB • Impedância – 4 ohms Dimensões: • Profundidade de instalação – 87 mm • Dimensões do alto-falante (sem tela) – 234 x 164 x 103 mm • Dimensões do alto-falante (com tela) – 264 x 184 x 116 mm • Dimensões para corte – 218 x 148 mm Conteúdo da embalagem: • 1 par de alto-falantes • 1 par de telas de acabamento • 8 parafusos • Certificado de garantia • Lista de postos de assistência técnica', 386.0, 319.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-81z1k-miovok1iummaa9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411081274%2F58202419583', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393279676', 'Papel Higiênico Interfolhado Premium Folha Dupla com 7.440un Tork', 'O refil Tork Premium Higiênico Interfolhado tem a suavidade de um produto premium, com 100% fibra virgem, sendo um papel de folha dupla, suave e macio. Cor: Branco Tipo: Cai Cai / Folha dupla Medidas por unidade: 11 x 20,5 cm Compatível com: Cód: 101333 - Dispenser Higienico Interfolhado Branco Tork (Sistema T3) Cód. de Fábrica: 0801556000 Cód.: 116672 - Dispenser Higienico Interfolhado Preto Tork (Sistema T3) Cód. de Fábrica: 0801556008 Embalagem: Caixa com 7.440 folhas (12 pacotes com 620 folhas cada)', 390.74, 390.74, NULL, 'Home & Living > Home Care Supplies > Toilet Paper', 'https://cf.shopee.com.br/file/sg-11134201-7rdvp-m036pc8koaufce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F22393279676', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
