INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993949880', 'Chocolate ao Leite Profissional Barra 2,1kg SICAO', 'O Chocolate Ao Leite Barra Profissional desenvolvido para facilitar o trabalho de confeiteiros e chocolatiers. De fácil temperagem e alto rendimento, oferece excelente desempenho em diversas aplicações: ideal para moldar bombons, cobrir trufas, banhar produtos e criar decorações com acabamento brilhante e textura lisa. Possui sabor suave e equilibrado de leite com cacau, derrete uniformemente e proporciona ótimo resultado tanto em pequenas produções quanto em larga escala. Embalado em barra de 2,1 kg, é uma escolha recomendada tanto para profissionais quanto para quem produz em casa, pois oferece versatilidade, rendimento e facilidade no manuseio. Ingredientes: Açúcar, gordura vegetal, manteiga de cacau, massa de cacau, cacau em pó, leite em pó integral, soro de leite em pó, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E DE SOJA. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN. INFORMAÇÃO NUTRICIONAL - Porção de 100g Valor Energético: 524kcal Carboidratos: 62g Açúcares Totais: 59g Açúcares Adicionados: 55g Proteínas: 4,2g Gorduras Totais: 28g Gorduras Saturadas: 17g Gorduras Trans: 0g Fibras Alimentares: 3,2g Sódio: 33mg', 212.09, 205.73, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-7rfg0-m9ivhdj5yln956', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F23993949880', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
