INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593989376', 'Kit Corretivo 20 + Pó Facial Retinol Matte Payot', 'Kit Corretivo 20 + Pó Facial Retinol Matte Payot, contém: 1- Corretivo Sérum Retinol Payot - Cor 20 O Corretivo Sérum Retinol é maquiagem e tratamento cosmético em um só produto. Com ativos como Retinol Vegetal*, Niacinamida, Pantenol e Biocolágeno*, que ajudam a minimizar a aparência de rugas, linhas de expressão. Disfarça imperfeições, olheiras, sinais de cansaço e uniformiza o tom da pele. Possui cobertura média, com acabamento de efeito natural, rápida absorção e sem craquelar. Para todos os tipos de pele. 1- Pó Facial Retinol Payot Cor: Matte Sua textura ultrafina, confere acabamento natural e translúcido sem destacar linhas de expressão. Controla o brilho excessivo e a oleosidade ao longo do dia. Fixa, sela e proporciona uma finalização perfeita da maquiagem. O Pó Facial Retinol é a combinação perfeita de maquiagem e tratamento cosmético em um só produto. Sua fórmula com Retinol Vegetal, Óleo de Rosa Mosqueta e Vitamina E, hidrata a pele, possui ação antioxidante e disfarça imperfeições e linhas de expressão. Para todos os tipos de pele. Produto vegano. Não testado em animais. Livre parabenos e fragância. *Retinol Vegetal - extrato obtido da planta Bidens pilosa. Atua de forma semelhante aos retinóis sintéticos.', 140.9, 123.99, NULL, 'Beauty > Makeup > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfh0-m9ukgk93xwv61d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F619779318%2F22593989376', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
