INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23822520144', 'Escapamento Escape Gemoto Moto Honda Titan Esd Ex 150 2009 A 2013 Fan 150 Mix Esdi Ml 2 Abafadores', 'O Escapamento ML Gemoto foi projetado com tecnologia de primeira linha, este modelo oferece mais ganho de fluxo na exaustão e garante respostas mais rápidas a sua motocicleta, além de oferecer um ronco único acordo com as normas regulamentadoras de fabricação. Especificações: - Disponível nas cores: Cromado, Preto; - Produzido em aço de alta qualidade e resistência; - Modelo: ML 2 Abafadores; - Marca: Gemoto. Aplicações: - TITAN ESD - EX 150 2009 - 2013 / FAN 150 MIX ESDI; Dicas: - A instalação deve ser feita por um profissional especializado. A Gemoto não se responsabiliza por instalação mal realizada; - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa-se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação.', 205.16, 187.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/br-11134201-820lz-mqy841hkwzk696', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F23822520144', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
