INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22809190673', 'Escapamento Moto Steel Technology Powercore 3 Pro Tork Compatível Com CRF 230F 2007 a 2020', 'Uma nova versão do renomado escapamento Powercore 3, vem ai o modelo Steel Technology. Produzido em aço carbono, entrega excelentes níveis de potência para motocicletas street e off road, com a melhor relação custo/benefício do mercado. O projeto contempla tubos bem dimensionados, garantindo maior potência em baixas, médias e altas rotações, além de retomadas certas nas saídas de curvas. Acabamento de primeira qualidade, banhado no melhor cromo do mercado e soldas reforçadas. sem falar no design agressivo que confere um belo visual. Tudo testado em dinamômetro e também nas pistas. Especificações: - Powercore 3 modelo Steel Technology; - Material: Aço carbono; - Acabamento feito em Titanium; - Ronco esportivo; - Design agressivo; - Pronto para instalação; - Sistema de dobras Omniex que permite a vazão dos gases em alta velocidade; - Curva com Sistema Bomber; - Marca: Pro Tork. Aplicações: - Crf 230F 2007; - Crf 230F 2008; - Crf 230F 2009; - Crf 230F 2010; - Crf 230F 2011; - Crf 230F 2012; - Crf 230F 2013; - Crf 230F 2014; - Crf 230F 2015; - Crf 230F 2016; - Crf 230F 2017; - Crf 230F 2018; - Crf 230F 2019; - Crf 230F 2020. Instalação: - A instalação deve ser feita por um profissional especializado. A Sportbay não se responsabiliza por instalação mal realizada; - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa-se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação.', 410.42, 262.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgc9cwxo2i2t86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2